CREATE OR REPLACE FUNCTION local_identity.account_directory_busy(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;f record;rejected uuid[]:='{}';unknowns uuid[]:='{}';table_rejected uuid[];table_unknown uuid[];BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.account_memberships WHERE account_id=p_account AND user_id=local_identity.owner_id() AND role='owner') THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 -- A definite rejection may leave the paid ledger at submitting. Inspect all
 -- submission protocols first; any started/received evidence outweighs rejection.
 FOR f IN SELECT c.table_name FROM information_schema.columns c WHERE c.table_schema='local_identity' AND c.column_name='outcome' AND c.table_name LIKE '%submissions' LOOP
  EXECUTE format('SELECT coalesce(array_agg(DISTINCT s.task_id) FILTER(WHERE s.outcome=''rejected''),''{}''::uuid[]),coalesce(array_agg(DISTINCT s.task_id) FILTER(WHERE s.outcome IN (''started'',''received'')),''{}''::uuid[]) FROM local_identity.%I s JOIN public.tasks t ON t.id=s.task_id JOIN public.episodes e ON e.id=t.episode_id WHERE e.account_id=$1 AND t.status<>''completed''',f.table_name) INTO table_rejected,table_unknown USING p_account;
  rejected:=rejected||table_rejected;unknowns:=unknowns||table_unknown;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('taskId',t.id,'reason',CASE WHEN t.status IN ('ready','running') AND (t.invalidated_at IS NULL OR t.status='running') THEN '存在待执行或运行中的任务，请完成或明确处理后重新盘点。' ELSE '供应商提交结果尚未确认，请先恢复或核对已有请求。' END)),'[]') INTO result
 FROM public.tasks t JOIN public.episodes e ON e.id=t.episode_id LEFT JOIN public.paid_generation_reservations r ON r.task_id=t.id
 WHERE e.account_id=p_account AND ((t.status IN ('ready','running') AND (t.invalidated_at IS NULL OR t.status='running')) OR (t.status<>'completed' AND (t.id=ANY(unknowns) OR (r.request_state<>'succeeded' AND NOT t.id=ANY(rejected)))));
 IF EXISTS(SELECT 1 FROM public.asset_locks l JOIN public.episodes e ON e.id=l.episode_id WHERE e.account_id=p_account AND l.expires_at>clock_timestamp()) THEN result:=result||jsonb_build_array(jsonb_build_object('reason','存在未释放的生产文件租约。'));END IF;
 IF EXISTS(SELECT 1 FROM local_identity.episode_creation_intents i WHERE i.account_id=p_account AND i.result IS NULL) THEN result:=result||jsonb_build_array(jsonb_build_object('reason','存在未完成的生产单目录创建，请先恢复原操作。'));END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION local_identity.account_directory_evidence(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f record;rows jsonb;result jsonb:='{}';BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.account_memberships WHERE account_id=p_account AND user_id=local_identity.owner_id() AND role='owner') THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 FOR f IN SELECT c.table_schema,c.table_name FROM information_schema.columns c JOIN information_schema.tables t USING(table_schema,table_name) WHERE c.table_schema IN ('public','local_identity') AND c.column_name='episode_id' AND t.table_type='BASE TABLE' ORDER BY c.table_schema,c.table_name LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text),''[]'') FROM %I.%I r WHERE r.episode_id::text IN (SELECT id::text FROM public.episodes WHERE account_id=$1)',f.table_schema,f.table_name) INTO rows USING p_account;
  result:=result||jsonb_build_object(f.table_schema||'.'||f.table_name,rows);
 END LOOP;
 FOR f IN SELECT c.table_schema,c.table_name FROM information_schema.columns c JOIN information_schema.tables t USING(table_schema,table_name) WHERE c.table_schema IN ('public','local_identity') AND c.column_name='workspace_id' AND t.table_type='BASE TABLE' AND NOT EXISTS(SELECT 1 FROM information_schema.columns x WHERE x.table_schema=c.table_schema AND x.table_name=c.table_name AND x.column_name='episode_id') ORDER BY c.table_schema,c.table_name LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text),''[]'') FROM %I.%I r WHERE r.workspace_id::text IN (SELECT w.id::text FROM local_identity.production_workspaces w JOIN public.episodes e ON e.id=w.episode_id WHERE e.account_id=$1)',f.table_schema,f.table_name) INTO rows USING p_account;
  result:=result||jsonb_build_object(f.table_schema||'.'||f.table_name,rows);
 END LOOP;
 RETURN result||jsonb_build_object(
  'account_asset_directories',(SELECT coalesce(jsonb_agg(to_jsonb(d)),'[]') FROM local_identity.account_asset_directories d WHERE d.account_id=p_account),
  'account_directory_locations',(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.source_root),'[]') FROM local_identity.account_directory_locations l WHERE l.account_id=p_account),
  'blueprint_asset_roots',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'root',b.policy->>'asset_root') ORDER BY b.id),'[]') FROM public.account_blueprint_versions b WHERE b.account_id=p_account AND coalesce(b.policy->>'asset_root','')<>'')
 );
END $function$

CREATE OR REPLACE FUNCTION local_identity.adopt_production_preparation(p_episode uuid, p_script uuid, p_source uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes;
BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned input required' USING ERRCODE='42501';END IF;
 SELECT * INTO e FROM public.episodes WHERE id=p_episode;
 IF e.main_script_revision_id IS DISTINCT FROM p_script OR e.archived_at IS NOT NULL OR local_identity.is_historical_episode(e.id)
  OR e.stage NOT IN ('script_approved','storyboard_review','storyboard_approved','production_ready','render_ready','qc_review','qc_passed') THEN
  RAISE EXCEPTION 'Current editable preparation required' USING ERRCODE='40001';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.review_packages p WHERE p.id=p_source AND p.episode_id=p_episode AND p.stage='storyboard_review' AND p.invalidated_at IS NULL) THEN RAISE EXCEPTION 'Current original preparation required' USING ERRCODE='40001';END IF;
 IF NOT EXISTS(SELECT 1 FROM local_identity.workspace_preparations b WHERE b.package_id=p_source AND b.episode_id=p_episode AND b.script_revision_id=p_script)
  AND NOT EXISTS(SELECT 1 FROM local_identity.production_preparation_revisions p WHERE p.id=p_source AND p.episode_id=p_episode AND p.script_revision_id=p_script AND p.source_reference_id=p_source AND p.source_format='storyboard/v1') THEN
  RAISE EXCEPTION 'Confirmed preparation import required' USING ERRCODE='42501';
 END IF;
 RETURN local_identity.import_preparation_source(p_episode,p_script,p_source);
END $function$

CREATE OR REPLACE FUNCTION local_identity.allow_provider_preparation_recovery(p_task uuid, p_attempt integer, p_lease uuid, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tasks;used integer;
BEGIN
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501';END IF;
 PERFORM public.refresh_worker_task_lease(p_task,p_attempt,p_lease);
 SELECT * INTO t FROM public.tasks WHERE id=p_task FOR UPDATE;
 IF p_kind NOT IN ('speech','image') OR NOT local_identity.provider_dispatch_context_current(p_task,p_kind) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts f WHERE f.task_id=p_task AND (f.phase NOT IN ('preparing','reserved') OR f.kind<>p_kind OR f.request_hash<>md5(t.input_snapshot::text))) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts WHERE task_id=p_task AND attempt=p_attempt AND lease_token<>p_lease) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts WHERE task_id=p_task AND phase='reserved')
  AND (EXISTS(SELECT 1 FROM public.paid_generation_reservations WHERE task_id=p_task)
   OR EXISTS(SELECT 1 FROM local_identity.workspace_narration_submissions WHERE task_id=p_task)
   OR EXISTS(SELECT 1 FROM local_identity.workspace_visual_submissions WHERE task_id=p_task)) THEN RETURN false;END IF;
 SELECT coalesce(sum(local_recoveries),0) INTO used FROM local_identity.provider_dispatch_facts WHERE task_id=p_task;
 IF used>=2 THEN RETURN false;END IF;
 INSERT INTO local_identity.provider_dispatch_facts(task_id,attempt,lease_token,kind,request_hash,phase)
 VALUES(p_task,p_attempt,p_lease,p_kind,md5(t.input_snapshot::text),'preparing') ON CONFLICT DO NOTHING;
 UPDATE local_identity.provider_dispatch_facts SET local_recoveries=local_recoveries+1,last_reason='temporary_local_failure',updated_at=clock_timestamp() WHERE task_id=p_task AND attempt=p_attempt;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION local_identity.append_production_metric(p_owner uuid, p_episode uuid, p_type text, p_key text, p_payload jsonb, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tier text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_payload jsonb; tier text; inserted_id bigint; amount bigint:=0; fact_currency text:='none'; test_episode boolean; activated timestamptz;
BEGIN
 SELECT updated_at INTO activated FROM local_identity.production_metric_controls WHERE owner_id=p_owner AND enabled;
 IF activated IS NULL OR p_at<activated THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.episodes e JOIN public.account_memberships m ON m.account_id=e.account_id WHERE e.id=p_episode AND m.user_id=p_owner AND m.role='owner') THEN RAISE EXCEPTION 'Owned metric episode required' USING ERRCODE='42501';END IF;
 IF p_key IS NULL OR p_key !~ '^[A-Za-z0-9:_.-]{1,200}$' OR p_type IS NULL OR p_type !~ '^[a-z_]{1,64}$' OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>8192 THEN RAISE EXCEPTION 'Invalid metric fact';END IF;
 IF p_payload->>'task_id' IS NOT NULL THEN
  SELECT q.tier INTO tier FROM local_identity.production_metric_task_quality q WHERE q.owner_id=p_owner AND q.task_id=(p_payload->>'task_id')::uuid;
  tier:=coalesce(tier,'unspecified');
 ELSE SELECT v.tier INTO tier FROM local_identity.production_metric_quality_versions v WHERE v.owner_id=p_owner AND v.episode_id=p_episode ORDER BY revision DESC LIMIT 1;END IF;
 tier:=coalesce(p_tier,tier,'unspecified');
 INSERT INTO local_identity.production_metric_events(owner_id,episode_id,event_type,source_key,payload,occurred_at,quality_tier)
 VALUES(p_owner,p_episode,p_type,p_key,p_payload,coalesce(p_at,clock_timestamp()),tier)
 ON CONFLICT(owner_id,episode_id,event_type,source_key) DO NOTHING RETURNING id INTO inserted_id;
 IF inserted_id IS NULL THEN
  SELECT payload INTO current_payload FROM local_identity.production_metric_events WHERE owner_id=p_owner AND episode_id=p_episode AND event_type=p_type AND source_key=p_key;
  IF current_payload IS DISTINCT FROM p_payload THEN RAISE EXCEPTION 'Metric idempotency content conflict' USING ERRCODE='23505';END IF;
  RETURN false;
 END IF;
 -- Fixed-size increment, never a scan/summary in the business transaction.
 IF p_type='estimate_frozen' AND coalesce((p_payload->>'estimate_known')::boolean,false) THEN amount:=coalesce((p_payload->>'estimated_cents')::bigint,0);fact_currency:=coalesce(p_payload->>'currency','CNY');
 ELSIF p_type='reservation_created' THEN amount:=coalesce((p_payload->>'reserved_cents')::bigint,0);fact_currency:='application_cents';
 ELSIF p_type='attempt_finished' THEN amount:=coalesce((p_payload->>'reported_cents')::bigint,0);fact_currency:='application_cents';
 ELSIF p_type='supplier_paid' THEN amount:=(p_payload->>'paid_cents')::bigint;fact_currency:=p_payload->>'currency';END IF;
 SELECT is_test INTO test_episode FROM public.episodes WHERE id=p_episode;
 INSERT INTO local_identity.production_metric_daily(owner_id,day,event_type,quality_tier,currency,is_test,count,amount_cents)
 VALUES(p_owner,(coalesce(p_at,clock_timestamp()) AT TIME ZONE 'Asia/Shanghai')::date,p_type,tier,fact_currency,test_episode,1,amount)
 ON CONFLICT(owner_id,day,event_type,quality_tier,currency,is_test) DO UPDATE SET count=local_identity.production_metric_daily.count+1,amount_cents=local_identity.production_metric_daily.amount_cents+excluded.amount_cents;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION local_identity.apply_connection_intent(p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i local_identity.connection_intents; result jsonb;
BEGIN
 SELECT * INTO i FROM local_identity.connection_intents WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Intent not found' USING ERRCODE='P0002'; END IF;
 result:=local_identity.apply_connection_intent_v1(p_key);
 IF i.applied_at IS NULL AND i.metadata->>'command'='rebind' THEN
  INSERT INTO local_identity.connection_qualifications(version_id,owner_id,qualified) VALUES(i.version_id,i.owner_id,false)
  ON CONFLICT(version_id) DO UPDATE SET qualified=false,updated_at=now();
 END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION local_identity.apply_connection_intent_v1(p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i local_identity.connection_intents; c public.external_connections; v public.external_connection_versions; official_endpoint text; next_version int; action text;
BEGIN
 SELECT * INTO i FROM local_identity.connection_intents WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Intent not found' USING ERRCODE='P0002'; END IF;
 IF i.applied_at IS NOT NULL THEN RETURN i.result; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.account_memberships WHERE user_id=i.owner_id AND role='owner') THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501'; END IF;
 action:=i.metadata->>'command';
 IF action IN ('create','rotate') THEN
  official_endpoint:=public.official_external_connection_endpoint(i.metadata->>'provider',i.metadata->>'adapter');
  IF official_endpoint IS NULL THEN RAISE EXCEPTION 'Provider not registered' USING ERRCODE='22023'; END IF;
  IF action='create' THEN
   INSERT INTO public.external_connections(id,provider,adapter,name,created_by,current_version_id,endpoint)
   VALUES(i.connection_id,i.metadata->>'provider',i.metadata->>'adapter',i.metadata->>'name',i.owner_id,i.version_id,official_endpoint) RETURNING * INTO c;
   next_version:=1;
  ELSE
   SELECT * INTO c FROM public.external_connections WHERE id=i.connection_id AND created_by=i.owner_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Connection not found' USING ERRCODE='P0002'; END IF;
   SELECT coalesce(max(version),0)+1 INTO next_version FROM public.external_connection_versions WHERE connection_id=c.id;
   UPDATE public.external_connections SET provider=i.metadata->>'provider',adapter=i.metadata->>'adapter',endpoint=official_endpoint,current_version_id=i.version_id,status='unverified',last_verified_at=NULL,last_verification_detail=NULL WHERE id=c.id RETURNING * INTO c;
  END IF;
  INSERT INTO public.external_connection_versions(id,connection_id,version,provider,adapter,endpoint,vault_secret_id)
  VALUES(i.version_id,c.id,next_version,c.provider,c.adapter,c.endpoint,i.secret_ref);
 ELSIF action='rebind' THEN
  SELECT version.* INTO v FROM public.external_connection_versions version JOIN public.external_connections connection ON connection.id=version.connection_id
  WHERE version.id=i.version_id AND version.connection_id=i.connection_id AND connection.created_by=i.owner_id AND version.revoked_at IS NULL FOR UPDATE OF version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Version not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO c FROM public.external_connections WHERE id=v.connection_id FOR UPDATE;
  -- Explicit re-entry invalidates readiness, retaining all old verification rows.
  INSERT INTO public.external_connection_verifications(connection_id,connection_version_id,status,detail) VALUES(c.id,v.id,'retryable','Owner重新绑定秘密；需要重新验证。');
  IF c.current_version_id=v.id THEN UPDATE public.external_connections SET status='retryable',last_verification_detail='Owner重新绑定秘密；需要重新验证。',last_verified_at=now() WHERE id=c.id RETURNING * INTO c; END IF;
 ELSE RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023';
 END IF;
 INSERT INTO local_identity.connection_bindings(version_id,owner_id,secret_ref,store_mode) VALUES(i.version_id,i.owner_id,i.secret_ref,i.store_mode)
 ON CONFLICT(version_id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM local_identity.connection_bindings WHERE version_id=i.version_id AND owner_id=i.owner_id AND secret_ref=i.secret_ref AND store_mode=i.store_mode) THEN RAISE EXCEPTION 'Binding conflict' USING ERRCODE='23505'; END IF;
 UPDATE local_identity.connection_intents SET applied_at=now(),result=to_jsonb(c) WHERE owner_id=i.owner_id AND idempotency_key=p_key;
 RETURN to_jsonb(c);
END;
$function$

CREATE OR REPLACE FUNCTION local_identity.attach_script_render_input()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p local_identity.script_productions; BEGIN
 IF NOT (NEW.input_snapshot ? 'review_render') THEN RETURN NEW; END IF;
 SELECT s.* INTO p FROM local_identity.script_productions s JOIN public.episodes e ON e.id=s.episode_id AND e.main_script_revision_id=s.script_revision_id WHERE s.episode_id=NEW.episode_id;
 IF FOUND THEN NEW.input_snapshot:=NEW.input_snapshot||jsonb_build_object('script_production',jsonb_build_object('authorization_hash',p.authorization_hash,'settings',p.plan->'settings','segments',p.plan->'segments')); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION local_identity.audit_failed_connection_probe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE connection public.external_connections; scope_account uuid;
BEGIN
 IF new.mode<>'live' OR new.outcome NOT IN('invalid','retryable') THEN RETURN new; END IF;
 SELECT c.* INTO connection FROM public.external_connections c WHERE c.current_version_id=new.version_id AND c.created_by=new.owner_id;
 IF NOT FOUND THEN RETURN new; END IF;
 SELECT m.account_id INTO scope_account FROM public.account_memberships m WHERE m.user_id=new.owner_id AND m.role='owner' ORDER BY m.account_id LIMIT 1;
 IF scope_account IS NOT NULL THEN
  INSERT INTO public.audit_events(account_id,event_type,payload,actor_id) VALUES(scope_account,'connection_verification_failed',jsonb_build_object('connection_id',connection.id,'name',connection.name,'probe_id',new.id,'outcome',new.outcome),new.owner_id);
 END IF;
 RETURN new;
END $function$

CREATE OR REPLACE FUNCTION local_identity.begin_native_output_publication(p_task_id uuid, p_attempt integer, p_lease_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM public.assert_worker_lease(p_task_id,p_attempt,p_lease_token);
 IF NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=p_task_id AND local_identity.input_task_allowed(t.episode_id,t.task_type)) THEN RAISE EXCEPTION 'Native task required' USING ERRCODE='42501'; END IF;
 INSERT INTO local_identity.native_output_publications(task_id,attempt,lease_token) VALUES(p_task_id,p_attempt,p_lease_token) ON CONFLICT(task_id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM local_identity.native_output_publications WHERE task_id=p_task_id AND attempt=p_attempt AND lease_token=p_lease_token) THEN RAISE EXCEPTION 'Pending publication belongs to another attempt' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION local_identity.bind_media_root(p_path text, p_device text, p_inode text, p_mount text, p_initialize boolean, p_owner uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 LOCK TABLE public.accounts,public.episodes,local_identity.import_record IN SHARE ROW EXCLUSIVE MODE;
 IF p_initialize THEN
  IF local_identity.owner_id() IS NULL OR local_identity.owner_id() IS DISTINCT FROM local_identity.media_root_owner() THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501'; END IF;
  IF NOT local_identity.media_workspace_empty() THEN RAISE EXCEPTION 'Existing workspace requires migration' USING ERRCODE='23514'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM local_identity.media_root_binding WHERE singleton AND (path,device_id,inode_id,mount_path) IS DISTINCT FROM (p_path,p_device,p_inode,p_mount)) THEN RAISE EXCEPTION 'Media identity mismatch' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM local_identity.media_root_binding) AND EXISTS(SELECT 1 FROM local_identity.restore_record WHERE media_root<>p_path) THEN RAISE EXCEPTION 'Restore root mismatch' USING ERRCODE='23514'; END IF;
 END IF;
 IF coalesce(p_owner,local_identity.media_root_owner()) IS NULL OR EXISTS(SELECT 1 FROM local_identity.media_root_binding WHERE owner_id IS DISTINCT FROM coalesce(p_owner,local_identity.media_root_owner())) THEN RAISE EXCEPTION 'Storage Owner binding required' USING ERRCODE='42501'; END IF;
 INSERT INTO local_identity.media_root_binding(owner_id,path,device_id,inode_id,mount_path) VALUES(coalesce(p_owner,local_identity.media_root_owner()),p_path,p_device,p_inode,p_mount)
 ON CONFLICT(singleton) DO UPDATE SET path=excluded.path,device_id=excluded.device_id,inode_id=excluded.inode_id,mount_path=excluded.mount_path,updated_at=clock_timestamp();
END $function$

CREATE OR REPLACE FUNCTION local_identity.capture_production_metric_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid; tier text; rev integer; d record; t public.tasks;
BEGIN
 -- Delivery rows may precede task completion. Freeze on confirmation (insertion),
 -- count a completed delivery only once the authoritative task completes.
 IF TG_TABLE_NAME='workspace_deliveries' THEN
  FOR o IN SELECT m.user_id FROM public.episodes e JOIN public.account_memberships m ON m.account_id=e.account_id JOIN local_identity.production_metric_controls c ON c.owner_id=m.user_id AND c.enabled AND c.updated_at<=NEW.created_at WHERE e.id=NEW.episode_id AND m.role='owner' LOOP
   SELECT v.tier,v.revision INTO tier,rev FROM local_identity.production_metric_quality_versions v WHERE v.owner_id=o AND v.episode_id=NEW.episode_id ORDER BY v.revision DESC LIMIT 1;
   INSERT INTO local_identity.production_metric_delivery_quality(owner_id,delivery_id,episode_id,tier,revision) VALUES(o,NEW.id,NEW.episode_id,coalesce(tier,'unspecified'),coalesce(rev,0)) ON CONFLICT DO NOTHING;
   PERFORM local_identity.append_production_metric(o,NEW.episode_id,'delivery_confirmed','delivery:'||NEW.id,jsonb_build_object('delivery_id',NEW.id,'task_id',NEW.task_id,'quality_snapshot_known',true),NULL,coalesce(tier,'unspecified'));
  END LOOP;
  SELECT * INTO t FROM public.tasks WHERE id=NEW.task_id;
 ELSE t:=NEW;END IF;
 IF t.status='completed' AND t.task_type='prepare_publish_package' AND t.completed_at IS NOT NULL THEN
  FOR d IN SELECT w.*,m.user_id owner_id,q.tier,q.delivery_id IS NOT NULL snapshot_known FROM local_identity.workspace_deliveries w JOIN public.episodes e ON e.id=w.episode_id JOIN public.account_memberships m ON m.account_id=e.account_id AND m.role='owner' JOIN local_identity.production_metric_controls c ON c.owner_id=m.user_id AND c.enabled LEFT JOIN local_identity.production_metric_delivery_quality q ON q.delivery_id=w.id AND q.owner_id=m.user_id WHERE w.task_id=t.id LOOP
   PERFORM local_identity.append_production_metric(d.owner_id,d.episode_id,'delivery_completed','delivery:'||d.id,jsonb_build_object('delivery_id',d.id,'task_id',t.id,'quality_snapshot_known',d.snapshot_known),t.completed_at,coalesce(d.tier,'unspecified'));
  END LOOP;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION local_identity.capture_production_metric_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e uuid; o uuid;
BEGIN
 IF TG_OP='UPDATE' AND NEW.phase IS NOT DISTINCT FROM OLD.phase THEN RETURN NEW;END IF;
 SELECT episode_id INTO e FROM public.tasks WHERE id=NEW.task_id;
 FOR o IN SELECT m.user_id FROM public.episodes ep JOIN public.account_memberships m ON m.account_id=ep.account_id JOIN local_identity.production_metric_controls c ON c.owner_id=m.user_id AND c.enabled WHERE ep.id=e AND m.role='owner' LOOP
  PERFORM local_identity.append_production_metric(o,e,'provider_dispatch_phase','dispatch:'||NEW.task_id||':'||NEW.attempt||':'||NEW.phase,jsonb_build_object('task_id',NEW.task_id,'attempt',NEW.attempt,'request_kind',NEW.kind,'phase',NEW.phase,'reason_code',CASE WHEN NEW.phase='dispatching' THEN 'dispatch_marker_not_delivery_proof' WHEN NEW.phase='received' THEN 'receipt_persisted' ELSE NEW.phase END),NEW.updated_at);
  IF NEW.phase='received' THEN PERFORM local_identity.append_production_metric(o,e,'provider_receipt_persisted','artifact-receipt:'||NEW.task_id||':'||NEW.attempt,jsonb_build_object('task_id',NEW.task_id,'attempt',NEW.attempt,'request_kind',NEW.kind,'phase','artifact_verified'),NEW.updated_at);END IF;
