CREATE OR REPLACE FUNCTION local_identity.change_owner_password(p_owner uuid, p_token_hash text, p_digest jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF coalesce(p_digest->>'version','')<>'scrypt-v1' OR coalesce(p_digest->>'salt','') !~ '^[0-9a-f]{64}$' OR coalesce(p_digest->>'digest','') !~ '^[0-9a-f]{128}$' THEN RAISE EXCEPTION 'Invalid password digest' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM local_identity.sessions WHERE token_hash=p_token_hash AND owner_id=p_owner AND revoked_at IS NULL AND expires_at>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RETURN false;END IF;
 UPDATE local_identity.credentials SET password_digest=p_digest,failed_attempts=0,locked_until=NULL,updated_at=clock_timestamp() WHERE owner_id=p_owner;
 IF NOT FOUND THEN RETURN false;END IF;
 UPDATE local_identity.sessions SET revoked_at=clock_timestamp() WHERE owner_id=p_owner AND token_hash<>p_token_hash AND revoked_at IS NULL;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION local_identity.claim_input_task(p_task_id uuid DEFAULT NULL::uuid, p_worker_capacity integer DEFAULT 1)
 RETURNS TABLE(task_id uuid, task_type text, attempt integer, budget_limit_cents integer, max_attempts integer, provider text, model text, prompt_version text, episode_id uuid, account_id uuid, blueprint_version_id uuid, title text, allowed_asset_root text, input_snapshot jsonb, lease_token uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claimed record; token uuid;
begin
  if local_identity.actor_role() is distinct from 'service_role' then raise exception 'Worker service role is required' using errcode='42501'; end if;
  -- The private claimant invokes independent recovery before selecting ready rows.
  for claimed in select * from local_identity.claim_input_task_pre_lease(p_task_id,p_worker_capacity) loop
    token := gen_random_uuid();
    update public.tasks set lease_token=token where id=claimed.task_id;
    update public.task_runs set lease_token=token,task_package=task_package || jsonb_build_object('lease_token',token)
      where task_runs.task_id=claimed.task_id and task_runs.attempt=claimed.attempt;
    return query select claimed.task_id,claimed.task_type,claimed.attempt,claimed.budget_limit_cents,claimed.max_attempts,claimed.provider,claimed.model,claimed.prompt_version,claimed.episode_id,claimed.account_id,claimed.blueprint_version_id,claimed.title,claimed.allowed_asset_root,claimed.input_snapshot,token;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION local_identity.claim_input_task_pre_lease(p_task_id uuid DEFAULT NULL::uuid, p_worker_capacity integer DEFAULT 1)
 RETURNS TABLE(task_id uuid, task_type text, attempt integer, budget_limit_cents integer, max_attempts integer, provider text, model text, prompt_version text, episode_id uuid, account_id uuid, blueprint_version_id uuid, title text, allowed_asset_root text, input_snapshot jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  candidate public.tasks;
  runtime jsonb;
  running_count integer;
  resource jsonb; next_turn bigint;
begin
  if p_worker_capacity is null or p_worker_capacity <= 0 then
    raise exception 'Worker capacity must be a positive integer' using errcode = '22023';
  end if;

  -- One durable host limit, shared by every HTTP/CLI process. Caller capacity
  -- may lower this invocation's limit but cannot raise the configured ceiling.
  perform pg_advisory_xact_lock(hashtextextended('loop-worker-global-capacity',0));
  perform local_identity.recover_input_tasks();
  select least(p_worker_capacity, capacity) into p_worker_capacity
    from public.worker_scheduler_settings where singleton for update;
  if not found then raise exception 'Worker scheduler capacity is not configured' using errcode='55000'; end if;
  if (select count(*) from public.tasks where local_identity.current_worker_task(tasks) and status='running'
      and claimed_at > clock_timestamp()-interval '30 minutes') >= p_worker_capacity then return; end if;

  for candidate in
    select task.*
    from public.tasks task left join public.worker_episode_turns turns on turns.episode_id=task.episode_id
    where local_identity.current_worker_task(task) and local_identity.input_task_allowed(task.episode_id,task.task_type) and task.status = 'ready' AND NOT EXISTS(SELECT 1 FROM local_identity.historical_tasks h WHERE h.task_id=task.id) and task.invalidated_at is null and task.available_at <= clock_timestamp()
      and task.provider in ('codex','volcengine_tts','pexels','ffmpeg','freesound','openchatcut','openai','whisperx','bailian','volcengine','minimax','kling')
      and task.attempt < task.max_attempts
      and (p_task_id is null or task.id = p_task_id)
    order by (select count(*) from public.tasks busy where local_identity.current_worker_task(busy) and busy.episode_id=task.episode_id and busy.status='running' and busy.claimed_at>clock_timestamp()-interval '30 minutes'), coalesce(turns.last_turn,0), task.created_at, task.id
    for update of task skip locked
  loop
    runtime := public.worker_runtime_constraints(candidate.input_snapshot, p_worker_capacity);
    runtime := runtime || jsonb_build_object('resource_limits',public.worker_resource_limits(candidate.input_snapshot,p_worker_capacity),
      'effective_concurrency',least((runtime->>'effective_concurrency')::integer,
        (select min((r->>'limit')::integer) from jsonb_array_elements(public.worker_resource_limits(candidate.input_snapshot,p_worker_capacity)) r)));
    -- All claimants take global -> recovery -> sorted resource locks. No lock
    -- is held across execution. Skip a saturated resource and try other Episodes.
    running_count:=0;
    for resource in select value from jsonb_array_elements(public.worker_resource_limits(candidate.input_snapshot,p_worker_capacity)) order by value->>'key'
    loop
      perform pg_advisory_xact_lock(hashtextextended(resource->>'key',0));
      select count(*) into running_count from public.tasks task
      where local_identity.current_worker_task(task) and task.status='running' and task.claimed_at>clock_timestamp()-interval '30 minutes'
        and exists(select 1 from jsonb_array_elements(public.worker_resource_limits(task.input_snapshot,p_worker_capacity)) r where r->>'key'=resource->>'key');
      if running_count >= (resource->>'limit')::integer then exit; end if;
    end loop;
    if running_count >= (resource->>'limit')::integer then continue; end if;

    update public.tasks task
    set input_snapshot = candidate.input_snapshot || jsonb_build_object(
      'runtime_constraints', runtime,
      'allowed_tools', public.worker_required_tools(candidate.input_snapshot ->> 'capability')
    )
    where task.id = candidate.id;
    return query select * from public.claim_next_worker_task_legacy(candidate.id);
    select nextval('local_identity.input_dispatch_turn') into next_turn;
    insert into public.worker_episode_turns(episode_id,last_turn) values(candidate.episode_id,next_turn)
      on conflict on constraint worker_episode_turns_pkey do update set last_turn=excluded.last_turn;
    return;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION local_identity.commit_media_root_migration(p_id uuid, p_sha text, p_targets jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m local_identity.media_root_migrations;ep jsonb;d jsonb;t jsonb;old local_identity.episode_asset_locations;proof jsonb;op text;new_root text;prefix text;actual jsonb;bindings jsonb:='[]';BEGIN
 IF session_user<>'loop_app' OR local_identity.owner_id() IS DISTINCT FROM local_identity.media_root_owner() THEN RAISE EXCEPTION 'Storage Owner required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM local_identity.media_root_migrations WHERE id=p_id AND owner_id=local_identity.owner_id() FOR UPDATE;
 IF NOT FOUND OR m.status<>'copying' OR m.manifest_sha256<>p_sha OR p_sha<>encode(sha256(convert_to(m.manifest::text,'UTF8')),'hex') OR NOT (m.manifest->>'canExecute')::boolean OR local_identity.media_root_binding() IS DISTINCT FROM m.manifest->'sourceBinding' THEN RAISE EXCEPTION 'Migration source or plan changed' USING ERRCODE='55000';END IF;
 IF (SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'owned',true) ORDER BY a.id),'[]') FROM public.accounts a) IS DISTINCT FROM m.manifest->'accounts' OR jsonb_array_length(local_identity.media_root_pending_operations())<>0 THEN RAISE EXCEPTION 'Workspace scope or pending operation changed' USING ERRCODE='55000';END IF;
 FOR ep IN SELECT value FROM jsonb_array_elements(m.manifest->'episodes') LOOP
  IF NOT local_identity.lock_owned_account_row((ep->>'accountId')::uuid) THEN RAISE EXCEPTION 'Account Owner required';END IF;
  IF NOT EXISTS(SELECT 1 FROM local_identity.episode_storage_location((ep->>'id')::uuid) l WHERE l.account_id=(ep->>'accountId')::uuid AND local_identity.storage_physical_root(l.asset_root)=ep->'location'->>'assetRoot' AND l.directory_relative_path=ep->'location'->>'relativePath' AND l.directory_device_id IS NOT DISTINCT FROM ep->'location'->>'deviceId' AND l.directory_inode_id IS NOT DISTINCT FROM ep->'location'->>'inodeId') THEN RAISE EXCEPTION 'Episode source changed';END IF;
  SELECT value INTO d FROM jsonb_array_elements(m.manifest->'directories') WHERE value->>'kind'='episode' AND value->>'episodeId'=ep->>'id';
  SELECT value INTO t FROM jsonb_array_elements(p_targets) WHERE value->>'sourcePath'=d->'source'->>'path';
  IF t IS NULL OR t->>'path'<>(m.manifest->'targetBinding'->>'path')||'/'||(d->>'targetRelativePath') OR t->>'device' IS NULL OR t->>'inode' IS NULL THEN RAISE EXCEPTION 'Episode target identity missing';END IF;
  new_root:=(m.manifest->'targetBinding'->>'path')||substring(ep->'location'->>'assetRoot' from length(m.manifest->'sourceBinding'->>'path')+1);prefix:=ep->'location'->>'relativePath';
  bindings:=bindings||jsonb_build_array(jsonb_build_object('episodeId',ep->>'id','accountId',ep->>'accountId','sourceRoot',ep->'location'->>'assetRoot','sourcePrefix',prefix,'sourceDeviceId',d->'source'->>'device','sourceInodeId',d->'source'->>'inode','actualRoot',new_root,'relativePath',prefix,'deviceId',t->>'device','inodeId',t->>'inode'));
 END LOOP;
 FOR d IN SELECT value FROM jsonb_array_elements(m.manifest->'directories') WHERE value->>'kind' IN ('account','series','unassigned') LOOP
  SELECT value INTO t FROM jsonb_array_elements(p_targets) WHERE value->>'sourcePath'=d->'source'->>'path';
  IF t IS NULL OR t->>'path'<>(m.manifest->'targetBinding'->>'path')||'/'||(d->>'targetRelativePath') THEN RAISE EXCEPTION 'Parent target identity missing';END IF;
  IF d->>'kind'='account' THEN
   UPDATE local_identity.account_asset_directories SET actual_root=t->>'path',device_id=t->>'device',inode_id=t->>'inode',updated_at=clock_timestamp() WHERE account_id=(d->>'accountId')::uuid AND actual_root=d->'source'->>'path' AND device_id=d->'source'->>'device' AND inode_id=d->'source'->>'inode';
  ELSE
   UPDATE local_identity.account_storage_containers SET device_id=t->>'device',inode_id=t->>'inode' WHERE id=(d->>'containerId')::uuid AND account_id=(d->>'accountId')::uuid AND device_id=d->'source'->>'device' AND inode_id=d->'source'->>'inode';
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent source registration changed';END IF;
 END LOOP;
 -- These are current alias destinations, never original manifests or task inputs.
 UPDATE local_identity.account_directory_locations SET actual_root=(m.manifest->'targetBinding'->>'path')||substring(actual_root from length(m.manifest->'sourceBinding'->>'path')+1) WHERE actual_root=m.manifest->'sourceBinding'->>'path' OR left(actual_root,length(m.manifest->'sourceBinding'->>'path')+1)=(m.manifest->'sourceBinding'->>'path')||'/';
 proof:=jsonb_build_object('planId',m.id,'manifestSha256',m.manifest_sha256,'bindings',bindings,'directories',p_targets,'targetBinding',m.manifest->'targetBinding');op:='root-migration:'||m.id::text;
 INSERT INTO local_identity.storage_location_operations(id,kind,media_root_migration_id,proof,proof_sha256) VALUES(op,'root_migration',m.id,proof,encode(sha256(convert_to(proof::text,'UTF8')),'hex'));
 FOR t IN SELECT value FROM jsonb_array_elements(bindings) LOOP
  INSERT INTO local_identity.episode_storage_lineage(operation_id,episode_id,account_id,source_root,source_prefix,source_device_id,source_inode_id,target_root,target_prefix,target_device_id,target_inode_id) VALUES(op,(t->>'episodeId')::uuid,(t->>'accountId')::uuid,t->>'sourceRoot',t->>'sourcePrefix',t->>'sourceDeviceId',t->>'sourceInodeId',t->>'actualRoot',t->>'relativePath',t->>'deviceId',t->>'inodeId');
  SELECT * INTO old FROM local_identity.episode_asset_locations WHERE episode_id=(t->>'episodeId')::uuid;
  INSERT INTO local_identity.episode_asset_locations(episode_id,account_id,asset_root,directory_relative_path,directory_device_id,directory_inode_id,storage_series_id,layout_version) VALUES((t->>'episodeId')::uuid,(t->>'accountId')::uuid,t->>'actualRoot',t->>'relativePath',t->>'deviceId',t->>'inodeId',old.storage_series_id,coalesce(old.layout_version,1)) ON CONFLICT(episode_id) DO UPDATE SET asset_root=excluded.asset_root,directory_relative_path=excluded.directory_relative_path,directory_device_id=excluded.directory_device_id,directory_inode_id=excluded.directory_inode_id;
 END LOOP;
 UPDATE local_identity.media_root_binding SET path=m.manifest->'targetBinding'->>'path',device_id=m.manifest->'targetBinding'->>'deviceId',inode_id=m.manifest->'targetBinding'->>'inodeId',mount_path=m.manifest->'targetBinding'->>'mountPath',updated_at=clock_timestamp();
 UPDATE local_identity.media_root_migrations SET status='committed',publication=proof,error=NULL,updated_at=clock_timestamp() WHERE id=m.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.complete_owned_deletion_cleanup(p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE r jsonb; BEGIN
 SELECT result INTO r FROM local_identity.command_receipts WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key AND result->>'cleanupKey'=p_key::text AND jsonb_typeof(result->'cleanupRoot')='string' FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.episodes WHERE id=(r->>'episodeId')::uuid) THEN RAISE EXCEPTION 'Owned committed deletion intent required' USING ERRCODE='42501'; END IF;
 r:=jsonb_set(jsonb_set(r,'{cleanupPending}','false'::jsonb),'{localRemoved}','true'::jsonb);
 UPDATE local_identity.command_receipts SET result=r WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION local_identity.complete_owned_publish(p_episode_id uuid, p_cover jsonb, p_metadata jsonb, p_package jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE a public.artifacts; BEGIN
 IF NOT local_identity.owned_delivery_episode(p_episode_id) THEN RAISE EXCEPTION 'Owned delivery Episode required' USING ERRCODE='42501'; END IF;
 PERFORM public.record_publish_input(p_episode_id,'cover',p_cover->>'relativePath',p_cover->>'sha256',(p_cover->>'fileSize')::bigint);
 PERFORM public.record_publish_input(p_episode_id,'metadata',p_metadata->>'relativePath',p_metadata->>'sha256',(p_metadata->>'fileSize')::bigint);
 a:=public.record_publish_package(p_episode_id,p_package->>'relativePath',p_package->>'sha256',(p_package->>'fileSize')::bigint);
 PERFORM public.record_publish_package_verification(p_episode_id,a.sha256,a.file_size); RETURN to_jsonb(a);
END $function$

CREATE OR REPLACE FUNCTION local_identity.complete_storage_adoption(p_migration uuid, p_targets jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m local_identity.account_directory_migrations;e jsonb;s jsonb;t jsonb;op text;BEGIN
 IF session_user<>'loop_app' THEN RAISE EXCEPTION 'Trusted local service required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM local_identity.account_directory_migrations WHERE id=p_migration FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_account_row(m.account_id) THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF m.status<>'copying' OR m.manifest->>'kind'<>'adoption' OR jsonb_array_length(m.manifest->'conflicts')<>0 THEN RAISE EXCEPTION 'Adoption plan not executable' USING ERRCODE='55000';END IF;
 op:='adoption:'||m.id::text;
 INSERT INTO local_identity.storage_location_operations(id,kind,migration_id,proof,proof_sha256) VALUES(op,'adoption',m.id,m.manifest,encode(sha256(convert_to(m.manifest::text,'UTF8')),'hex'));
 FOR e IN SELECT value FROM jsonb_array_elements(m.manifest->'episodes') WHERE NOT (value->>'managed')::boolean LOOP
  SELECT value INTO t FROM jsonb_array_elements(p_targets) WHERE value->>'episodeId'=e->>'id';
  IF t IS NULL OR t->>'prefix'<>e->>'targetPrefix' OR t->>'path'<>(m.manifest->>'targetRoot')||'/'||(e->>'targetPrefix') OR NOT EXISTS(SELECT 1 FROM public.episodes WHERE id=(e->>'id')::uuid AND account_id=m.account_id) THEN RAISE EXCEPTION 'Adoption target mismatch';END IF;
  FOR s IN SELECT value FROM jsonb_array_elements(e->'sources') LOOP
   INSERT INTO local_identity.episode_storage_lineage(operation_id,episode_id,account_id,source_root,source_prefix,source_device_id,source_inode_id,target_root,target_prefix,target_device_id,target_inode_id)
    VALUES(op,(e->>'id')::uuid,m.account_id,s->'root'->>'path',s->>'prefix',s->'directory'->>'device',s->'directory'->>'inode',m.manifest->>'targetRoot',e->>'targetPrefix',t->>'device',t->>'inode');
  END LOOP;
  INSERT INTO local_identity.episode_asset_locations(episode_id,account_id,asset_root,directory_relative_path,directory_device_id,directory_inode_id,storage_series_id,layout_version)
   VALUES((e->>'id')::uuid,m.account_id,m.manifest->>'targetRoot',e->>'targetPrefix',t->>'device',t->>'inode',(e->>'seriesId')::uuid,2)
   ON CONFLICT(episode_id) DO UPDATE SET asset_root=excluded.asset_root,directory_relative_path=excluded.directory_relative_path,directory_device_id=excluded.directory_device_id,directory_inode_id=excluded.directory_inode_id,storage_series_id=excluded.storage_series_id,layout_version=2;
 END LOOP;
 UPDATE local_identity.account_directory_migrations SET status='completed',error=NULL,updated_at=clock_timestamp() WHERE id=m.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.complete_storage_move(p_migration uuid, p_targets jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m local_identity.account_directory_migrations;e jsonb;s jsonb;t jsonb;
 l record;c record;a record;op text;
BEGIN
 IF session_user<>'loop_app' THEN RAISE EXCEPTION 'Trusted local service required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM local_identity.account_directory_migrations WHERE id=p_migration FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_account_row(m.account_id) THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF m.status<>'copying' OR m.manifest->>'kind'<>'move' OR jsonb_array_length(m.manifest->'conflicts')<>0
  OR jsonb_array_length(m.manifest->'episodes')<>1 OR jsonb_array_length(p_targets)<>1 THEN RAISE EXCEPTION 'Move plan not executable' USING ERRCODE='55000';END IF;
 e:=m.manifest->'episodes'->0;s:=e->'sources'->0;t:=p_targets->0;
 SELECT * INTO l FROM local_identity.episode_storage_location((e->>'id')::uuid);
 SELECT * INTO c FROM local_identity.account_storage_containers WHERE id=(m.manifest->>'targetContainerId')::uuid AND account_id=m.account_id AND series_id IS NOT DISTINCT FROM (e->>'seriesId')::uuid;
 SELECT * INTO a FROM local_identity.account_asset_directories WHERE account_id=m.account_id;
 IF l.account_id IS DISTINCT FROM m.account_id OR c.id IS NULL OR a.actual_root IS DISTINCT FROM m.manifest->>'targetRoot'
  OR jsonb_array_length(e->'sources')<>1 OR (e->>'managed')::boolean
  OR (local_identity.storage_physical_root(l.asset_root),l.directory_relative_path,l.directory_device_id,l.directory_inode_id)
    IS DISTINCT FROM (s->'root'->>'path',s->>'prefix',s->'directory'->>'device',s->'directory'->>'inode')
  OR NOT EXISTS(SELECT 1 FROM local_identity.episode_storage_collection((e->>'id')::uuid) x WHERE x.container_id=(m.manifest->>'sourceContainerId')::uuid AND x.container_id<>c.id)
  OR left(e->>'targetPrefix',length(c.directory_relative_path)+1)<>c.directory_relative_path||'/'
  OR position('/' IN substring(e->>'targetPrefix' FROM length(c.directory_relative_path)+2))<>0
  OR e->>'targetPrefix'=l.directory_relative_path
  OR (t->>'episodeId',t->>'prefix',t->>'path') IS DISTINCT FROM (e->>'id',e->>'targetPrefix',a.actual_root||'/'||(e->>'targetPrefix'))
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(m.manifest->'containers') x WHERE x->>'id'=c.id::text AND (x->>'prefix',x->'identity'->>'device',x->'identity'->>'inode')=(c.directory_relative_path,c.device_id,c.inode_id))
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(m.manifest->'createdDirectories') x WHERE (x->>'path',x->>'device',x->>'inode')=(t->>'path',t->>'device',t->>'inode'))
 THEN RAISE EXCEPTION 'Move location or container changed' USING ERRCODE='55000';END IF;
 op:='move:'||m.id::text;
 INSERT INTO local_identity.storage_location_operations(id,kind,migration_id,proof,proof_sha256)
  VALUES(op,'move',m.id,m.manifest,encode(sha256(convert_to(m.manifest::text,'UTF8')),'hex'));
 INSERT INTO local_identity.episode_storage_lineage(operation_id,episode_id,account_id,source_root,source_prefix,source_device_id,source_inode_id,target_root,target_prefix,target_device_id,target_inode_id)
  VALUES(op,(e->>'id')::uuid,m.account_id,s->'root'->>'path',s->>'prefix',s->'directory'->>'device',s->'directory'->>'inode',a.actual_root,e->>'targetPrefix',t->>'device',t->>'inode');
 UPDATE local_identity.episode_asset_locations SET asset_root=a.actual_root,directory_relative_path=e->>'targetPrefix',directory_device_id=t->>'device',directory_inode_id=t->>'inode',storage_series_id=c.series_id,layout_version=2 WHERE episode_id=(e->>'id')::uuid;
 UPDATE local_identity.account_directory_migrations SET status='completed',error=NULL,updated_at=clock_timestamp() WHERE id=m.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.confirm_legacy_workspace_preparation(p_episode uuid, p_script uuid, p_package uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes;
BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501'; END IF;
 SELECT * INTO e FROM public.episodes WHERE id=p_episode;
 IF e.main_script_revision_id IS DISTINCT FROM p_script OR e.archived_at IS NOT NULL OR e.stage NOT IN ('storyboard_review','storyboard_approved','production_ready','render_ready','qc_review','qc_passed') OR local_identity.is_historical_episode(p_episode) THEN RAISE EXCEPTION 'Current confirmed script required' USING ERRCODE='22023'; END IF;
 IF p_package IS DISTINCT FROM (SELECT p.id FROM public.review_packages p JOIN public.artifacts a ON a.id=p.artifact_id WHERE p.episode_id=p_episode AND p.stage='storyboard_review' AND p.invalidated_at IS NULL ORDER BY p.revision_number DESC LIMIT 1) THEN RAISE EXCEPTION 'Current storyboard required' USING ERRCODE='22023'; END IF;
 INSERT INTO local_identity.workspace_preparations(package_id,episode_id,script_revision_id,origin,confirmed_by) VALUES(p_package,p_episode,p_script,'legacy-board',local_identity.owner_id()) ON CONFLICT(package_id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM local_identity.workspace_preparations WHERE package_id=p_package AND episode_id=p_episode AND script_revision_id=p_script) THEN RAISE EXCEPTION 'Preparation baseline changed' USING ERRCODE='40001'; END IF;
END $function$

CREATE OR REPLACE FUNCTION local_identity.create_account_at_id(p_id uuid, p_account_name text, p_account_slug text, p_timezone text, p_policy jsonb)
 RETURNS public.accounts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE created public.accounts; blueprint public.account_blueprint_versions;
BEGIN
 IF local_identity.owner_id() IS NULL OR local_identity.owner_id() IS DISTINCT FROM (SELECT owner_id FROM local_identity.media_root_binding WHERE singleton) THEN RAISE EXCEPTION 'Workspace storage Owner required' USING ERRCODE='42501'; END IF;
 IF char_length(trim(p_account_name))=0 OR char_length(trim(p_account_slug))=0 OR jsonb_typeof(p_policy)<>'object' THEN RAISE EXCEPTION 'Account fields required' USING ERRCODE='22023'; END IF;
 INSERT INTO public.accounts(id,name,slug,timezone) VALUES(p_id,trim(p_account_name),trim(p_account_slug),p_timezone) RETURNING * INTO created;
 INSERT INTO public.account_blueprint_versions(account_id,version,policy,is_active) VALUES(p_id,1,p_policy,true) RETURNING * INTO blueprint;
 UPDATE public.accounts SET current_blueprint_version_id=blueprint.id WHERE id=p_id RETURNING * INTO created;
 INSERT INTO public.account_memberships(account_id,user_id,role) VALUES(p_id,local_identity.owner_id(),'owner');
 INSERT INTO public.audit_events(account_id,event_type,payload,actor_id) VALUES(p_id,'account_created',jsonb_build_object('blueprint_version_id',blueprint.id),local_identity.owner_id());
 RETURN created;
END $function$

CREATE OR REPLACE FUNCTION local_identity.create_episode_from_intent(p_key uuid)
 RETURNS public.episodes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i local_identity.episode_creation_intents;created public.episodes;
BEGIN
 SELECT * INTO i FROM local_identity.episode_creation_intents WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key AND result IS NULL FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_account_row(i.account_id) THEN RAISE EXCEPTION 'Owned creation intent required' USING ERRCODE='42501';END IF;
 IF i.device_id IS NULL OR i.marker_device_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.accounts WHERE id=i.account_id AND archived_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM public.account_blueprint_versions WHERE id=i.blueprint_version_id AND account_id=i.account_id)
 OR (i.series_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.series_versions WHERE id=i.series_version_id AND account_id=i.account_id AND series_id=i.storage_series_id))
 OR NOT EXISTS(SELECT 1 FROM local_identity.account_asset_directories WHERE account_id=i.account_id AND actual_root=i.account_root AND device_id=i.account_device_id AND inode_id=i.account_inode_id)
 OR NOT EXISTS(SELECT 1 FROM local_identity.account_storage_containers WHERE id=i.container_id AND account_id=i.account_id AND series_id IS NOT DISTINCT FROM i.storage_series_id AND directory_relative_path=i.container_relative_path AND device_id=i.container_device_id AND inode_id=i.container_inode_id)
 THEN RAISE EXCEPTION 'Creation intent references changed' USING ERRCODE='40001';END IF;
 INSERT INTO public.episodes(id,account_id,blueprint_version_id,series_version_id,title,stage,is_test) VALUES(i.episode_id,i.account_id,i.blueprint_version_id,i.series_version_id,trim(coalesce(i.payload->>'title','')),'waiting_input',coalesce((i.payload->>'isTest')::boolean,false)) RETURNING * INTO created;
 UPDATE local_identity.episode_asset_locations SET asset_root=i.account_root,directory_relative_path=i.directory_relative_path,directory_device_id=i.device_id,directory_inode_id=i.inode_id,storage_series_id=i.storage_series_id,layout_version=2 WHERE episode_id=i.episode_id AND account_id=i.account_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Episode location registration missing' USING ERRCODE='40001';END IF;
 INSERT INTO local_identity.input_episodes(episode_id,owner_id) VALUES(i.episode_id,i.owner_id);
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) VALUES(i.account_id,i.episode_id,'episode_created',jsonb_build_object('blueprint_version_id',i.blueprint_version_id,'series_version_id',i.series_version_id,'is_test',created.is_test),i.owner_id);
 RETURN created;
END $function$

