CREATE OR REPLACE FUNCTION local_identity.episode_deletion_submission_unknown(p_episode uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f record;rejected uuid[]:='{}';unknowns uuid[]:='{}';table_rejected uuid[];table_unknown uuid[];
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.episodes e JOIN public.account_memberships m ON m.account_id=e.account_id WHERE e.id=p_episode AND m.user_id=local_identity.owner_id() AND m.role='owner') THEN RAISE EXCEPTION 'Owned Episode required' USING ERRCODE='42501';END IF;
 -- Reuse the account migration submission protocols, scoped to this Episode.
 FOR f IN SELECT table_name FROM information_schema.columns WHERE table_schema='local_identity' AND column_name='outcome' AND table_name LIKE '%submissions' LOOP
  EXECUTE format('SELECT coalesce(array_agg(DISTINCT s.task_id) FILTER(WHERE s.outcome=''rejected''),''{}''::uuid[]),coalesce(array_agg(DISTINCT s.task_id) FILTER(WHERE s.outcome IN (''started'',''received'')),''{}''::uuid[]) FROM local_identity.%I s JOIN public.tasks t ON t.id=s.task_id WHERE t.episode_id=$1 AND t.status<>''completed''',f.table_name) INTO table_rejected,table_unknown USING p_episode;
  rejected:=rejected||table_rejected;unknowns:=unknowns||table_unknown;
 END LOOP;
 RETURN EXISTS(SELECT 1 FROM public.tasks t LEFT JOIN public.paid_generation_reservations r ON r.task_id=t.id WHERE t.episode_id=p_episode AND t.status<>'completed' AND (t.id=ANY(unknowns) OR r.request_state<>'succeeded' AND NOT t.id=ANY(rejected)));
END $function$

CREATE OR REPLACE FUNCTION local_identity.finish_media_root_migration(p_id uuid, p_sha text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ BEGIN
 PERFORM local_identity.media_root_publication_proof(p_id,p_sha);
 UPDATE local_identity.media_root_migrations SET status='completed',error=NULL,updated_at=clock_timestamp() WHERE id=p_id AND status IN ('committed','completed');
 IF NOT FOUND THEN RAISE EXCEPTION 'Migration not committed';END IF;
END $function$

CREATE OR REPLACE FUNCTION local_identity.finish_native_output_publication(p_task_id uuid, p_attempt integer, p_lease_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tasks;
BEGIN
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.tasks WHERE id=p_task_id FOR UPDATE;
 IF NOT FOUND OR t.attempt<>p_attempt+1 OR NOT EXISTS(SELECT 1 FROM public.task_runs r WHERE r.task_id=p_task_id AND r.attempt=p_attempt AND r.lease_token=p_lease_token) THEN RAISE EXCEPTION 'Current native attempt required' USING ERRCODE='42501'; END IF;
 IF t.status='running' THEN PERFORM public.assert_worker_lease(p_task_id,p_attempt,p_lease_token);
 ELSIF t.status<>'completed' THEN RAISE EXCEPTION 'Publication outcome requires reconciliation' USING ERRCODE='42501'; END IF;
 DELETE FROM local_identity.native_output_publications WHERE task_id=p_task_id AND attempt=p_attempt AND lease_token=p_lease_token;
END $function$

CREATE OR REPLACE FUNCTION local_identity.freeze_episode_asset_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE root text;BEGIN
 SELECT actual_root INTO root FROM local_identity.account_asset_directories WHERE account_id=NEW.account_id;
 IF root IS NULL THEN
  IF session_user='loop_app' THEN RAISE EXCEPTION '请先在账号配置中设置实际专属目录。' USING ERRCODE='55000';END IF;
  SELECT policy->>'asset_root' INTO root FROM public.account_blueprint_versions WHERE id=NEW.blueprint_version_id;
 END IF;
 IF coalesce(root,'')<>'' THEN INSERT INTO local_identity.episode_asset_locations(episode_id,account_id,asset_root) VALUES(NEW.id,NEW.account_id,root);END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION local_identity.history_external_reference(p_value text, p_episode text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t record;hit boolean;
BEGIN
 FOR t IN SELECT n.nspname,c.relname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','p') LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I r WHERE position($1 in to_jsonb(r)::text)>0 AND NOT local_identity.history_episode_row_matches($3,to_jsonb(r),$2))',t.nspname,t.relname) INTO hit USING p_value,p_episode,t.relname;
  IF hit THEN RETURN true;END IF;
 END LOOP;
 RETURN false;
END $function$

CREATE OR REPLACE FUNCTION local_identity.import_preparation_source(p_episode uuid, p_script uuid, p_source uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes; package public.review_packages; source public.production_material_revisions;
 file public.artifacts; basis local_identity.workspace_preparations; existing local_identity.production_preparation_revisions; parent local_identity.production_preparation_revisions;
 board jsonb; manifest jsonb; evidence jsonb; reference jsonb; actor uuid; actors uuid[]; origin text; next_revision integer;
 shot jsonb; position integer:=0; recorded record;
BEGIN
 SELECT * INTO e FROM public.episodes WHERE id=p_episode FOR UPDATE;
 SELECT * INTO package FROM public.review_packages WHERE id=p_source AND episode_id=p_episode AND stage='storyboard_review';
 SELECT * INTO source FROM public.production_material_revisions WHERE id=p_script AND episode_id=p_episode AND material_type='script';
 IF e.id IS NULL OR package.id IS NULL OR source.id IS NULL THEN RAISE EXCEPTION 'Same-order preparation and script required' USING ERRCODE='22023';END IF;
 IF NOT(EXISTS(SELECT 1 FROM local_identity.workspace_preparations WHERE package_id=p_source AND episode_id=p_episode AND script_revision_id=p_script)
  OR EXISTS(SELECT 1 FROM local_identity.production_workspaces WHERE storyboard_package_id=p_source AND episode_id=p_episode AND script_revision_id=p_script)
  OR EXISTS(SELECT 1 FROM local_identity.production_workspace_versions WHERE storyboard_package_id=p_source AND episode_id=p_episode AND script_revision_id=p_script)) THEN
  RAISE EXCEPTION 'Recorded preparation reference required' USING ERRCODE='42501';
 END IF;
 IF EXISTS(SELECT 1 FROM (
  SELECT episode_id,script_revision_id FROM local_identity.workspace_preparations WHERE package_id=p_source
  UNION SELECT episode_id,script_revision_id FROM local_identity.production_workspaces WHERE storyboard_package_id=p_source
  UNION SELECT episode_id,script_revision_id FROM local_identity.production_workspace_versions WHERE storyboard_package_id=p_source
 ) r WHERE r.episode_id IS DISTINCT FROM p_episode OR r.script_revision_id IS DISTINCT FROM p_script) THEN
  RAISE EXCEPTION 'Conflicting preparation provenance' USING ERRCODE='40001';
 END IF;
 SELECT * INTO file FROM public.artifacts WHERE id=package.artifact_id AND episode_id=p_episode;
 IF file.id IS NULL THEN RAISE EXCEPTION 'Original preparation file reference required' USING ERRCODE='22023';END IF;
 board:=coalesce(package.context_snapshot#>'{worker_result,storyboard}',package.context_snapshot->'storyboard');
 IF board->>'version' IS DISTINCT FROM 'storyboard/v1' OR jsonb_typeof(board->'shots') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Supported original storyboard required' USING ERRCODE='22023';
 END IF;
 IF jsonb_array_length(board->'shots')<1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(board->'shots') s WHERE jsonb_typeof(s->'id') IS DISTINCT FROM 'string' OR btrim(s->>'id')='' OR jsonb_typeof(s->'scriptSegment') IS DISTINCT FROM 'string')
  OR (SELECT count(*)<>count(DISTINCT s->>'id') FROM jsonb_array_elements(board->'shots') s) THEN RAISE EXCEPTION 'Unambiguous original shots required' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM local_identity.workspace_shot_inputs s WHERE s.preparation_id=p_source GROUP BY s.shot_id HAVING count(DISTINCT jsonb_build_object('text',s.baseline_text,'snapshot',s.snapshot,'origin',s.origin,'classification',s.shot_type))>1) THEN
  RAISE EXCEPTION 'Conflicting recorded shot versions' USING ERRCODE='40001';
 END IF;
 IF EXISTS(SELECT 1 FROM local_identity.workspace_shot_inputs s JOIN local_identity.production_workspaces w ON w.id=s.workspace_id WHERE s.preparation_id=p_source AND w.episode_id IS DISTINCT FROM p_episode) THEN
  RAISE EXCEPTION 'Recorded shot belongs to another order' USING ERRCODE='40001';
 END IF;
 manifest:=(board-'version'-'shots')||jsonb_build_object('version','production-preparation/v1','shots',(
  SELECT jsonb_agg((s-'shotType')||jsonb_build_object('visualSource',coalesce(s->>'visualSource','unassigned')) ORDER BY ordinal)
  FROM jsonb_array_elements(board->'shots') WITH ORDINALITY a(s,ordinal)));
 IF package.context_snapshot#>'{workspace_preparation,formattingOnly}'='true'::jsonb THEN
  SELECT * INTO parent FROM local_identity.production_preparation_revisions p WHERE p.episode_id=p_episode
   AND p.id::text=package.context_snapshot#>>'{workspace_preparation,sourceReviewPackageId}'
   AND p.script_revision_id::text=package.context_snapshot#>>'{continued_project,previousScriptRevisionId}'
   AND p.source_format='storyboard/v1' AND p.source_reference_id=p.id AND p.id<>p_source;
  IF parent.id IS NULL THEN RAISE EXCEPTION 'Proven formatting preparation parent required' USING ERRCODE='40001';END IF;
  manifest:=parent.manifest;
 END IF;
 reference:=jsonb_build_object('relativePath',file.relative_path,'sha256',file.sha256,'fileSize',file.file_size);
 IF parent.id IS NOT NULL AND (reference IS DISTINCT FROM parent.file_reference OR board IS DISTINCT FROM coalesce(parent.source_evidence#>'{package,context_snapshot,worker_result,storyboard}',parent.source_evidence#>'{package,context_snapshot,storyboard}')) THEN
  RAISE EXCEPTION 'Formatting source differs from the frozen parent' USING ERRCODE='40001';
 END IF;
 SELECT * INTO existing FROM local_identity.production_preparation_revisions WHERE id=p_source;
 IF FOUND THEN
  IF existing.episode_id IS DISTINCT FROM p_episode OR existing.script_revision_id IS DISTINCT FROM p_script
   OR existing.script_sha256 IS DISTINCT FROM source.sha256 OR existing.source_reference_id IS DISTINCT FROM p_source
   OR existing.source_format<>'storyboard/v1' OR existing.manifest IS DISTINCT FROM manifest OR existing.file_reference IS DISTINCT FROM reference
   OR existing.parent_preparation_revision_id IS DISTINCT FROM parent.id THEN
   RAISE EXCEPTION 'Imported identity conflicts with frozen provenance' USING ERRCODE='40001';
  END IF;
  RETURN p_source;
 END IF;
 SELECT * INTO basis FROM local_identity.workspace_preparations WHERE package_id=p_source;
 actor:=basis.confirmed_by;
 IF actor IS NULL THEN
  SELECT array_agg(DISTINCT created_by) INTO actors FROM local_identity.production_workspace_versions WHERE storyboard_package_id=p_source;
  IF coalesce(array_length(actors,1),0)>1 THEN RAISE EXCEPTION 'Ambiguous preparation creator' USING ERRCODE='40001';END IF;
  actor:=actors[1];
 END IF;
 IF actor IS NULL THEN
  SELECT array_agg(DISTINCT user_id) INTO actors FROM public.account_memberships WHERE account_id=e.account_id AND role='owner';
  IF coalesce(array_length(actors,1),0)<>1 THEN RAISE EXCEPTION 'Proven preparation creator required' USING ERRCODE='40001';END IF;
  actor:=actors[1];
 END IF;
 origin:=coalesce(parent.origin,CASE basis.origin WHEN 'script-segment' THEN 'script' WHEN 'planner' THEN 'plan-import' ELSE 'historical-import' END);
 evidence:=jsonb_build_object('package',to_jsonb(package),'artifact',to_jsonb(file),'preparation',to_jsonb(basis),
  'shot_inputs',CASE WHEN parent.id IS NOT NULL THEN parent.source_evidence->'shot_inputs' ELSE (SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.workspace_id,s.shot_id),'[]'::jsonb) FROM local_identity.workspace_shot_inputs s WHERE s.preparation_id=p_source) END);
 SELECT coalesce(max(revision_number),0)+1 INTO next_revision FROM local_identity.production_preparation_revisions WHERE episode_id=p_episode;
 INSERT INTO local_identity.production_preparation_revisions(id,episode_id,script_revision_id,script_sha256,revision_number,origin,source_format,file_reference,manifest,content_sha256,source_reference_id,source_evidence,created_by,created_at,invalidated_at,parent_preparation_revision_id)
 VALUES(p_source,p_episode,p_script,source.sha256,next_revision,origin,'storyboard/v1',reference,manifest,encode(extensions.digest(manifest::text,'sha256'),'hex'),p_source,evidence,actor,coalesce(basis.confirmed_at,package.created_at),package.invalidated_at,parent.id);
 IF parent.id IS NOT NULL THEN
  INSERT INTO local_identity.production_shots(episode_id,shot_id) SELECT p_episode,shot_id FROM local_identity.production_shot_versions WHERE preparation_revision_id=parent.id ON CONFLICT DO NOTHING;
  INSERT INTO local_identity.production_shot_versions(preparation_revision_id,episode_id,shot_id,position,origin,baseline_text,snapshot)
   SELECT p_source,p_episode,v.shot_id,v.position,v.origin,v.baseline_text,v.snapshot FROM local_identity.production_shot_versions v WHERE v.preparation_revision_id=parent.id;
  RETURN p_source;
 END IF;
 FOR shot IN SELECT value FROM jsonb_array_elements(manifest->'shots') LOOP
  position:=position+1;
  SELECT s.* INTO recorded FROM local_identity.workspace_shot_inputs s WHERE s.preparation_id=p_source AND s.shot_id=shot->>'id' ORDER BY s.workspace_id LIMIT 1;
  INSERT INTO local_identity.production_shots(episode_id,shot_id) VALUES(p_episode,shot->>'id') ON CONFLICT DO NOTHING;
  INSERT INTO local_identity.production_shot_versions(preparation_revision_id,episode_id,shot_id,position,origin,baseline_text,snapshot)
   VALUES(p_source,p_episode,shot->>'id',position,CASE WHEN origin='script' THEN 'script' ELSE 'historical-import' END,coalesce(recorded.baseline_text,shot->>'scriptSegment'),coalesce(recorded.snapshot-'shotType',shot));
 END LOOP;
 FOR recorded IN SELECT DISTINCT ON(s.shot_id) s.* FROM local_identity.workspace_shot_inputs s WHERE s.preparation_id=p_source AND NOT EXISTS(SELECT 1 FROM local_identity.production_shot_versions v WHERE v.preparation_revision_id=p_source AND v.shot_id=s.shot_id) ORDER BY s.shot_id,s.workspace_id LOOP
  position:=position+1;
  INSERT INTO local_identity.production_shots(episode_id,shot_id) VALUES(p_episode,recorded.shot_id) ON CONFLICT DO NOTHING;
  INSERT INTO local_identity.production_shot_versions(preparation_revision_id,episode_id,shot_id,position,origin,baseline_text,snapshot)
   VALUES(p_source,p_episode,recorded.shot_id,position,CASE WHEN recorded.origin='local-added' THEN 'local' ELSE 'historical-import' END,recorded.baseline_text,recorded.snapshot-'shotType');
 END LOOP;
 RETURN p_source;
END $function$

CREATE OR REPLACE FUNCTION local_identity.input_media_connection(p_task_id uuid, p_attempt integer, p_lease_token uuid, p_version_id uuid)
 RETURNS TABLE(version_id uuid, provider text, adapter text, endpoint text, secret_ref uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM local_identity.workspace_pexels_requests r WHERE r.task_id=p_task_id) THEN
  IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501';END IF;
  PERFORM public.refresh_worker_task_lease(p_task_id,p_attempt,p_lease_token);
  IF NOT EXISTS(SELECT 1 FROM local_identity.workspace_pexels_requests r WHERE r.task_id=p_task_id AND local_identity.workspace_task_preparation_current(p_task_id,r.workspace_id)) THEN RAISE EXCEPTION 'Pexels production preparation is stale' USING ERRCODE='55000';END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=p_task_id AND t.task_type='generate_soundtrack' AND EXISTS(SELECT 1 FROM local_identity.workspace_audio_requests r WHERE r.task_id=t.id)) THEN RETURN QUERY SELECT * FROM local_identity.input_media_connection_before_audio_selection(p_task_id,p_attempt,p_lease_token,p_version_id);RETURN;END IF;
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501';END IF;
 PERFORM public.refresh_worker_task_lease(p_task_id,p_attempt,p_lease_token);
 RETURN QUERY SELECT cv.id,cv.provider,cv.adapter,cv.endpoint,b.secret_ref FROM public.tasks t
 JOIN local_identity.input_episodes i ON i.episode_id=t.episode_id AND i.enabled AND i.media_enabled
 JOIN public.external_connection_versions cv ON cv.id=p_version_id AND cv.provider=t.provider AND cv.adapter=t.input_snapshot#>>'{executor,adapter}' AND cv.revoked_at IS NULL
 JOIN public.external_connections cn ON cn.id=cv.connection_id AND cn.created_by=i.owner_id
 JOIN local_identity.connection_bindings b ON b.version_id=cv.id AND b.owner_id=i.owner_id AND b.store_mode='keychain'
 JOIN local_identity.connection_qualifications q ON q.version_id=cv.id AND q.owner_id=i.owner_id AND q.qualified
 WHERE t.id=p_task_id AND t.input_snapshot->>'credential_ref'=cv.id::text AND EXISTS(SELECT 1 FROM local_identity.connection_probe_evidence pe WHERE pe.version_id=cv.id AND pe.owner_id=i.owner_id AND pe.mode='live' AND pe.outcome='verified');
 IF NOT FOUND THEN RAISE EXCEPTION 'Frozen audio connection unavailable';END IF;
END $function$

CREATE OR REPLACE FUNCTION local_identity.input_worker_call_before_publication_fence(p_name text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tasks;d local_identity.workspace_deliveries;candidate_artifact jsonb;pack jsonb;oldstage public.episode_stage;
BEGIN
 SELECT * INTO d FROM local_identity.workspace_deliveries WHERE task_id=(p_args->>'p_task_id')::uuid;
 IF NOT FOUND THEN RETURN local_identity.input_worker_call_before_workspace_delivery(p_name,p_args); END IF;
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501'; END IF;
 -- Match Owner lock order: episode, workspace, task. Completion cannot race editing.
 PERFORM id FROM public.episodes WHERE id=d.episode_id FOR UPDATE;
 PERFORM id FROM local_identity.production_workspaces WHERE id=d.workspace_id FOR UPDATE;
 SELECT * INTO t FROM public.tasks WHERE id=d.task_id FOR UPDATE;
 IF p_name='refresh_worker_task_lease' THEN PERFORM public.refresh_worker_task_lease(t.id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid);
 ELSIF p_name='report_worker_progress' THEN PERFORM public.report_worker_progress(t.id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid,p_args->'p_progress');
 ELSIF p_name='report_worker_result' THEN
  IF p_args#>>'{p_result,status}'='completed' THEN
   IF NOT local_identity.workspace_delivery_current(d.workspace_id,d.export_id) THEN RAISE EXCEPTION 'Confirmed export changed before delivery completion' USING ERRCODE='22023'; END IF;
   IF p_args#>'{p_result,deliveryIdentity}' IS DISTINCT FROM t.input_snapshot#>'{workspace_delivery,identity}' THEN RAISE EXCEPTION 'Result identity mismatch' USING ERRCODE='22023'; END IF;
   SELECT value INTO pack FROM jsonb_array_elements(p_args#>'{p_result,artifacts}') entry(value) WHERE value->>'artifactType'='publish_package';
   IF pack->>'relativePath' IS DISTINCT FROM t.input_snapshot#>>'{output,relative_path}' OR jsonb_array_length(p_args#>'{p_result,artifacts}')<>4 THEN RAISE EXCEPTION 'Delivery manifest mismatch' USING ERRCODE='22023'; END IF;
   FOR candidate_artifact IN SELECT value FROM jsonb_array_elements(t.input_snapshot#>'{workspace_delivery,artifacts}') entry(value) WHERE value->>'artifactType' IN ('cover','metadata','final_qc_report') LOOP
    IF NOT (p_args#>'{p_result,artifacts}') @> jsonb_build_array(candidate_artifact) THEN RAISE EXCEPTION 'Delivery inputs mismatch' USING ERRCODE='22023'; END IF;
   END LOOP;
  END IF;
  PERFORM public.report_worker_result(t.id,(p_args->>'p_attempt')::integer,p_args->'p_result',(p_args->>'p_lease_token')::uuid);
  IF p_args#>>'{p_result,status}'='completed' THEN
   SELECT stage INTO oldstage FROM public.episodes WHERE id=d.episode_id FOR UPDATE;
   UPDATE public.episodes SET stage='production_completed',updated_at=clock_timestamp() WHERE id=d.episode_id;
   INSERT INTO public.state_transitions(episode_id,from_stage,to_stage,reason) VALUES(d.episode_id,oldstage,'production_completed','Exact workspace delivery package verified.');
   INSERT INTO public.audit_events(account_id,episode_id,event_type,payload) SELECT account_id,id,'publish_package_verified',jsonb_build_object('task_id',t.id,'export_id',d.export_id,'sha256',pack->>'sha256','to_stage','production_completed','protocol','publish-package/v2') FROM public.episodes WHERE id=d.episode_id;
  END IF;
 ELSE RAISE EXCEPTION 'Unsupported Worker command' USING ERRCODE='22023'; END IF;
 RETURN 'null'::jsonb;
END $function$

CREATE OR REPLACE FUNCTION local_identity.input_worker_call_before_workspace_delivery(p_name text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE selected_task_id uuid:=(p_args->>'p_task_id')::uuid; frozen jsonb; paths text[]; authority jsonb;
BEGIN
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' OR NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=selected_task_id AND local_identity.input_task_allowed(t.episode_id,t.task_type)) THEN RAISE EXCEPTION 'Managed input Worker task required' USING ERRCODE='42501'; END IF;
 IF p_name='refresh_worker_task_lease' THEN PERFORM public.refresh_worker_task_lease(selected_task_id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid);
 ELSIF p_name='report_worker_progress' THEN PERFORM public.report_worker_progress(selected_task_id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid,p_args->'p_progress');
 ELSIF p_name='report_worker_result' THEN
  IF p_args#>>'{p_result,status}'='completed' THEN
   PERFORM public.assert_worker_lease(selected_task_id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid);
   SELECT input_snapshot->'output' INTO frozen FROM public.tasks WHERE id=selected_task_id;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_args#>'{p_result,artifacts}') a WHERE a->>'artifactType'=frozen#>>'{required_artifact_types,0}' AND a->>'relativePath'=frozen->>'relative_path') THEN RAISE EXCEPTION 'Completed result requires the frozen primary path' USING ERRCODE='22023'; END IF;
   SELECT array_agg(a->>'relativePath') INTO paths FROM jsonb_array_elements(p_args#>'{p_result,artifacts}') a;
   authority:=local_identity.native_output_authority(selected_task_id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid,paths);
   IF jsonb_array_length(authority->'conflicts')>0 THEN RAISE EXCEPTION 'Output path is indexed by another task' USING ERRCODE='22023'; END IF;
  END IF;
  IF p_args#>>'{p_result,status}'='completed' AND EXISTS(SELECT 1 FROM public.tasks WHERE id=selected_task_id AND provider IN ('bailian','volcengine','minimax','kling')) THEN
 PERFORM local_identity.register_wan_material(selected_task_id,(p_args->>'p_attempt')::integer,(p_args->>'p_lease_token')::uuid,p_args#>>'{p_result,artifacts,0,relativePath}',p_args#>>'{p_result,artifacts,0,sha256}',(p_args#>>'{p_result,artifacts,0,fileSize}')::bigint);
 END IF;
 PERFORM public.report_worker_result(selected_task_id,(p_args->>'p_attempt')::integer,p_args->'p_result',(p_args->>'p_lease_token')::uuid);
 ELSE RAISE EXCEPTION 'Unsupported Worker command' USING ERRCODE='22023'; END IF;
 RETURN 'null'::jsonb;
END $function$

CREATE OR REPLACE FUNCTION local_identity.lock_account_directory_migration(p_account uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ BEGIN
 IF NOT local_identity.lock_owned_account_row(p_account) THEN RAISE EXCEPTION '账号不可见。' USING ERRCODE='42501';END IF;
 PERFORM id FROM public.episodes WHERE account_id=p_account ORDER BY id FOR UPDATE;
 PERFORM t.id FROM public.tasks t JOIN public.episodes e ON e.id=t.episode_id WHERE e.account_id=p_account ORDER BY t.id FOR UPDATE;
END $function$

CREATE OR REPLACE FUNCTION local_identity.lock_current_production_workspace(p_workspace uuid)
 RETURNS local_identity.production_workspaces
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces; e public.episodes;
BEGIN
 SELECT * INTO w FROM local_identity.production_workspaces WHERE id=p_workspace FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(w.episode_id) THEN RAISE EXCEPTION 'Current Owner workspace required' USING ERRCODE='42501';END IF;
 SELECT * INTO e FROM public.episodes WHERE id=w.episode_id;
 IF e.archived_at IS NOT NULL OR e.stage='production_completed' OR local_identity.is_historical_episode(e.id)
  OR e.main_script_revision_id IS DISTINCT FROM w.script_revision_id OR NOT EXISTS(
   SELECT 1 FROM local_identity.production_preparation_revisions p WHERE p.id=w.preparation_revision_id AND p.episode_id=e.id
    AND p.script_revision_id=w.script_revision_id AND local_identity.preparation_source_current(p.id)) THEN
  RAISE EXCEPTION 'Current confirmed workspace preparation required' USING ERRCODE='40001';
 END IF;
 RETURN w;
END $function$

CREATE OR REPLACE FUNCTION local_identity.lock_history_deletion_inventory(p_session_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t record;
BEGIN
 IF session_user<>'loop_app' OR NOT EXISTS(SELECT 1 FROM local_identity.sessions WHERE token_hash=p_session_hash AND owner_id=local_identity.owner_id() AND revoked_at IS NULL AND expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'Verified Owner session required' USING ERRCODE='42501';END IF;
 FOR t IN SELECT n.nspname,c.relname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p') AND (n.nspname='public' OR n.nspname='local_identity' AND c.relname IN('history_sources','history_versions','history_source_rows','history_files','history_retained_files','history_file_protections','history_projection_results')) ORDER BY n.nspname,c.relname LOOP
  EXECUTE format('LOCK TABLE %I.%I IN SHARE ROW EXCLUSIVE MODE NOWAIT',t.nspname,t.relname);
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION local_identity.lock_owned_connection(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM 1 FROM public.external_connections WHERE id=p_id AND created_by=local_identity.owner_id() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Connection not found' USING ERRCODE='P0002'; END IF;
 RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION local_identity.lock_owned_episode_deletion(p_episode_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ BEGIN
 IF NOT local_identity.lock_owned_episode_cleanup(p_episode_id) THEN RETURN false; END IF;
 PERFORM id FROM public.tasks WHERE episode_id=p_episode_id ORDER BY id FOR UPDATE NOWAIT;
 IF NOT EXISTS(SELECT 1 FROM public.episodes WHERE id=p_episode_id AND archived_at IS NOT NULL) OR EXISTS(SELECT 1 FROM public.tasks WHERE episode_id=p_episode_id AND status='running') OR EXISTS(SELECT 1 FROM public.asset_locks WHERE episode_id=p_episode_id AND expires_at>now()) THEN RAISE EXCEPTION 'Archived Episode without active work required' USING ERRCODE='55000'; END IF; RETURN true;
END $function$

CREATE OR REPLACE FUNCTION local_identity.lock_owned_revision_tasks(p_episode uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned revision required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.episodes e WHERE e.id=p_episode AND e.archived_at IS NULL AND e.stage='qc_review' AND NOT local_identity.is_historical_episode(e.id)) THEN RAISE EXCEPTION 'Current editable review required' USING ERRCODE='55000';END IF;
 PERFORM id FROM public.tasks WHERE episode_id=p_episode AND invalidated_at IS NULL FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.tasks WHERE episode_id=p_episode AND invalidated_at IS NULL AND status='running') THEN RAISE EXCEPTION 'Current production task is running' USING ERRCODE='55000';END IF;
END $function$

CREATE OR REPLACE FUNCTION local_identity.mark_provider_dispatching(p_task uuid, p_attempt integer, p_lease uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f local_identity.provider_dispatch_facts;t public.tasks;
BEGIN
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501';END IF;
 PERFORM public.refresh_worker_task_lease(p_task,p_attempt,p_lease);
 SELECT * INTO t FROM public.tasks WHERE id=p_task FOR UPDATE;
 SELECT * INTO f FROM local_identity.provider_dispatch_facts WHERE task_id=p_task AND attempt=p_attempt AND lease_token=p_lease;
 IF NOT FOUND OR f.phase<>'reserved' OR f.request_hash<>md5(t.input_snapshot::text) OR NOT local_identity.provider_dispatch_context_current(p_task,f.kind) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts WHERE task_id=p_task AND phase IN ('dispatching','received')) THEN RAISE EXCEPTION 'Previous dispatch requires reconciliation' USING ERRCODE='55000';END IF;
 UPDATE local_identity.provider_dispatch_facts SET phase='dispatching',updated_at=clock_timestamp() WHERE task_id=p_task AND attempt=p_attempt;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION local_identity.media_root_publication_proof(p_id uuid, p_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m local_identity.media_root_migrations;ep jsonb;d jsonb;t jsonb;runtime_dirs jsonb:='[]';BEGIN
 IF session_user NOT IN ('loop_app','postgres') THEN RAISE EXCEPTION 'Trusted runtime required';END IF;
 SELECT * INTO m FROM local_identity.media_root_migrations WHERE id=p_id;
 IF NOT FOUND OR m.manifest_sha256<>p_sha OR p_sha<>encode(sha256(convert_to(m.manifest::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'Migration manifest authority missing';END IF;
 PERFORM set_config('loop.owner_id',m.owner_id::text,true);
 IF m.status IN ('committed','completed') THEN
  IF local_identity.media_root_binding() IS DISTINCT FROM m.manifest->'targetBinding' OR NOT EXISTS(SELECT 1 FROM local_identity.storage_location_operations o WHERE o.media_root_migration_id=m.id AND o.kind='root_migration' AND o.proof=m.publication AND o.proof_sha256=encode(sha256(convert_to(o.proof::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'Migration publication incomplete';END IF;
  IF m.status='completed' THEN
   -- Completed proof is history. Legitimate later moves append verified edges;
   -- explicit deletion removes live edges but never rewrites this operation.
   FOR t IN SELECT value FROM jsonb_array_elements(m.publication->'bindings') LOOP
    IF EXISTS(SELECT 1 FROM public.episodes WHERE id=(t->>'episodeId')::uuid) THEN
     IF NOT EXISTS(WITH RECURSIVE edges AS(SELECT * FROM local_identity.episode_completed_storage_lineage((t->>'episodeId')::uuid)),walk(root,prefix,device,inode) AS(
      SELECT t->>'actualRoot',t->>'relativePath',t->>'deviceId',t->>'inodeId'
      UNION SELECT e.target_root,e.target_prefix,e.target_device_id,e.target_inode_id FROM walk w JOIN edges e ON (w.root,w.prefix,w.device,w.inode)=(e.source_root,e.source_prefix,e.source_device_id,e.source_inode_id))
      SELECT 1 FROM walk w CROSS JOIN local_identity.episode_storage_location((t->>'episodeId')::uuid) l WHERE (w.root,w.prefix,w.device,w.inode)=(local_identity.storage_physical_root(l.asset_root),l.directory_relative_path,l.directory_device_id,l.directory_inode_id))
      OR NOT EXISTS(SELECT 1 FROM local_identity.episode_completed_storage_lineage((t->>'episodeId')::uuid) l WHERE l.operation_id='root-migration:'||m.id::text) THEN RAISE EXCEPTION 'Completed migration has no valid current lineage';END IF;
     SELECT to_jsonb(l) INTO ep FROM local_identity.episode_storage_location((t->>'episodeId')::uuid) l;
     runtime_dirs:=runtime_dirs||jsonb_build_array(jsonb_build_object('path',local_identity.storage_physical_root(ep->>'asset_root')||'/'||(ep->>'directory_relative_path'),'device',ep->>'directory_device_id','inode',ep->>'directory_inode_id'));
    END IF;
   END LOOP;
   FOR d IN SELECT jsonb_build_object('path',a.actual_root,'device',a.device_id,'inode',a.inode_id) FROM local_identity.account_asset_directories a WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(m.manifest->'accounts') x WHERE x->>'id'=a.account_id::text) LOOP
    IF left(d->>'path',length(m.manifest->'targetBinding'->>'path')+1)<>(m.manifest->'targetBinding'->>'path')||'/' THEN RAISE EXCEPTION 'Current account root leaves media binding';END IF;
    runtime_dirs:=runtime_dirs||jsonb_build_array(d);
   END LOOP;
   FOR d IN SELECT jsonb_build_object('path',a.actual_root||'/'||c.directory_relative_path,'device',c.device_id,'inode',c.inode_id) FROM local_identity.account_storage_containers c JOIN local_identity.account_asset_directories a ON a.account_id=c.account_id WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(m.manifest->'accounts') x WHERE x->>'id'=a.account_id::text) LOOP runtime_dirs:=runtime_dirs||jsonb_build_array(d);END LOOP;
   RETURN to_jsonb(m)||jsonb_build_object('runtimeDirectories',runtime_dirs);
  END IF;
  FOR t IN SELECT value FROM jsonb_array_elements(m.publication->'bindings') LOOP
   IF NOT EXISTS(SELECT 1 FROM local_identity.episode_storage_location((t->>'episodeId')::uuid) l WHERE (l.asset_root,l.directory_relative_path,l.directory_device_id,l.directory_inode_id)=(t->>'actualRoot',t->>'relativePath',t->>'deviceId',t->>'inodeId')) OR NOT EXISTS(SELECT 1 FROM local_identity.episode_completed_storage_lineage((t->>'episodeId')::uuid) l WHERE l.operation_id='root-migration:'||m.id::text) THEN RAISE EXCEPTION 'Migration episode publication mismatch';END IF;
  END LOOP;
  FOR d IN SELECT value FROM jsonb_array_elements(m.manifest->'directories') WHERE value->>'kind' IN ('account','series','unassigned') LOOP
   SELECT value INTO t FROM jsonb_array_elements(m.publication->'directories') WHERE value->>'sourcePath'=d->'source'->>'path';
   IF d->>'kind'='account' THEN
    IF NOT EXISTS(SELECT 1 FROM local_identity.account_asset_directories a WHERE a.account_id=(d->>'accountId')::uuid AND (a.actual_root,a.device_id,a.inode_id)=(t->>'path',t->>'device',t->>'inode')) THEN RAISE EXCEPTION 'Migration account publication mismatch';END IF;
   ELSIF NOT EXISTS(SELECT 1 FROM local_identity.account_storage_containers c WHERE c.id=(d->>'containerId')::uuid AND (c.device_id,c.inode_id)=(t->>'device',t->>'inode')) THEN RAISE EXCEPTION 'Migration container publication mismatch';END IF;
  END LOOP;
 ELSE
  IF m.status NOT IN ('copying','failed') OR local_identity.media_root_binding() IS DISTINCT FROM m.manifest->'sourceBinding' THEN RAISE EXCEPTION 'Migration source publication mismatch';END IF;
 END IF;
 RETURN to_jsonb(m);
END $function$

CREATE OR REPLACE FUNCTION local_identity.namespace_native_task_output()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prefix text; base text; path text; field text; location record;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'ready' OR NEW.attempt<>0
   OR NEW.task_type NOT IN ('generate_shot_video','search_shot_video','preview_shot_video','prepare_visual_brief','draft_storyboard','draft_storyboard_revision','generate_narration','generate_a_roll','generate_b_roll','generate_soundtrack','extract_embedded_audio','align_shot_captions','generate_shot_sync_preview','generate_review_render','generate_final_render')
   OR NOT EXISTS(SELECT 1 FROM local_identity.input_episodes e WHERE e.episode_id=NEW.episode_id AND e.enabled) THEN RETURN NEW; END IF;
  SELECT * INTO STRICT location FROM local_identity.episode_storage_location(NEW.episode_id);
  NEW.input_snapshot:=NEW.input_snapshot||jsonb_build_object('native_output_namespace',NEW.id::text,'native_episode_relative_path',location.directory_relative_path,'native_episode_directory_identity',jsonb_build_object('deviceId',location.directory_device_id,'inodeId',location.directory_inode_id));
 ELSE
  IF OLD.input_snapshot->>'native_output_namespace' IS DISTINCT FROM OLD.id::text THEN RETURN NEW; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.task_type IS DISTINCT FROM OLD.task_type OR NEW.episode_id IS DISTINCT FROM OLD.episode_id OR NEW.input_snapshot->>'native_output_namespace' IS DISTINCT FROM OLD.id::text OR NEW.input_snapshot->'native_episode_relative_path' IS DISTINCT FROM OLD.input_snapshot->'native_episode_relative_path' OR NEW.input_snapshot->'native_episode_directory_identity' IS DISTINCT FROM OLD.input_snapshot->'native_episode_directory_identity' THEN RAISE EXCEPTION 'Native output identity is immutable' USING ERRCODE='22023'; END IF;
  IF NEW.attempt<>0 OR OLD.attempt<>0 THEN
   IF NEW.input_snapshot#>'{output}' IS DISTINCT FROM OLD.input_snapshot#>'{output}' OR NEW.input_snapshot#>'{review_render,project_relative_path}' IS DISTINCT FROM OLD.input_snapshot#>'{review_render,project_relative_path}' OR NEW.input_snapshot#>'{final_render,project_relative_path}' IS DISTINCT FROM OLD.input_snapshot#>'{final_render,project_relative_path}' THEN RAISE EXCEPTION 'Claimed native output is immutable' USING ERRCODE='22023'; END IF;
   RETURN NEW;
  END IF;
 END IF;
 base:=coalesce(NEW.input_snapshot->>'native_episode_relative_path','episodes/'||NEW.episode_id::text);
 prefix:=format('%s/native-tasks/%s/',base,NEW.id);
 path:=NEW.input_snapshot#>>'{output,relative_path}';
 IF path IS NULL OR (left(path,length(base)+1)<>base||'/' AND left(path,length('episodes/'||NEW.episode_id::text)+1)<>'episodes/'||NEW.episode_id::text||'/') OR path ~ '(^|/)\.\.(/|$)' OR path ~ E'\\\\' OR path ~ '/$' THEN RAISE EXCEPTION 'Native output path is invalid' USING ERRCODE='22023'; END IF;
 NEW.input_snapshot:=jsonb_set(NEW.input_snapshot,'{output,relative_path}',to_jsonb(prefix||regexp_replace(path,'^.*/','')));
 FOREACH field IN ARRAY ARRAY['review_render','final_render'] LOOP
  path:=NEW.input_snapshot#>>ARRAY[field,'project_relative_path'];
  IF path IS NOT NULL THEN
   IF (left(path,length(base)+1)<>base||'/' AND left(path,length('episodes/'||NEW.episode_id::text)+1)<>'episodes/'||NEW.episode_id::text||'/') OR path ~ '(^|/)\.\.(/|$)' OR path ~ E'\\\\' OR path ~ '/$' THEN RAISE EXCEPTION 'Native output project path is invalid' USING ERRCODE='22023'; END IF;
   NEW.input_snapshot:=jsonb_set(NEW.input_snapshot,ARRAY[field,'project_relative_path'],to_jsonb(prefix||regexp_replace(path,'^.*/','')));
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION local_identity.namespace_workspace_image_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE location record;
BEGIN
 IF NEW.task_type<>'generate_static_visual' THEN RETURN NEW;END IF;
 IF NEW.provider<>'openai' OR NEW.model NOT IN ('gpt-image-2','gpt-image-2.5-sunburst','gpt-image-2.5-flare','gpt-image-2.5-sunburst-2026-09-08','gpt-image-2.5-flare-2026-09-08','gpt-image-2.6-sunburst','gpt-image-2.6-flare') OR NEW.model IS DISTINCT FROM NEW.input_snapshot#>>'{executor,model}' OR NEW.status<>'ready' OR NEW.attempt<>0 OR NOT EXISTS(SELECT 1 FROM local_identity.workspace_visual_candidates v WHERE v.id::text=NEW.input_snapshot->>'workspace_image_request_id' AND v.episode_id=NEW.episode_id AND v.request_snapshot->>'kind'='image') THEN RAISE EXCEPTION 'Explicit workspace image request required';END IF;
 SELECT * INTO STRICT location FROM local_identity.episode_storage_location(NEW.episode_id);
 NEW.input_snapshot:=jsonb_set(NEW.input_snapshot||jsonb_build_object('native_output_namespace',NEW.id::text,'native_episode_relative_path',location.directory_relative_path,'native_episode_directory_identity',jsonb_build_object('deviceId',location.directory_device_id,'inodeId',location.directory_inode_id)),'{output,relative_path}',to_jsonb(format('%s/native-tasks/%s/image.png',location.directory_relative_path,NEW.id)));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION local_identity.native_output_authority(p_task_id uuid, p_attempt integer, p_lease_token uuid, p_paths text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE selected public.tasks; run public.task_runs; path text; prefix text; base text; allowed text[]; indexed jsonb; conflicts jsonb;
BEGIN
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO selected FROM public.tasks WHERE id=p_task_id FOR UPDATE;
 IF NOT FOUND OR selected.invalidated_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM local_identity.input_episodes e WHERE e.episode_id=selected.episode_id) OR selected.attempt<>p_attempt+1 OR p_lease_token IS NULL THEN RAISE EXCEPTION 'Current native task identity required' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM public.task_runs WHERE task_id=p_task_id AND attempt=p_attempt AND lease_token=p_lease_token;
 IF NOT FOUND THEN RAISE EXCEPTION 'Current native attempt identity required' USING ERRCODE='42501'; END IF;
 IF selected.status='running' THEN
  IF NOT local_identity.input_task_allowed(selected.episode_id,selected.task_type) THEN RAISE EXCEPTION 'Native task disabled' USING ERRCODE='42501'; END IF;
  PERFORM public.assert_worker_lease(p_task_id,p_attempt,p_lease_token);
 ELSIF selected.status<>'completed' OR run.status<>'completed' OR selected.last_result->>'status' IS DISTINCT FROM 'completed' OR run.result IS DISTINCT FROM selected.last_result THEN RAISE EXCEPTION 'Native task result is not recoverable' USING ERRCODE='42501'; END IF;
 IF p_paths IS NULL OR cardinality(p_paths)=0 OR cardinality(p_paths)>256 THEN RAISE EXCEPTION 'Publication paths required' USING ERRCODE='22023'; END IF;
 base:=coalesce(selected.input_snapshot->>'native_episode_relative_path','episodes/'||selected.episode_id::text);
 prefix:=format('%s/native-tasks/%s/',base,selected.id);
 allowed:=ARRAY[selected.input_snapshot#>>'{output,relative_path}',format('%s/card-video/%s/project.json',base,selected.id)];
 FOREACH path IN ARRAY ARRAY[selected.input_snapshot#>>'{review_render,project_relative_path}',selected.input_snapshot#>>'{final_render,project_relative_path}'] LOOP
  IF path IS NOT NULL THEN allowed:=allowed||ARRAY[path,regexp_replace(path,'[^/]+$','project.json'),regexp_replace(path,'[^/]+$','openchatcut-runtime.json'),regexp_replace(path,'[^/]+$','qc-report.json'),regexp_replace(path,'[^/]+$','final-qc-report.json')]; END IF;
 END LOOP;
 FOR path IN SELECT DISTINCT value FROM unnest(p_paths) value ORDER BY value LOOP
  IF path IS NULL OR left(path,length(base)+1)<>base||'/' OR path ~ '(^|/)\.\.(/|$)' OR path ~ E'\\\\' OR path ~ '/$' THEN RAISE EXCEPTION 'Publication path outside native Episode' USING ERRCODE='22023'; END IF;
  IF left(path,length(prefix))<>prefix AND NOT coalesce(path=ANY(allowed),false) THEN RAISE EXCEPTION 'Publication path is not frozen for this task' USING ERRCODE='42501'; END IF;
  IF selected.input_snapshot->>'native_output_namespace'=selected.id::text AND left(path,length(prefix))<>prefix AND path<>format('%s/card-video/%s/project.json',base,selected.id) THEN RAISE EXCEPTION 'New native output must use its task namespace' USING ERRCODE='42501'; END IF;
  IF local_identity.episode_current_reference(selected.episode_id,path) IS NULL THEN RAISE EXCEPTION 'Publication location proof missing' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('native-output:'||selected.episode_id::text||':'||local_identity.episode_current_reference(selected.episode_id,path),0));
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('artifactType',a.artifact_type,'relativePath',a.relative_path,'sha256',a.sha256,'fileSize',a.file_size)),'[]'::jsonb) INTO indexed FROM public.artifacts a WHERE a.producer_task_id=p_task_id AND a.relative_path=ANY(p_paths);
 SELECT coalesce(jsonb_agg(jsonb_build_object('artifactType',a.artifact_type,'relativePath',a.relative_path,'sha256',a.sha256,'fileSize',a.file_size)),'[]'::jsonb) INTO conflicts FROM public.artifacts a WHERE a.producer_task_id IS DISTINCT FROM p_task_id AND a.episode_id=selected.episode_id AND local_identity.episode_current_reference(selected.episode_id,a.relative_path) IN (SELECT local_identity.episode_current_reference(selected.episode_id,p) FROM unnest(p_paths) p);
 RETURN jsonb_build_object('output',selected.input_snapshot->'output','reviewProjectPath',selected.input_snapshot#>'{review_render,project_relative_path}','finalProjectPath',selected.input_snapshot#>'{final_render,project_relative_path}','status',selected.status,'inputHash',md5(selected.input_snapshot::text),'result',selected.last_result,'artifacts',indexed,'conflicts',conflicts);
END $function$

CREATE OR REPLACE FUNCTION local_identity.prepare_provider_dispatch(p_task uuid, p_attempt integer, p_lease uuid, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tasks;f local_identity.provider_dispatch_facts;prior local_identity.provider_dispatch_facts;r text;ok boolean;
BEGIN
 IF local_identity.actor_role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Worker required' USING ERRCODE='42501';END IF;
 PERFORM public.refresh_worker_task_lease(p_task,p_attempt,p_lease);
 SELECT * INTO t FROM public.tasks WHERE id=p_task FOR UPDATE;
 IF p_kind NOT IN ('speech','image') THEN RAISE EXCEPTION 'Invalid dispatch kind' USING ERRCODE='22023';END IF;
 IF NOT local_identity.provider_dispatch_context_current(p_task,p_kind) THEN RETURN jsonb_build_object('phase','not_sent','reason','input_changed');END IF;
 IF EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts x WHERE x.task_id=p_task AND (x.request_hash<>md5(t.input_snapshot::text) OR x.kind<>p_kind)) THEN RETURN jsonb_build_object('phase','not_sent','reason','input_changed');END IF;
 IF EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts x WHERE x.task_id=p_task AND x.phase IN ('dispatching','received')) THEN RETURN jsonb_build_object('phase','unknown','reason','previous_submission');END IF;
 IF EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts x WHERE x.task_id=p_task AND x.phase='rejected') THEN RETURN jsonb_build_object('phase','not_sent','reason','previous_rejected');END IF;
 SELECT * INTO f FROM local_identity.provider_dispatch_facts WHERE task_id=p_task AND attempt=p_attempt;
 IF FOUND AND f.lease_token IS DISTINCT FROM p_lease THEN RAISE EXCEPTION 'Dispatch fence changed' USING ERRCODE='42501';END IF;
 SELECT * INTO prior FROM local_identity.provider_dispatch_facts WHERE task_id=p_task AND phase='reserved' ORDER BY attempt DESC LIMIT 1;
 -- No new-protocol proof: a historical reservation remains unknown forever.
 IF prior.task_id IS NULL AND (EXISTS(SELECT 1 FROM public.paid_generation_reservations WHERE task_id=p_task)
  OR EXISTS(SELECT 1 FROM local_identity.workspace_narration_submissions WHERE task_id=p_task)
  OR EXISTS(SELECT 1 FROM local_identity.workspace_visual_submissions WHERE task_id=p_task)) THEN RETURN jsonb_build_object('phase','unknown','reason','legacy_submission');END IF;
 INSERT INTO local_identity.provider_dispatch_facts(task_id,attempt,lease_token,kind,request_hash,phase)
 VALUES(p_task,p_attempt,p_lease,p_kind,md5(t.input_snapshot::text),'preparing') ON CONFLICT DO NOTHING;
 IF prior.task_id IS NOT NULL THEN r:=prior.route;
 ELSIF p_kind='speech' THEN
  r:=local_identity.reserve_workspace_narration_route(p_task,p_attempt,p_lease);
  IF r IS NULL THEN
   UPDATE local_identity.provider_dispatch_facts SET last_reason='input_or_prior_request',updated_at=clock_timestamp() WHERE task_id=p_task AND attempt=p_attempt;
   RETURN jsonb_build_object('phase','not_sent','reason','input_or_prior_request');
  END IF;
 ELSE
  PERFORM local_identity.reserve_workspace_images(p_task,p_attempt,p_lease);r:='confirmed';
 END IF;
 UPDATE local_identity.provider_dispatch_facts SET phase='reserved',route=r,last_reason=NULL,updated_at=clock_timestamp() WHERE task_id=p_task AND attempt=p_attempt;
 RETURN jsonb_build_object('phase','reserved','route',r);
END $function$

CREATE OR REPLACE FUNCTION local_identity.production_metrics_activity()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid:=local_identity.owner_id(); q integer; r integer; w integer; capacity integer;
BEGIN
 IF o IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF NOT local_identity.production_metrics_enabled() THEN RETURN jsonb_build_object('enabled',false,'queued',0,'running',0,'resourceWait',0);END IF;
 SELECT s.capacity INTO capacity FROM public.worker_scheduler_settings s WHERE singleton;
 capacity:=coalesce(capacity,1);
 WITH owned AS (SELECT t.*,public.worker_resource_limits(t.input_snapshot,capacity) limits FROM public.tasks t JOIN public.episodes e ON e.id=t.episode_id WHERE t.status IN ('ready','running') AND NOT e.is_test AND e.archived_at IS NULL AND t.invalidated_at IS NULL AND local_identity.current_worker_task(t) AND NOT EXISTS(SELECT 1 FROM local_identity.episode_recycle_bin b WHERE b.episode_id=e.id) AND EXISTS(SELECT 1 FROM public.account_memberships m WHERE m.account_id=e.account_id AND m.user_id=o AND m.role='owner')),
 busy AS (SELECT public.worker_resource_limits(t.input_snapshot,capacity) limits FROM public.tasks t WHERE t.status='running' AND t.claimed_at>clock_timestamp()-interval '30 minutes' AND local_identity.current_worker_task(t))
 SELECT count(*) FILTER(WHERE status='ready'),count(*) FILTER(WHERE status='running' AND claimed_at>clock_timestamp()-interval '30 minutes'),count(*) FILTER(WHERE status='ready' AND available_at<=clock_timestamp() AND EXISTS(SELECT 1 FROM jsonb_array_elements(owned.limits) lim WHERE (SELECT count(*) FROM busy WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(busy.limits) used WHERE used->>'key'=lim->>'key'))>=(lim->>'limit')::integer)) INTO q,r,w FROM owned;
 RETURN jsonb_build_object('enabled',true,'queued',q,'running',r,'resourceWait',w);
END $function$

CREATE OR REPLACE FUNCTION local_identity.prune_production_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid:=local_identity.owner_id(); events integer; resources integer; daily integer; cycles integer; quality integer; tasks integer; deliveries integer; coverage integer; resource_daily integer;
BEGIN
 IF o IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 DELETE FROM local_identity.production_metric_events WHERE owner_id=o AND occurred_at<clock_timestamp()-interval '12 months';GET DIAGNOSTICS events=ROW_COUNT;
 DELETE FROM local_identity.production_metric_resources WHERE owner_id=o AND sampled_at<clock_timestamp()-interval '30 days';GET DIAGNOSTICS resources=ROW_COUNT;
 DELETE FROM local_identity.production_metric_daily WHERE owner_id=o AND day<(clock_timestamp() AT TIME ZONE 'Asia/Shanghai')::date-interval '24 months';GET DIAGNOSTICS daily=ROW_COUNT;
 DELETE FROM local_identity.production_metric_resource_daily WHERE owner_id=o AND day<(clock_timestamp() AT TIME ZONE 'Asia/Shanghai')::date-interval '24 months';GET DIAGNOSTICS resource_daily=ROW_COUNT;
 DELETE FROM local_identity.production_metric_queue_cycles WHERE owner_id=o AND coalesce(claimed_at,enqueued_at)<clock_timestamp()-interval '12 months' AND EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=task_id AND t.status NOT IN ('ready','running'));GET DIAGNOSTICS cycles=ROW_COUNT;
 DELETE FROM local_identity.production_metric_quality_versions v WHERE owner_id=o AND created_at<clock_timestamp()-interval '12 months' AND EXISTS(SELECT 1 FROM local_identity.production_metric_quality_versions newer WHERE newer.owner_id=v.owner_id AND newer.episode_id=v.episode_id AND newer.revision>v.revision);GET DIAGNOSTICS quality=ROW_COUNT;
 DELETE FROM local_identity.production_metric_task_quality q WHERE owner_id=o AND frozen_at<clock_timestamp()-interval '12 months' AND EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=q.task_id AND t.status NOT IN ('ready','running'));GET DIAGNOSTICS tasks=ROW_COUNT;
 DELETE FROM local_identity.production_metric_delivery_quality WHERE owner_id=o AND frozen_at<clock_timestamp()-interval '12 months';GET DIAGNOSTICS deliveries=ROW_COUNT;
 DELETE FROM local_identity.production_metric_coverage_periods WHERE owner_id=o AND ended_at<clock_timestamp()-interval '24 months';GET DIAGNOSTICS coverage=ROW_COUNT;
 RETURN jsonb_build_object('events',events,'resources',resources,'daily',daily,'resourceDaily',resource_daily,'queueCycles',cycles,'obsoleteQualityVersions',quality,'finishedTaskSnapshots',tasks,'deliverySnapshots',deliveries,'coveragePeriods',coverage);
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_owned_final_render(p_episode_id uuid)
 RETURNS SETOF public.tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE t public.tasks; prefix text; BEGIN
 IF NOT local_identity.owned_delivery_episode(p_episode_id) THEN RAISE EXCEPTION 'Owned delivery Episode required' USING ERRCODE='42501'; END IF;
 FOR t IN SELECT * FROM public.orchestrate_final_render_tasks(p_episode_id) LOOP
  IF t.status<>'ready' OR t.attempt<>0 OR t.created_at<>transaction_timestamp() THEN RAISE EXCEPTION 'Fresh final task required' USING ERRCODE='42501'; END IF;
  prefix:=format('%s/final-render/%s',(SELECT directory_relative_path FROM local_identity.episode_storage_location(p_episode_id)),t.id);
  UPDATE public.tasks SET input_snapshot=jsonb_set(jsonb_set(input_snapshot,'{output,relative_path}',to_jsonb(prefix||'/final-render.mp4')),'{final_render,project_relative_path}',to_jsonb(prefix||'/index.html')) WHERE id=t.id RETURNING * INTO t; RETURN NEXT t;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_selected_workspace_narration(p_workspace uuid, p_shot text, p_snapshot jsonb, p_retry boolean)
 RETURNS public.tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces;n local_identity.workspace_narrations;d local_identity.workspace_narration_inputs;a local_identity.script_productions;e public.episodes;t public.tasks;cfg jsonb;frozen jsonb;amount integer;hash text;caption_text text;BEGIN
 w:=local_identity.lock_current_production_workspace(p_workspace);
 PERFORM pg_advisory_xact_lock(hashtextextended(w.id::text||p_shot,0));
 SELECT * INTO e FROM public.episodes WHERE id=w.episode_id;
 SELECT * INTO a FROM local_identity.workspace_production_authorizations WHERE episode_id=e.id AND enabled AND authorized_at IS NOT NULL AND script_revision_id=w.script_revision_id AND authorization_hash=local_identity.current_workspace_call_hash(w.id);
 SELECT * INTO n FROM local_identity.workspace_narrations WHERE workspace_id=w.id AND shot_id=p_shot;
 SELECT * INTO d FROM local_identity.workspace_narration_inputs WHERE workspace_id=w.id AND preparation_revision_id=w.preparation_revision_id AND shot_id=p_shot;
 SELECT contract->>'text' INTO caption_text FROM local_identity.workspace_caption_inputs WHERE workspace_id=w.id AND preparation_revision_id=w.preparation_revision_id AND shot_id=p_shot;
 IF btrim(coalesce(caption_text,''))='' THEN caption_text:=d.narration_text;END IF;
 IF e.archived_at IS NOT NULL OR e.stage='production_completed' OR e.main_script_revision_id<>w.script_revision_id OR a.authorization_hash IS NULL OR a.authorization_hash IS DISTINCT FROM p_snapshot->>'authorizationHash' OR n.mode<>'tts' OR n.confirmed_fingerprint IS DISTINCT FROM n.input_fingerprint OR n.input_fingerprint IS DISTINCT FROM p_snapshot->>'inputFingerprint' OR n.selection IS DISTINCT FROM p_snapshot->'selection' OR NOT local_identity.preparation_source_current(w.preparation_revision_id) THEN RAISE EXCEPTION 'Current authorized speech input required';END IF;
 IF d.workspace_id IS NULL OR d.mode<>'tts' OR p_snapshot#>>'{target,preparationRevisionId}' IS DISTINCT FROM w.preparation_revision_id::text OR p_snapshot#>>'{target,workspaceId}' IS DISTINCT FROM w.id::text OR p_snapshot#>>'{target,shotId}' IS DISTINCT FROM p_shot OR p_snapshot#>>'{target,scriptRevisionId}' IS DISTINCT FROM w.script_revision_id::text OR p_snapshot#>>'{target,projectSha256}' IS DISTINCT FROM w.project_sha256 OR p_snapshot#>>'{context,text}' IS DISTINCT FROM d.narration_text THEN RAISE EXCEPTION 'Current preparation-bound speech input required' USING ERRCODE='40001';END IF;
 cfg:=p_snapshot->'execution';amount:=(p_snapshot->>'reservationCents')::integer;hash:=p_snapshot->>'inputFingerprint';
 IF p_snapshot->>'selectionVersion'<>'1' OR cfg#>>'{executor,provider}'<>'volcengine_tts' OR cfg#>>'{executor,adapter}'<>'volcengine_tts' OR cfg#>>'{executor,model}'<>'seed-tts-2.0' OR cfg->>'credential_ref' IS DISTINCT FROM n.selection->>'connectionVersionId' OR NOT EXISTS(SELECT 1 FROM public.external_connection_versions v JOIN public.external_connections cn ON cn.id=v.connection_id AND cn.created_by=local_identity.owner_id() AND cn.current_version_id=v.id JOIN local_identity.connection_bindings cb ON cb.version_id=v.id AND cb.owner_id=cn.created_by AND cb.store_mode='keychain' JOIN local_identity.connection_qualifications cq ON cq.version_id=v.id AND cq.owner_id=cn.created_by AND cq.qualified WHERE v.id::text=cfg->>'credential_ref' AND v.provider='volcengine_tts' AND v.adapter='volcengine_tts' AND v.revoked_at IS NULL AND EXISTS(SELECT 1 FROM local_identity.connection_probe_evidence pe WHERE pe.version_id=v.id AND pe.mode='live' AND pe.outcome='verified')) THEN RAISE EXCEPTION 'Verified owned speech connection required';END IF;
 SELECT task.* INTO t FROM public.tasks task JOIN local_identity.workspace_narration_requests r ON r.task_id=task.id WHERE r.workspace_id=w.id AND r.shot_id=p_shot AND r.input_fingerprint=hash ORDER BY task.created_at DESC LIMIT 1;
 IF FOUND AND (t.status IN ('ready','running','completed') OR t.status IN ('failed','blocked') AND NOT p_retry) THEN RETURN t;END IF;

 IF EXISTS(
  WITH prior AS(
   SELECT task.id,task.status,s.outcome,
    EXISTS(SELECT 1 FROM local_identity.native_output_publications h WHERE h.task_id=task.id) held,
    EXISTS(SELECT 1 FROM local_identity.workspace_narration_requests child WHERE child.workspace_id=w.id AND child.shot_id=p_shot AND child.request_snapshot->>'retryOfTaskId'=task.id::text) retried
   FROM local_identity.workspace_narration_requests r JOIN public.tasks task ON task.id=r.task_id
   LEFT JOIN local_identity.workspace_narration_submissions s ON s.task_id=task.id
   WHERE r.workspace_id=w.id AND r.shot_id=p_shot
  ), unresolved AS(
   SELECT * FROM prior WHERE status IN ('ready','running') OR held OR(outcome IN ('started','received') AND status<>'completed' AND NOT retried AND NOT local_identity.provider_request_not_sent(id))
  ), approved AS(
   SELECT u.id FROM unresolved u JOIN local_identity.workspace_call_confirmations c ON c.authorization_hash=local_identity.current_workspace_call_hash(w.id)
   WHERE u.status IN ('failed','blocked') AND (u.outcome='started' OR(u.outcome='received' AND NOT EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts f WHERE f.task_id=u.id))) AND NOT u.held AND NOT u.retried
    AND u.id::text=p_snapshot->>'retryOfTaskId' AND c.command='generateWorkspaceNarration'
    AND c.payload->>'retryOfTaskId'=u.id::text AND c.payload->>'clipId'=n.clip_id::text
  )
  SELECT 1 FROM unresolved u WHERE NOT EXISTS(SELECT 1 FROM approved x WHERE x.id=u.id)
  UNION ALL SELECT 1 WHERE p_snapshot ? 'retryOfTaskId' AND NOT EXISTS(SELECT 1 FROM approved)
 ) THEN RAISE EXCEPTION 'Previous speech submission pending or unknown' USING ERRCODE='55000';END IF;

 IF amount IS NULL OR amount<greatest(1,char_length(d.narration_text)) OR amount>100000 THEN RAISE EXCEPTION 'Invalid per-request narration reservation' USING ERRCODE='22023';END IF;
 frozen:=jsonb_build_object('selectionVersion',1,'production_selection',n.selection,'production_context',p_snapshot->'context','workspace_target',p_snapshot->'target','cost_basis',p_snapshot->'costBasis','capability','narration_generation','workspace_narration',jsonb_build_object('version','workspace-narration/v2','workspace_id',w.id,'preparation_revision_id',w.preparation_revision_id,'shot_id',p_shot,'mode','tts'),'configuration_hash',hash,'native_tts_retry_id',gen_random_uuid(),'credential_ref',cfg->>'credential_ref','executor',cfg->'executor','media',jsonb_build_object('adapter','volcengine_tts','narration',jsonb_build_object('text',d.narration_text,'voice',jsonb_build_object('name',d.voice,'language_code',d.language_code,'speaking_rate',d.speaking_rate))),'acoustic_alignment',jsonb_build_object('confirmed_text',caption_text,'text_fingerprint',encode(extensions.digest(convert_to(caption_text,'UTF8'),'sha256'),'hex')),'audio_track',jsonb_build_object('kind','narration','cue_id',p_shot,'preparation_revision_id',w.preparation_revision_id,'start_seconds',0,'duration_seconds',0.001),'budget',jsonb_build_object('limit_cents',amount,'max_attempts',1),'allowed_tools',jsonb_build_array('read','write'),'input_artifacts',jsonb_build_array(),'output',jsonb_build_object('required_artifact_types',jsonb_build_array('narration_audio'),'content_type','audio/mpeg','relative_path',format('%s/audio/narration-%s.mp3',(SELECT directory_relative_path FROM local_identity.episode_storage_location(e.id)),gen_random_uuid()),'review_stage','production_ready'));
 UPDATE local_identity.input_episodes SET narration_enabled=true WHERE episode_id=e.id;
 INSERT INTO public.tasks(episode_id,task_type,status,input_snapshot,budget_limit_cents,max_attempts,provider,model,prompt_version) VALUES(e.id,'generate_narration','ready',frozen,amount,1,'volcengine_tts','seed-tts-2.0','production-request-v1') RETURNING * INTO t;
 INSERT INTO local_identity.workspace_narration_requests(task_id,workspace_id,episode_id,clip_id,shot_id,input_fingerprint,authorization_hash,request_snapshot) VALUES(t.id,w.id,e.id,n.clip_id,p_shot,hash,a.authorization_hash,p_snapshot);
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_audio(p_preparation uuid, p_retry boolean DEFAULT false, p_source jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prep local_identity.workspace_audio_preparations; workspace local_identity.production_workspaces; previous public.tasks; created public.tasks; policy jsonb; config jsonb; executor jsonb; auth local_identity.script_productions; frozen jsonb; nonce text:=gen_random_uuid()::text; budget integer:=0; attempts integer:=2; BEGIN
 SELECT * INTO prep FROM local_identity.workspace_audio_preparations WHERE id=p_preparation FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(prep.episode_id) THEN RAISE EXCEPTION 'Owned preparation required' USING ERRCODE='42501'; END IF;
 workspace:=local_identity.lock_current_production_workspace(prep.workspace_id);
 PERFORM 1 FROM public.episodes e WHERE e.id=prep.episode_id AND e.main_script_revision_id=workspace.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed';
 IF NOT FOUND OR prep.material_revision_id IS NOT NULL THEN RAISE EXCEPTION 'Current generated preparation required' USING ERRCODE='22023'; END IF;
 IF prep.task_id IS NOT NULL THEN
  SELECT * INTO previous FROM public.tasks WHERE id=prep.task_id;
  IF previous.status IN ('ready','running','completed') OR NOT p_retry THEN RETURN previous.id; END IF;
  p_source:=previous.input_snapshot->'workspace_source';
 END IF;
 IF previous.id IS NOT NULL AND NOT local_identity.workspace_task_preparation_current(previous.id,workspace.id) THEN RAISE EXCEPTION 'Original audio preparation no longer current' USING ERRCODE='40001';END IF;
 IF previous.id IS NOT NULL THEN
  frozen:=previous.input_snapshot;budget:=previous.budget_limit_cents;attempts:=previous.max_attempts;executor:=frozen->'executor';
  SELECT * INTO auth FROM local_identity.workspace_production_authorizations WHERE episode_id=prep.episode_id AND script_revision_id=workspace.script_revision_id AND enabled AND authorized_at IS NOT NULL AND authorization_hash=local_identity.current_workspace_call_hash(workspace.id);
  IF prep.kind<>'source' AND auth.authorization_hash IS NULL THEN RAISE EXCEPTION 'Current production authorization required' USING ERRCODE='42501';END IF;
 ELSIF prep.kind='source' THEN
  IF p_source IS NULL OR p_source->>'sha256' IS DISTINCT FROM prep.source_sha256 OR coalesce(p_source->>'startSeconds','') !~ '^[0-9]+([.][0-9]+)?$' OR (p_source->>'startSeconds')::numeric>7200 OR (p_source->>'durationSeconds')::numeric IS DISTINCT FROM prep.duration_seconds OR (left(coalesce(p_source->>'relativePath',''),length((SELECT directory_relative_path FROM local_identity.episode_storage_location(prep.episode_id)))+1) IS DISTINCT FROM (SELECT directory_relative_path FROM local_identity.episode_storage_location(prep.episode_id))||'/' AND left(coalesce(p_source->>'relativePath',''),length('episodes/'||prep.episode_id::text)+1) IS DISTINCT FROM 'episodes/'||prep.episode_id::text||'/') THEN RAISE EXCEPTION 'Current native source required' USING ERRCODE='22023'; END IF;
  frozen:=jsonb_build_object('capability','embedded_audio_extraction','workspace_source',p_source,'media',jsonb_build_object('adapter','ffmpeg_extract_audio','embedded_audio',jsonb_build_object('source_relative_path',p_source->>'relativePath','duration_seconds',prep.duration_seconds,'start_seconds',(p_source->>'startSeconds')::numeric)),'input_artifacts',jsonb_build_array(jsonb_build_object('artifactType','source_video','relativePath',p_source->>'relativePath','sha256',p_source->>'sha256','fileSize',(p_source->>'fileSize')::bigint)),'allowed_tools',jsonb_build_array('read','write'));
 ELSE
  config:=prep.request_snapshot->'execution';executor:=config->'executor';
  IF prep.request_snapshot->>'selectionVersion' IS DISTINCT FROM '1' OR prep.request_snapshot#>>'{selection,capability}' IS DISTINCT FROM 'music_sound' OR config->>'credential_ref' IS DISTINCT FROM prep.request_snapshot#>>'{selection,connectionVersionId}' OR NOT EXISTS(SELECT 1 FROM public.external_connection_versions cv JOIN public.external_connections cn ON cn.id=cv.connection_id AND cn.created_by=local_identity.owner_id() AND cn.current_version_id=cv.id JOIN local_identity.connection_bindings cb ON cb.version_id=cv.id AND cb.owner_id=cn.created_by AND cb.store_mode='keychain' JOIN local_identity.connection_qualifications cq ON cq.version_id=cv.id AND cq.owner_id=cn.created_by AND cq.qualified WHERE cv.id::text=config->>'credential_ref' AND cv.provider='freesound' AND cv.adapter='freesound_preview' AND cv.revoked_at IS NULL AND EXISTS(SELECT 1 FROM local_identity.connection_probe_evidence pe WHERE pe.version_id=cv.id AND pe.owner_id=cn.created_by AND pe.mode='live' AND pe.outcome='verified')) THEN RAISE EXCEPTION 'Validated owned Freesound selection required' USING ERRCODE='22023';END IF;
  IF config->>'execution_path' IS DISTINCT FROM 'external' OR executor->>'provider' IS DISTINCT FROM 'freesound' OR executor->>'adapter' IS DISTINCT FROM 'freesound_preview' OR executor->>'model' IS DISTINCT FROM 'freesound-preview-v1' THEN RAISE EXCEPTION 'Selected Freesound execution required' USING ERRCODE='22023'; END IF;
  SELECT * INTO auth FROM local_identity.workspace_production_authorizations WHERE episode_id=prep.episode_id AND script_revision_id=workspace.script_revision_id AND enabled AND authorized_at IS NOT NULL AND authorization_hash=local_identity.current_workspace_call_hash(workspace.id);
  IF NOT FOUND THEN RAISE EXCEPTION 'Current production authorization required' USING ERRCODE='42501'; END IF;
  IF coalesce(config->>'budget_cents','') !~ '^[0-9]+$' OR coalesce(config->>'max_attempts','') !~ '^[1-9][0-9]*$' OR jsonb_typeof(config->'allowed_tools') IS DISTINCT FROM 'array' OR jsonb_array_length(config->'allowed_tools')=0 THEN RAISE EXCEPTION 'Frozen soundtrack budget and tools required' USING ERRCODE='22023'; END IF;
  budget:=(config->>'budget_cents')::integer;attempts:=(config->>'max_attempts')::integer;
  frozen:=jsonb_build_object('production_selection',prep.request_snapshot->'selection','production_context',prep.request_snapshot->'context','workspace_target',prep.request_snapshot->'target','cost_basis',prep.request_snapshot->'costBasis','capability','soundtrack_generation','credential_ref',config->>'credential_ref','executor',executor,'media',jsonb_build_object('adapter','freesound_preview','soundtrack',jsonb_build_object('query',prep.query,'target_duration_seconds',prep.duration_seconds,'cue',jsonb_build_object('id',prep.id,'kind',prep.kind,'description',prep.description,'search_query',prep.query,'start_seconds',prep.offset_seconds,'duration_seconds',prep.duration_seconds))),'allowed_tools',config->'allowed_tools','input_artifacts','[]'::jsonb);
 END IF;
 IF previous.id IS NULL THEN
  IF workspace.episode_id IS DISTINCT FROM prep.episode_id OR prep.shot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(workspace.bindings) b WHERE b->>'shotId'=prep.shot_id) THEN RAISE EXCEPTION 'Current audio target required' USING ERRCODE='40001';END IF;
  IF prep.kind<>'source' AND (prep.request_snapshot#>>'{target,workspaceId}' IS DISTINCT FROM workspace.id::text OR prep.request_snapshot#>>'{target,preparationRevisionId}' IS DISTINCT FROM workspace.preparation_revision_id::text OR prep.request_snapshot#>>'{target,scriptRevisionId}' IS DISTINCT FROM workspace.script_revision_id::text) THEN RAISE EXCEPTION 'Current preparation-bound sound input required' USING ERRCODE='40001';END IF;
  frozen:=frozen||jsonb_build_object('production_preparation',jsonb_strip_nulls(jsonb_build_object('version','production-preparation-ref/v1','workspace_id',workspace.id,'preparation_revision_id',workspace.preparation_revision_id,'script_revision_id',workspace.script_revision_id,'shot_id',prep.shot_id)));
 END IF;
 IF prep.kind='sfx' AND prep.request_snapshot ? 'candidateIndex' THEN
    IF jsonb_typeof(prep.request_snapshot->'candidateIndex') IS DISTINCT FROM 'number' OR (prep.request_snapshot->>'candidateIndex')::integer NOT BETWEEN 0 AND 2 THEN RAISE EXCEPTION 'Invalid sound candidate index' USING ERRCODE='22023'; END IF;
    frozen:=jsonb_set(frozen,'{media,soundtrack,candidate_index}',prep.request_snapshot->'candidateIndex');
   END IF;
   frozen:=frozen||jsonb_build_object('configuration_hash',prep.input_fingerprint||'-'||nonce,'workspace_audio',jsonb_build_object('preparation_id',prep.id,'input_fingerprint',prep.input_fingerprint),'budget',jsonb_build_object('limit_cents',budget,'max_attempts',attempts),'audio_track',CASE WHEN previous.id IS NOT NULL THEN frozen->'audio_track' ELSE jsonb_build_object('kind',prep.kind,'cue_id',coalesce(prep.shot_id,prep.id::text),'preparation_revision_id',workspace.preparation_revision_id,'start_seconds',0,'duration_seconds',0.001) END,'output',jsonb_build_object('required_artifact_types',jsonb_build_array(CASE WHEN prep.kind='source' THEN 'shot_source_audio' ELSE 'soundtrack_audio' END),'content_type','audio/mpeg','relative_path',format('%s/workspace-audio/%s/%s.mp3',(SELECT directory_relative_path FROM local_identity.episode_storage_location(prep.episode_id)),prep.id,nonce),'review_stage','production_ready'));
 UPDATE local_identity.input_episodes SET media_enabled=true WHERE episode_id=prep.episode_id;
 INSERT INTO public.tasks(episode_id,task_type,status,input_snapshot,budget_limit_cents,max_attempts,provider,model,prompt_version) VALUES(prep.episode_id,CASE WHEN prep.kind='source' THEN 'extract_embedded_audio' ELSE 'generate_soundtrack' END,'ready',frozen,budget,attempts,CASE WHEN prep.kind='source' THEN 'ffmpeg' ELSE 'freesound' END,CASE WHEN prep.kind='source' THEN 'ffmpeg' ELSE executor->>'model' END,CASE WHEN prep.kind='source' THEN 'workspace-source-audio-v1' ELSE executor->>'prompt_version' END) RETURNING * INTO created;
 UPDATE local_identity.workspace_audio_preparations SET task_id=created.id WHERE id=prep.id;
 INSERT INTO local_identity.workspace_audio_requests(task_id,preparation_id,workspace_id,episode_id,input_fingerprint,authorization_hash) VALUES(created.id,prep.id,workspace.id,prep.episode_id,prep.input_fingerprint,auth.authorization_hash);
 RETURN created.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_delivery(p_id uuid, p_workspace uuid, p_export uuid, p_snapshot jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces;x local_identity.workspace_exports;t public.tasks;
BEGIN
 SELECT * INTO w FROM local_identity.production_workspaces WHERE id=p_workspace FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(w.episode_id) OR NOT local_identity.workspace_delivery_current(w.id,p_export) THEN RAISE EXCEPTION 'Current confirmed workspace export required' USING ERRCODE='22023'; END IF;
 SELECT * INTO x FROM local_identity.workspace_exports WHERE id=p_export;
 IF p_snapshot->>'capability'<>'workspace_delivery' OR p_snapshot#>>'{workspace_delivery,identity,exportId}'<>x.id::text OR p_snapshot#>>'{workspace_delivery,identity,workspaceId}'<>w.id::text OR p_snapshot#>>'{workspace_delivery,identity,contentSha256}'<>x.content_sha256 OR p_snapshot#>'{workspace_delivery,identity,video}' IS DISTINCT FROM x.artifact||'{"artifactType":"final_render"}'::jsonb OR p_snapshot#>'{workspace_delivery,identity,project}' IS DISTINCT FROM x.project||'{"artifactType":"editable_project"}'::jsonb OR (p_snapshot#>>'{workspace_delivery,identity,projectContentVersion}')::bigint<>x.project_content_version THEN RAISE EXCEPTION 'Delivery does not match exact export' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM local_identity.workspace_deliveries d JOIN public.tasks busy ON busy.id=d.task_id WHERE d.workspace_id=w.id AND busy.status IN ('ready','running')) THEN RAISE EXCEPTION 'Delivery already queued' USING ERRCODE='22023'; END IF;
 INSERT INTO public.tasks(id,episode_id,task_type,status,input_snapshot,provider,model,prompt_version,max_attempts) VALUES(p_id,w.episode_id,'prepare_publish_package','ready',p_snapshot,'ffmpeg','workspace-delivery/v2','workspace-delivery/v2',1) RETURNING * INTO t;
 INSERT INTO local_identity.workspace_deliveries(id,workspace_id,episode_id,export_id,task_id) VALUES(p_id,w.id,w.episode_id,x.id,t.id);
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) SELECT account_id,id,'workspace_delivery_queued',jsonb_build_object('task_id',t.id,'export_id',x.id,'sha256',x.artifact->>'sha256'),local_identity.owner_id() FROM public.episodes WHERE id=w.episode_id;
 RETURN t.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_images(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v local_identity.workspace_visual_candidates;w local_identity.production_workspaces;cfg jsonb;auth local_identity.script_productions;tid uuid;frozen jsonb;aid uuid;BEGIN
 SELECT * INTO v FROM local_identity.workspace_visual_candidates WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(v.episode_id) THEN RAISE EXCEPTION 'Owned image request required' USING ERRCODE='42501';END IF;
 w:=local_identity.lock_current_production_workspace(v.workspace_id);
 IF v.task_id IS NOT NULL THEN RETURN v.task_id;END IF;
 SELECT b.policy->'static_visual' INTO cfg FROM public.episodes e JOIN public.account_blueprint_versions b ON b.id=e.blueprint_version_id WHERE e.id=v.episode_id AND e.main_script_revision_id=w.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed';
 SELECT * INTO auth FROM local_identity.workspace_production_authorizations WHERE episode_id=v.episode_id AND script_revision_id=w.script_revision_id AND enabled AND authorized_at IS NOT NULL AND authorization_hash=local_identity.current_workspace_call_hash(w.id);
 IF v.request_snapshot->>'selectionVersion'='1' THEN
 cfg:=v.request_snapshot->'execution';
 IF cfg->>'credential_ref' IS DISTINCT FROM v.request_snapshot#>>'{selection,connectionVersionId}' OR NOT EXISTS(SELECT 1 FROM public.external_connection_versions cv JOIN public.external_connections cn ON cn.id=cv.connection_id AND cn.created_by=local_identity.owner_id() AND cn.current_version_id=cv.id JOIN local_identity.connection_bindings cb ON cb.version_id=cv.id AND cb.owner_id=cn.created_by AND cb.store_mode='keychain' JOIN local_identity.connection_qualifications cq ON cq.version_id=cv.id AND cq.owner_id=cn.created_by AND cq.qualified WHERE cv.id::text=cfg->>'credential_ref' AND cv.provider='openai' AND cv.adapter='openai_images' AND cv.revoked_at IS NULL AND EXISTS(SELECT 1 FROM local_identity.connection_probe_evidence p WHERE p.version_id=cv.id AND p.owner_id=cn.created_by AND p.mode='live' AND p.outcome='verified')) THEN RAISE EXCEPTION 'Validated owned image connection required';END IF;
 END IF;
 IF cfg IS NULL OR cfg IS DISTINCT FROM v.request_snapshot->'execution' OR cfg->>'execution_path'<>'external' OR cfg#>>'{executor,provider}'<>'openai' OR cfg#>>'{executor,adapter}'<>'openai_images' OR coalesce(cfg#>>'{executor,model}','') NOT IN ('gpt-image-2','gpt-image-2.5-sunburst','gpt-image-2.5-flare','gpt-image-2.5-sunburst-2026-09-08','gpt-image-2.5-flare-2026-09-08','gpt-image-2.6-sunburst','gpt-image-2.6-flare') OR auth.authorization_hash IS DISTINCT FROM v.request_snapshot->>'authorizationHash' OR auth.authorization_hash IS NULL THEN RAISE EXCEPTION 'Current authorized image configuration required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.episodes e JOIN local_identity.production_preparation_revisions p ON p.id=w.preparation_revision_id AND p.episode_id=e.id AND p.script_revision_id=w.script_revision_id WHERE e.id=v.episode_id AND e.main_script_revision_id=w.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed' AND local_identity.preparation_source_current(p.id)) THEN RAISE EXCEPTION 'Current workspace required';END IF;
 IF w.episode_id IS DISTINCT FROM v.episode_id OR v.request_snapshot#>>'{target,workspaceId}' IS DISTINCT FROM w.id::text OR v.request_snapshot#>>'{target,preparationRevisionId}' IS DISTINCT FROM w.preparation_revision_id::text OR v.request_snapshot#>>'{target,scriptRevisionId}' IS DISTINCT FROM w.script_revision_id::text OR v.request_snapshot#>>'{target,shotId}' IS DISTINCT FROM v.shot_id THEN RAISE EXCEPTION 'Current preparation-bound image target required' USING ERRCODE='40001';END IF;
 SELECT account_id INTO aid FROM public.episodes WHERE id=v.episode_id;

 IF EXISTS(
  WITH prior AS (
   SELECT t.id,t.status,r.request_state,r.provider_task_id,s.outcome,
    EXISTS(SELECT 1 FROM local_identity.native_output_publications h WHERE h.task_id=t.id) held,
    EXISTS(SELECT 1 FROM local_identity.workspace_visual_candidates retry
           WHERE retry.workspace_id=x.workspace_id AND retry.target_item_id=x.target_item_id
             AND retry.task_id IS NOT NULL AND retry.request_snapshot->>'retryOfTaskId'=t.id::text) retried
   FROM local_identity.workspace_visual_candidates x JOIN public.tasks t ON t.id=x.task_id
   LEFT JOIN public.paid_generation_reservations r ON r.task_id=t.id
   LEFT JOIN local_identity.workspace_visual_submissions s ON s.task_id=t.id
   WHERE x.workspace_id=v.workspace_id AND x.target_item_id=v.target_item_id AND x.request_snapshot->>'kind'='image'
  ), unresolved AS (
   SELECT *,status IN ('failed','blocked') AND provider_task_id IS NULL
          AND (coalesce(outcome,'started')='started' OR(outcome='received' AND NOT EXISTS(SELECT 1 FROM local_identity.provider_dispatch_facts f WHERE f.task_id=prior.id))) AND NOT held AS may_retry
   FROM prior WHERE status IN ('ready','running') OR held
    OR (request_state='submitting' AND status<>'completed' AND coalesce(outcome,'started')<>'rejected' AND NOT retried AND NOT local_identity.provider_request_not_sent(id))
  ), confirmed_retry AS (
   SELECT u.id FROM unresolved u JOIN local_identity.workspace_call_confirmations c
     ON c.authorization_hash=local_identity.current_workspace_call_hash(v.workspace_id)
   WHERE u.may_retry AND u.id::text=v.request_snapshot->>'retryOfTaskId'
     AND c.command='requestWorkspaceImageCandidates'
     AND c.payload->>'retryOfTaskId'=u.id::text AND c.payload->>'targetItemId'=v.target_item_id
  )
  SELECT 1 FROM unresolved u WHERE NOT EXISTS(SELECT 1 FROM confirmed_retry r WHERE r.id=u.id)
  UNION ALL
  SELECT 1 WHERE v.request_snapshot ? 'retryOfTaskId' AND NOT EXISTS(SELECT 1 FROM confirmed_retry)
 ) THEN RAISE EXCEPTION 'Previous image submission pending or unknown' USING ERRCODE='55000';END IF;

 frozen:=jsonb_build_object('capability','static_visual_generation','production_preparation',jsonb_build_object('version','production-preparation-ref/v1','workspace_id',w.id,'preparation_revision_id',w.preparation_revision_id,'script_revision_id',w.script_revision_id,'shot_id',v.shot_id),'production_selection',v.request_snapshot->'selection','production_context',v.request_snapshot->'context','workspace_target',v.request_snapshot->'target','cost_basis',v.request_snapshot->'costBasis','configuration_hash',v.input_fingerprint,'workspace_image_request_id',v.id,'credential_ref',cfg->>'credential_ref','executor',cfg->'executor','allowed_tools',jsonb_build_array('read','write'),'input_artifacts',coalesce(v.request_snapshot->'references','[]'::jsonb),'budget',jsonb_build_object('limit_cents',(v.request_snapshot->>'reservationCents')::integer,'max_attempts',1),'media',jsonb_build_object('adapter','openai_images','static_visual',jsonb_build_object('prompt',coalesce(v.request_snapshot->>'actualPrompt',v.request_snapshot->>'prompt'),'settings',v.request_snapshot->'imageSettings','references',coalesce(v.request_snapshot->'references','[]'::jsonb))),'output',jsonb_build_object('required_artifact_types',jsonb_build_array('static_visual'),'content_type','image/png','relative_path',format('episodes/%s/workspace-images/%s/image.png',v.episode_id,v.id),'review_stage','production_ready'));
 UPDATE local_identity.input_episodes SET media_enabled=true WHERE episode_id=v.episode_id;
 INSERT INTO public.tasks(episode_id,task_type,status,input_snapshot,budget_limit_cents,max_attempts,provider,model,prompt_version) VALUES(v.episode_id,'generate_static_visual','ready',frozen,(v.request_snapshot->>'reservationCents')::integer,1,'openai',cfg#>>'{executor,model}','workspace-image-v1') RETURNING id INTO tid;
 UPDATE local_identity.workspace_visual_candidates SET task_id=tid WHERE id=v.id;RETURN tid;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_pexels(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r local_identity.workspace_pexels_requests;w local_identity.production_workspaces;cfg jsonb;snap jsonb;tid uuid;op text;BEGIN
 SELECT * INTO r FROM local_identity.workspace_pexels_requests WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(r.episode_id) THEN RAISE EXCEPTION 'Owned Pexels request required' USING ERRCODE='42501';END IF;
 IF r.task_id IS NOT NULL THEN RETURN r.task_id;END IF;
 w:=local_identity.lock_current_production_workspace(r.workspace_id);
 IF w.episode_id IS DISTINCT FROM r.episode_id OR NOT local_identity.preparation_source_current(w.preparation_revision_id) THEN RAISE EXCEPTION 'Current production preparation required';END IF;
 snap:=r.request_snapshot;cfg:=snap->'execution';op:=snap->>'operation';
 IF snap#>>'{target,workspaceId}' IS DISTINCT FROM w.id::text OR snap#>>'{target,preparationRevisionId}' IS DISTINCT FROM w.preparation_revision_id::text
  OR snap#>>'{target,scriptRevisionId}' IS DISTINCT FROM w.script_revision_id::text OR snap#>>'{target,targetItemId}' IS DISTINCT FROM r.target_item_id
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.bindings) b JOIN local_identity.production_shot_versions s ON s.preparation_revision_id=w.preparation_revision_id AND s.episode_id=w.episode_id AND s.shot_id=b->>'shotId' WHERE b->>'itemId'=r.target_item_id AND s.shot_id=snap#>>'{target,shotId}') THEN RAISE EXCEPTION 'Frozen Pexels preparation target mismatch';END IF;
 IF op NOT IN ('search','preview') OR snap#>>'{selection,capability}'<>'video' OR cfg#>>'{executor,provider}'<>'pexels' OR cfg#>>'{executor,adapter}'<>'pexels_video' OR snap#>>'{selection,model}' IS NOT NULL OR cfg->>'credential_ref' IS DISTINCT FROM snap#>>'{selection,connectionVersionId}' OR NOT EXISTS(SELECT 1 FROM public.episodes e WHERE e.id=r.episode_id AND e.main_script_revision_id=w.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed' AND w.revision=(snap->>'expectedRevision')::bigint) THEN RAISE EXCEPTION 'Current Pexels selection and workspace required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.external_connection_versions cv JOIN public.external_connections cn ON cn.id=cv.connection_id AND cn.created_by=local_identity.owner_id() JOIN local_identity.connection_bindings cb ON cb.version_id=cv.id AND cb.owner_id=cn.created_by AND cb.store_mode='keychain' JOIN local_identity.connection_qualifications cq ON cq.version_id=cv.id AND cq.owner_id=cn.created_by AND cq.qualified WHERE cv.id::text=cfg->>'credential_ref' AND cv.provider='pexels' AND cv.adapter='pexels_video' AND cv.revoked_at IS NULL AND (op='preview' OR cn.current_version_id=cv.id) AND EXISTS(SELECT 1 FROM local_identity.connection_probe_evidence p WHERE p.version_id=cv.id AND p.owner_id=cn.created_by AND p.mode='live' AND p.outcome='verified')) THEN RAISE EXCEPTION 'Validated owned Pexels connection required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(r.workspace_id::text||r.target_item_id||':pexels:'||op,0));
 IF EXISTS(SELECT 1 FROM local_identity.workspace_pexels_requests x JOIN public.tasks t ON t.id=x.task_id WHERE x.workspace_id=r.workspace_id AND x.target_item_id=r.target_item_id AND x.request_snapshot->>'operation'=op AND t.status IN ('ready','running')) THEN RAISE EXCEPTION 'Pexels request already running' USING ERRCODE='55000';END IF;
 UPDATE local_identity.input_episodes SET enabled=true,media_enabled=true WHERE episode_id=r.episode_id;
 INSERT INTO public.tasks(episode_id,task_type,status,budget_limit_cents,max_attempts,provider,model,prompt_version,input_snapshot) VALUES(r.episode_id,CASE op WHEN 'search' THEN 'search_shot_video' ELSE 'preview_shot_video' END,'ready',0,1,'pexels','pexels-video-v1','workspace-pexels-v1',jsonb_build_object(
 'capability',CASE op WHEN 'search' THEN 'shot_video_search' ELSE 'shot_video_preview' END,'production_preparation',jsonb_build_object('version','production-preparation-ref/v1','workspace_id',w.id,'preparation_revision_id',w.preparation_revision_id,'script_revision_id',w.script_revision_id,'shot_id',snap#>>'{target,shotId}'),'workspace_pexels_request_id',r.id,'configuration_hash',snap->>'fingerprint','credential_ref',cfg->>'credential_ref','executor',cfg->'executor','production_selection',snap->'selection','production_context',snap->'context','workspace_target',snap->'target','cost_basis',jsonb_build_object('kind','free-search','reservedCents',0),'allowed_tools',jsonb_build_array('read','write'),'input_artifacts',snap->'inputs','budget',jsonb_build_object('limit_cents',0,'max_attempts',1),
 'media',jsonb_build_object('adapter','pexels_video','video',jsonb_build_object('query',snap->>'query','target_duration_seconds',snap->'targetDurationSeconds','request',jsonb_build_object('operation',op,'parameters',snap->'parameters','source',snap->'source'))),
 'output',jsonb_build_object('required_artifact_types',jsonb_build_array(CASE op WHEN 'search' THEN 'pexels_search_results' ELSE 'pexels_video_preview' END),'content_type',CASE op WHEN 'search' THEN 'application/json' ELSE 'video/mp4' END,'relative_path',format('episodes/%s/pexels/%s',r.episode_id,CASE op WHEN 'search' THEN 'results.json' ELSE 'preview.mp4' END),'review_stage','production_ready'))) RETURNING id INTO tid;
 UPDATE local_identity.workspace_pexels_requests SET task_id=tid WHERE id=r.id;RETURN tid;
END $function$

