CREATE OR REPLACE FUNCTION local_identity.queue_workspace_visual(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous uuid; tid uuid;
BEGIN
 SELECT task_id INTO previous FROM local_identity.workspace_visual_candidates WHERE id=p_id FOR UPDATE;
 tid:=local_identity.queue_workspace_visual_before_shot_protocol(p_id);
 IF previous IS NULL THEN
 UPDATE public.tasks SET input_snapshot=local_identity.shot_video_snapshot(input_snapshot)
 WHERE id=tid AND task_type IN ('generate_shot_video','search_shot_video','preview_shot_video') AND status='ready';
 END IF;
 RETURN tid;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_visual_before_selection(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tid uuid;v local_identity.workspace_visual_candidates;BEGIN
 tid:=local_identity.queue_workspace_visual_before_settings(p_id);
 SELECT * INTO v FROM local_identity.workspace_visual_candidates WHERE id=p_id;
 IF v.request_snapshot ? 'videoSettings' OR v.request_snapshot ? 'firstFrameComposition' THEN
 UPDATE public.tasks SET input_snapshot=jsonb_set(input_snapshot,'{media,wan_video}',input_snapshot#>'{media,wan_video}'||jsonb_build_object('settings',v.request_snapshot->'videoSettings','composition',v.request_snapshot->'firstFrameComposition')) WHERE id=tid AND status='ready';
 END IF;
 RETURN tid;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_visual_before_settings(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v local_identity.workspace_visual_candidates; w local_identity.production_workspaces; tid uuid; BEGIN
 SELECT * INTO v FROM local_identity.workspace_visual_candidates WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(v.episode_id) THEN RAISE EXCEPTION 'Owned visual request required' USING ERRCODE='42501'; END IF;
 w:=local_identity.lock_current_production_workspace(v.workspace_id);
 PERFORM pg_advisory_xact_lock(hashtextextended(v.workspace_id::text||v.target_item_id,0));
 IF v.task_id IS NOT NULL THEN RETURN v.task_id; END IF;
 IF EXISTS(SELECT 1 FROM local_identity.workspace_visual_candidates other JOIN public.tasks t ON t.id=other.task_id LEFT JOIN local_identity.workspace_visual_submissions s ON s.task_id=t.id WHERE other.workspace_id=v.workspace_id AND other.target_item_id=v.target_item_id AND t.task_type IN ('generate_shot_video','search_shot_video','preview_shot_video','generate_a_roll', 'generate_b_roll') AND (t.status='running' OR (t.status='ready' AND (t.invalidated_at IS NULL OR EXISTS(SELECT 1 FROM public.paid_generation_reservations prior_reservation WHERE prior_reservation.task_id=t.id) OR EXISTS(SELECT 1 FROM local_identity.native_output_publications prior_publication WHERE prior_publication.task_id=t.id))) OR (s.outcome IN ('started','received') AND t.status<>'completed'))) THEN RAISE EXCEPTION 'Previous visual submission pending or unknown; reconcile or resume its saved Provider ID' USING ERRCODE='55000'; END IF;
 UPDATE local_identity.input_episodes SET media_enabled=true WHERE episode_id=v.episode_id;
 IF v.request_snapshot#>>'{execution,executor,provider}'='bailian' THEN
 tid:=local_identity.request_workspace_wan_visual(v.episode_id,w.preparation_revision_id,v.shot_id,(v.request_snapshot->>'firstFrameId')::uuid,v.request_snapshot->>'prompt',(v.request_snapshot->>'providerDurationSeconds')::integer,v.id);
 ELSE
 tid:=local_identity.request_workspace_official_visual(v.episode_id,w.preparation_revision_id,v.shot_id,(v.request_snapshot->>'firstFrameId')::uuid,v.request_snapshot->>'prompt',(v.request_snapshot->>'providerDurationSeconds')::integer,v.id,(v.request_snapshot->>'reservationCents')::integer);
 END IF;
 UPDATE local_identity.workspace_visual_candidates SET task_id=tid WHERE id=v.id AND task_id IS NULL;RETURN tid;
END $function$

CREATE OR REPLACE FUNCTION local_identity.queue_workspace_visual_before_shot_protocol(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v local_identity.workspace_visual_candidates;tid uuid;aid uuid;cfg jsonb;BEGIN
 SELECT * INTO v FROM local_identity.workspace_visual_candidates WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(v.episode_id) THEN RAISE EXCEPTION 'Owned video request required' USING ERRCODE='42501';END IF;
 IF v.task_id IS NOT NULL THEN RETURN v.task_id;END IF;
 IF v.request_snapshot->>'authorizationHash' IS DISTINCT FROM local_identity.current_workspace_call_hash(v.workspace_id) OR local_identity.current_workspace_call_hash(v.workspace_id) IS NULL THEN RAISE EXCEPTION 'Current call confirmation required' USING ERRCODE='42501';END IF;
 IF v.request_snapshot->>'selectionVersion'='1' THEN
 cfg:=v.request_snapshot->'execution';
 IF v.request_snapshot#>>'{selection,capability}'<>'video' OR cfg->>'credential_ref' IS DISTINCT FROM v.request_snapshot#>>'{selection,connectionVersionId}' OR NOT EXISTS(SELECT 1 FROM public.external_connection_versions cv JOIN public.external_connections cn ON cn.id=cv.connection_id AND cn.created_by=local_identity.owner_id() AND cn.current_version_id=cv.id JOIN local_identity.connection_bindings cb ON cb.version_id=cv.id AND cb.owner_id=cn.created_by AND cb.store_mode='keychain' JOIN local_identity.connection_qualifications cq ON cq.version_id=cv.id AND cq.owner_id=cn.created_by AND cq.qualified WHERE cv.id::text=cfg->>'credential_ref' AND cv.provider=cfg#>>'{executor,provider}' AND cv.adapter=cfg#>>'{executor,adapter}' AND cv.revoked_at IS NULL AND EXISTS(SELECT 1 FROM local_identity.connection_probe_evidence p WHERE p.version_id=cv.id AND p.owner_id=cn.created_by AND p.mode='live' AND p.outcome='verified')) THEN RAISE EXCEPTION 'Validated owned video connection required';END IF;
 SELECT account_id INTO aid FROM public.episodes WHERE id=v.episode_id;
 END IF;
 tid:=local_identity.queue_workspace_visual_before_selection(p_id);
 IF v.request_snapshot->>'selectionVersion'='1' THEN
 UPDATE public.tasks SET input_snapshot=input_snapshot||jsonb_build_object('production_selection',v.request_snapshot->'selection','production_context',v.request_snapshot->'context','workspace_target',v.request_snapshot->'target','cost_basis',v.request_snapshot->'costBasis','configuration_hash',v.input_fingerprint),budget_limit_cents=(v.request_snapshot->>'reservationCents')::integer WHERE id=tid;
 UPDATE public.tasks SET input_snapshot=jsonb_set(jsonb_set(input_snapshot,'{media,wan_video,prompt}',v.request_snapshot->'actualPrompt'),'{budget,limit_cents}',v.request_snapshot->'reservationCents') WHERE id=tid;
 END IF;
 RETURN tid;
END $function$

CREATE OR REPLACE FUNCTION local_identity.reconfirm_episode_script(p_episode uuid, p_expected uuid, p_source text, p_storage text, p_sha text, p_size bigint, p_reason text)
 RETURNS public.production_material_revisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes; m public.production_material_revisions;
BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned production required' USING ERRCODE='42501'; END IF;
 SELECT * INTO e FROM public.episodes WHERE id=p_episode;
 IF e.archived_at IS NOT NULL OR e.stage='production_completed' OR e.main_script_revision_id IS DISTINCT FROM p_expected OR p_expected IS NULL THEN RAISE EXCEPTION '当前脚本版本或生产单状态已变化，请刷新。' USING ERRCODE='22023'; END IF;
 IF btrim(coalesce(p_reason,''))='' OR length(p_reason)>4000 THEN RAISE EXCEPTION '请填写修订原因。' USING ERRCODE='22023'; END IF;
 PERFORM id FROM public.tasks WHERE episode_id=p_episode FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.tasks WHERE episode_id=p_episode AND status='running') THEN RAISE EXCEPTION '制作任务正在运行，请完成或停止后修订脚本。' USING ERRCODE='22023'; END IF;
 IF p_sha !~ '^[0-9a-f]{64}$' OR p_size<=0 OR p_size>2097152 OR p_sha=(SELECT sha256 FROM public.production_material_revisions WHERE id=p_expected) THEN RAISE EXCEPTION '脚本内容未改变或无效。' USING ERRCODE='22023'; END IF;
 UPDATE local_identity.input_episodes SET enabled=false,storyboard_enabled=false,visual_media_enabled=false,narration_enabled=false,media_enabled=false,alignment_enabled=false,preview_enabled=false,studio_enabled=false,delivery_enabled=false WHERE episode_id=p_episode;
 UPDATE local_identity.script_productions SET enabled=false,authorized_at=NULL,last_status='脚本已修订，请重新确认制作计划',updated_at=clock_timestamp() WHERE episode_id=p_episode;
 PERFORM public.invalidate_dependent_production_work('material_revision',p_expected,p_reason);
 UPDATE public.tasks SET invalidated_at=now(),invalidated_reason=p_reason WHERE episode_id=p_episode AND invalidated_at IS NULL;
 UPDATE public.review_packages SET invalidated_at=now(),invalidated_reason=p_reason WHERE episode_id=p_episode AND invalidated_at IS NULL;
 UPDATE public.episodes SET stage='waiting_input',main_script_revision_id=NULL,updated_at=now() WHERE id=p_episode;
 SELECT * INTO m FROM public.import_production_material(p_episode,'script','file',p_source,p_storage,'text/markdown',p_sha,p_size,true,'main_script');
 -- Import triggers may invalidate prior dependencies; the new input remains the gate.
 UPDATE public.episodes SET stage='waiting_input',updated_at=now() WHERE id=p_episode;
 INSERT INTO public.state_transitions(episode_id,from_stage,to_stage,reason,actor_id) VALUES(p_episode,e.stage,'waiting_input',p_reason,local_identity.owner_id());
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) VALUES(e.account_id,p_episode,'main_script_reconfirmed',jsonb_build_object('previous_material_id',p_expected,'material_id',m.id,'reason',p_reason),local_identity.owner_id());
 RETURN m;
END $function$

CREATE OR REPLACE FUNCTION local_identity.record_connection_probe(p_id uuid, p_mode text, p_outcome text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.external_connection_versions; c public.external_connections; saved_status text; detail text; qualified boolean;
BEGIN
 IF p_mode NOT IN ('live','simulated') OR p_outcome NOT IN ('verified','invalid','retryable') THEN RAISE EXCEPTION 'Invalid result' USING ERRCODE='22023'; END IF;
 SELECT version.* INTO v FROM public.external_connection_versions version JOIN public.external_connections connection ON connection.id=version.connection_id
 WHERE version.id=p_id AND connection.created_by=local_identity.owner_id() AND version.revoked_at IS NULL FOR UPDATE OF version;
 IF NOT FOUND THEN RAISE EXCEPTION 'Version not found' USING ERRCODE='P0002'; END IF;
 SELECT * INTO c FROM public.external_connections WHERE id=v.connection_id FOR UPDATE;
 IF c.current_version_id<>v.id THEN RAISE EXCEPTION 'Version changed' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM local_identity.connection_bindings WHERE version_id=v.id AND owner_id=c.created_by AND (p_mode='simulated' OR store_mode='keychain')) THEN RAISE EXCEPTION 'Binding required' USING ERRCODE='22023'; END IF;
 saved_status:=CASE WHEN p_mode='simulated' THEN 'retryable' ELSE p_outcome END;
 detail:=CASE WHEN p_mode='simulated' THEN '仅模拟验证；真实Keychain及在线验证尚未完成。' WHEN p_outcome='verified' THEN '连接验证通过。' WHEN p_outcome='invalid' THEN '连接认证失败。' ELSE '本次验证暂不可用；既有验证资格未因此撤销。' END;
 INSERT INTO local_identity.connection_probe_evidence(version_id,owner_id,mode,outcome) VALUES(v.id,c.created_by,p_mode,p_outcome);
 INSERT INTO public.external_connection_verifications(connection_id,connection_version_id,status,detail) VALUES(c.id,v.id,saved_status,detail);
 IF p_mode='live' THEN
  INSERT INTO local_identity.connection_qualifications(version_id,owner_id,qualified) VALUES(v.id,c.created_by,p_outcome='verified')
  ON CONFLICT(version_id) DO UPDATE SET qualified=CASE WHEN p_outcome='retryable' THEN local_identity.connection_qualifications.qualified ELSE p_outcome='verified' END,updated_at=now();
 END IF;
 qualified:=public.connection_version_is_verified(v.id);
 UPDATE public.external_connections SET status=CASE WHEN qualified THEN 'verified' ELSE saved_status END,last_verification_detail=detail,last_verified_at=now() WHERE id=c.id;
END;
$function$

CREATE OR REPLACE FUNCTION local_identity.record_material_reuse(p_material uuid, p_source uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE target public.production_material_revisions;source public.production_material_revisions;origin jsonb;
BEGIN
 SELECT * INTO target FROM public.production_material_revisions WHERE id=p_material;
 SELECT * INTO source FROM public.production_material_revisions WHERE id=p_source;
 IF target.id IS NULL OR source.id IS NULL OR NOT local_identity.lock_owned_input_episode(target.episode_id)
 OR target.episode_id=source.episode_id OR NOT local_identity.script_material_is_approved(source.id)
 OR target.sha256<>source.sha256 OR target.file_size<>source.file_size OR target.material_type<>source.material_type
 OR (SELECT account_id FROM public.episodes WHERE id=target.episode_id) IS DISTINCT FROM (SELECT account_id FROM public.episodes WHERE id=source.episode_id)
 THEN RAISE EXCEPTION 'Approved same-account immutable source required' USING ERRCODE='42501';END IF;
 origin:=jsonb_build_object('source',to_jsonb(source),'approvals',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.approved_at,a.id) FROM public.material_revision_approvals a WHERE a.material_revision_id=source.id));
 INSERT INTO local_identity.material_import_origins(material_id,provenance) VALUES(target.id,origin) ON CONFLICT DO NOTHING;
 RETURN (SELECT provenance FROM local_identity.material_import_origins WHERE material_id=target.id);
END $function$

CREATE OR REPLACE FUNCTION local_identity.record_owned_deletion_cleanup_error(p_key uuid, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb;
BEGIN
 IF session_user<>'loop_app' OR p_message IS NULL THEN RAISE EXCEPTION 'Owned cleanup diagnostic required';END IF;
 SELECT result INTO r FROM local_identity.command_receipts WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key AND result->>'cleanupKey'=p_key::text AND result ? 'cleanupRoot' FOR UPDATE;
 IF r IS NULL THEN
  UPDATE local_identity.episode_deletion_intents SET last_error=p_message WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key AND state='prepared';
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned cleanup receipt unavailable';END IF;
  RETURN NULL;
 END IF;
 IF r->>'cleanupPending'='true' THEN
  r:=jsonb_set(r,'{message}',to_jsonb(p_message));
  UPDATE local_identity.command_receipts SET result=r WHERE owner_id=local_identity.owner_id() AND idempotency_key=p_key;
 END IF;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION local_identity.record_owned_production_metric(p_episode uuid, p_type text, p_source_key text, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid:=local_identity.owner_id();
BEGIN
 IF o IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF NOT local_identity.production_metrics_enabled() THEN RETURN false;END IF;
 IF p_type NOT IN ('estimate_frozen','candidate_adopted','candidate_withdrawn','candidate_rejected','retry_relation') THEN RAISE EXCEPTION 'Owner metric type invalid';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.episodes e JOIN public.account_memberships m ON m.account_id=e.account_id WHERE e.id=p_episode AND m.user_id=o AND m.role='owner') THEN RAISE EXCEPTION 'Owned metric episode required' USING ERRCODE='42501';END IF;
 PERFORM local_identity.validate_production_metric_payload(p_payload);
 PERFORM local_identity.validate_production_metric_scope(p_episode,p_payload);
 RETURN local_identity.append_production_metric(o,p_episode,p_type,p_source_key,p_payload);
END $function$

CREATE OR REPLACE FUNCTION local_identity.record_production_metric_resource(p_sample jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid:=local_identity.owner_id(); at_time timestamptz; inserted integer; old_value jsonb; field text; cpu numeric; mem_used bigint; mem_total bigint; queued integer; running integer; waiting integer; gap numeric;
BEGIN
 IF o IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF NOT local_identity.production_metrics_enabled() THEN RETURN false;END IF;
 IF p_sample IS NULL OR jsonb_typeof(p_sample)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_sample) AS fields(key) WHERE fields.key<>ALL(ARRAY['sampled_at','cpu_percent','memory_used_bytes','memory_total_bytes','queue_count','running_count','resource_wait_count','gpu_percent','gap_seconds'])) OR NOT p_sample ?& ARRAY['sampled_at','queue_count','running_count','resource_wait_count'] OR coalesce(p_sample->'gpu_percent','null'::jsonb)<>'null'::jsonb THEN RAISE EXCEPTION 'Invalid resource sample';END IF;
 IF jsonb_typeof(p_sample->'sampled_at')<>'string' THEN RAISE EXCEPTION 'Resource observation timestamp required';END IF;
 FOREACH field IN ARRAY ARRAY['cpu_percent','memory_used_bytes','memory_total_bytes','queue_count','running_count','resource_wait_count','gap_seconds'] LOOP
  IF p_sample->>field IS NOT NULL AND jsonb_typeof(p_sample->field)<>'number' THEN RAISE EXCEPTION 'Resource numeric value required';END IF;
 END LOOP;
 at_time:=(p_sample->>'sampled_at')::timestamptz;
 IF at_time IS NULL OR at_time>clock_timestamp()+interval '5 seconds' OR at_time<clock_timestamp()-interval '5 minutes' THEN RAISE EXCEPTION 'Resource sample outside observation window';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(o::text||':production-resource-sample',0));
 IF EXISTS(SELECT 1 FROM local_identity.production_metric_resources WHERE owner_id=o AND sampled_at<>at_time AND sampled_at>at_time-interval '30 seconds') THEN RETURN false;END IF;
 INSERT INTO local_identity.production_metric_resources(owner_id,sampled_at,cpu_percent,memory_used_bytes,memory_total_bytes,queue_count,running_count,resource_wait_count,gpu_percent,gap_seconds)
 VALUES(o,at_time,(p_sample->>'cpu_percent')::numeric,(p_sample->>'memory_used_bytes')::bigint,(p_sample->>'memory_total_bytes')::bigint,(p_sample->>'queue_count')::integer,(p_sample->>'running_count')::integer,(p_sample->>'resource_wait_count')::integer,NULL,coalesce((p_sample->>'gap_seconds')::numeric,0)) ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted=0 THEN
  SELECT to_jsonb(s)-'owner_id' INTO old_value FROM local_identity.production_metric_resources s WHERE owner_id=o AND sampled_at=at_time;
  IF old_value IS DISTINCT FROM jsonb_build_object('sampled_at',at_time,'cpu_percent',(p_sample->>'cpu_percent')::numeric,'memory_used_bytes',(p_sample->>'memory_used_bytes')::bigint,'memory_total_bytes',(p_sample->>'memory_total_bytes')::bigint,'queue_count',(p_sample->>'queue_count')::integer,'running_count',(p_sample->>'running_count')::integer,'resource_wait_count',(p_sample->>'resource_wait_count')::integer,'gpu_percent',NULL,'gap_seconds',coalesce((p_sample->>'gap_seconds')::numeric,0)) THEN RAISE EXCEPTION 'Resource sample idempotency content conflict' USING ERRCODE='23505';END IF;
 ELSE
  cpu:=(p_sample->>'cpu_percent')::numeric;mem_used:=(p_sample->>'memory_used_bytes')::bigint;mem_total:=(p_sample->>'memory_total_bytes')::bigint;queued:=(p_sample->>'queue_count')::integer;running:=(p_sample->>'running_count')::integer;waiting:=(p_sample->>'resource_wait_count')::integer;gap:=coalesce((p_sample->>'gap_seconds')::numeric,0);
  INSERT INTO local_identity.production_metric_resource_daily(owner_id,day,samples,cpu_samples,cpu_sum,cpu_max,memory_samples,memory_used_sum,memory_total_sum,memory_used_peak,queue_peak,running_peak,resource_wait_peak,gap_seconds)
  VALUES(o,(at_time AT TIME ZONE 'Asia/Shanghai')::date,1,CASE WHEN cpu IS NULL THEN 0 ELSE 1 END,coalesce(cpu,0),cpu,CASE WHEN mem_used IS NULL OR mem_total IS NULL THEN 0 ELSE 1 END,CASE WHEN mem_total IS NOT NULL THEN coalesce(mem_used,0) ELSE 0 END,CASE WHEN mem_used IS NOT NULL THEN coalesce(mem_total,0) ELSE 0 END,mem_used,queued,running,waiting,gap)
  ON CONFLICT(owner_id,day) DO UPDATE SET samples=local_identity.production_metric_resource_daily.samples+1,cpu_samples=local_identity.production_metric_resource_daily.cpu_samples+excluded.cpu_samples,cpu_sum=local_identity.production_metric_resource_daily.cpu_sum+excluded.cpu_sum,cpu_max=greatest(local_identity.production_metric_resource_daily.cpu_max,excluded.cpu_max),memory_samples=local_identity.production_metric_resource_daily.memory_samples+excluded.memory_samples,memory_used_sum=local_identity.production_metric_resource_daily.memory_used_sum+excluded.memory_used_sum,memory_total_sum=local_identity.production_metric_resource_daily.memory_total_sum+excluded.memory_total_sum,memory_used_peak=greatest(local_identity.production_metric_resource_daily.memory_used_peak,excluded.memory_used_peak),queue_peak=greatest(local_identity.production_metric_resource_daily.queue_peak,excluded.queue_peak),running_peak=greatest(local_identity.production_metric_resource_daily.running_peak,excluded.running_peak),resource_wait_peak=greatest(local_identity.production_metric_resource_daily.resource_wait_peak,excluded.resource_wait_peak),gap_seconds=local_identity.production_metric_resource_daily.gap_seconds+excluded.gap_seconds;
 END IF;
 RETURN inserted=1;
END $function$

CREATE OR REPLACE FUNCTION local_identity.record_script_production_configuration(p_episode uuid, p_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE p local_identity.script_productions; account uuid; BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned production required' USING ERRCODE='42501'; END IF;
 SELECT s.* INTO p FROM local_identity.script_productions s WHERE s.episode_id=p_episode AND s.owner_id=local_identity.owner_id() AND s.authorization_hash=p_hash;
 IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed production required' USING ERRCODE='22023'; END IF;
 SELECT e.account_id INTO account FROM public.episodes e WHERE e.id=p_episode;
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id)
 VALUES(account,p_episode,'script_production_configured',jsonb_build_object('script_sha256',p.script_sha256,'authorization_hash',p.authorization_hash,'enabled',p.enabled),local_identity.owner_id());
