CREATE OR REPLACE FUNCTION local_identity.record_wan_submission(p_task_id uuid, p_attempt integer, p_lease_token uuid, p_provider_task_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if local_identity.actor_role() is distinct from 'service_role' then raise exception 'Worker required' using errcode='42501'; end if;
 perform public.assert_worker_lease(p_task_id,p_attempt,p_lease_token);
 if not exists(select 1 from public.tasks t where t.id=p_task_id and t.provider IN ('bailian','volcengine','minimax','kling') and local_identity.input_task_allowed(t.episode_id,t.task_type)) then raise exception 'Managed Wan task required' using errcode='42501'; end if;
 if char_length(p_provider_task_id) not between 1 and 128 or p_provider_task_id !~ '^[a-zA-Z0-9_-]+$' then raise exception 'Invalid supplier task ID'; end if;
 if not exists(select 1 from public.tasks where id=p_task_id and status='running' and attempt=p_attempt+1 and provider IN ('bailian','volcengine','minimax','kling')) then raise exception 'Current task attempt required'; end if;
 update public.paid_generation_reservations set provider_task_id=p_provider_task_id,request_state='submitted' where task_id=p_task_id and kind='video' and (provider_task_id is null or provider_task_id=p_provider_task_id);
 if not found then raise exception 'Reservation missing or supplier task changed'; end if;
end $function$

CREATE OR REPLACE FUNCTION local_identity.record_worker_production_metric(p_task uuid, p_attempt integer, p_lease uuid, p_type text, p_source_key text, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e uuid; o uuid; wrote boolean:=false;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tasks t JOIN public.episodes ep ON ep.id=t.episode_id JOIN public.account_memberships m ON m.account_id=ep.account_id JOIN local_identity.production_metric_controls c ON c.owner_id=m.user_id AND c.enabled WHERE t.id=p_task AND m.role='owner') THEN RETURN false;END IF;
 PERFORM public.assert_worker_lease(p_task,p_attempt,p_lease);
 IF p_type NOT IN ('provider_request_dispatch','provider_response_observed','provider_outcome_unknown','provider_receipt_persisted','supplier_paid') THEN RAISE EXCEPTION 'Worker metric type invalid';END IF;
 PERFORM local_identity.validate_production_metric_payload(p_payload);
 IF p_payload ? 'task_id' AND p_payload->>'task_id' IS DISTINCT FROM p_task::text OR p_payload ? 'attempt' AND (p_payload->>'attempt')::integer IS DISTINCT FROM p_attempt THEN RAISE EXCEPTION 'Metric attempt scope mismatch' USING ERRCODE='42501';END IF;
 IF p_type='supplier_paid' THEN RAISE EXCEPTION 'No trusted attributed supplier bill adapter is installed' USING ERRCODE='0A000';END IF;
 SELECT episode_id INTO e FROM public.tasks WHERE id=p_task;
 PERFORM local_identity.validate_production_metric_scope(e,p_payload);
 FOR o IN SELECT m.user_id FROM public.episodes ep JOIN public.account_memberships m ON m.account_id=ep.account_id JOIN local_identity.production_metric_controls c ON c.owner_id=m.user_id AND c.enabled WHERE ep.id=e AND m.role='owner' LOOP
  wrote:=local_identity.append_production_metric(o,e,p_type,p_source_key,p_payload||jsonb_build_object('task_id',p_task,'attempt',p_attempt)) OR wrote;
 END LOOP;
 RETURN wrote;
END $function$

