CREATE OR REPLACE FUNCTION local_identity.recover_input_tasks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare stale public.tasks; expired_result jsonb; recovered integer := 0;
begin
  if local_identity.actor_role() is distinct from 'service_role' then
    raise exception 'Worker service role is required' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('loop-worker-lease-recovery',0));
  for stale in select * from public.tasks
    where local_identity.current_worker_task(tasks) and local_identity.input_task_allowed(tasks.episode_id,task_type) and status='running' and not exists(select 1 from local_identity.native_output_publications h where h.task_id=tasks.id) and (claimed_at is null or claimed_at <= clock_timestamp()-interval '30 minutes')
    order by id for update skip locked
  loop
    expired_result := jsonb_build_object('version','worker-result/v1','taskId',stale.id,'status','failed','artifacts','[]'::jsonb,
      'validation',jsonb_build_object('passed',false,'checks',jsonb_build_array(jsonb_build_object('name','worker_lease','passed',false,'detail','Worker lease expired before it reported a result.'))),
      'actualCostCents',0,'blockers','[]'::jsonb,'retry',jsonb_build_object('shouldRetry',stale.attempt < stale.max_attempts,'reason','Worker lease expired.'),'nextStep','Retry after the Worker is available.');
    update public.task_runs set status='failed',result=expired_result,completed_at=clock_timestamp()
      where task_id=stale.id and attempt=stale.attempt-1 and status='running';
    update public.tasks set status=case when stale.attempt < stale.max_attempts then 'ready'::public.task_status else 'failed'::public.task_status end,
      claimed_at=null,lease_token=null,completed_at=case when stale.attempt < stale.max_attempts then null else clock_timestamp() end,last_result=expired_result where id=stale.id;
    insert into public.audit_events(account_id,episode_id,event_type,payload)
      select account_id,id,'worker_lease_expired',jsonb_build_object('task_id',stale.id,'attempt',stale.attempt-1) from public.episodes where id=stale.episode_id;
    recovered := recovered+1;
  end loop;
  return recovered;
end $function$

CREATE OR REPLACE FUNCTION local_identity.recycle_owned_episode(p_episode uuid, p_inventory jsonb, p_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes; version uuid;
BEGIN
 IF NOT local_identity.lock_owned_episode_cleanup(p_episode) THEN RAISE EXCEPTION 'Owned Episode required' USING ERRCODE='42501';END IF;
 SELECT * INTO e FROM public.episodes WHERE id=p_episode;
 IF local_identity.is_recycled_episode(p_episode) THEN RAISE EXCEPTION 'Episode already recycled' USING ERRCODE='55000';END IF;
 PERFORM id FROM public.tasks WHERE episode_id=p_episode ORDER BY id FOR UPDATE NOWAIT;
 IF EXISTS(SELECT 1 FROM public.tasks WHERE episode_id=p_episode AND invalidated_at IS NULL AND status IN ('ready','running'))
  OR EXISTS(SELECT 1 FROM public.asset_locks WHERE episode_id=p_episode AND expires_at>clock_timestamp())
  OR local_identity.episode_deletion_submission_unknown(p_episode)
  OR EXISTS(SELECT 1 FROM public.tasks WHERE episode_id=p_episode AND status<>'completed' AND invalidated_at IS NULL AND coalesce(last_result#>'{preflight,checks}','[]'::jsonb) @> '[{"check":"provider_result_unknown"}]'::jsonb)
  OR EXISTS(SELECT 1 FROM local_identity.workspace_publication_holds(p_episode))
  OR EXISTS(SELECT 1 FROM local_identity.account_directory_migrations WHERE account_id=e.account_id AND status IN ('planned','copying','failed'))
  OR EXISTS(SELECT 1 FROM local_identity.episode_deletion_intents WHERE episode_id=p_episode AND state IN ('prepared','committed')) THEN RAISE EXCEPTION 'Episode has active or unresolved work' USING ERRCODE='55000';END IF;
 IF p_size IS NULL OR p_size<0 OR p_inventory IS NULL OR jsonb_typeof(p_inventory)<>'object' THEN RAISE EXCEPTION 'Invalid recycle inventory' USING ERRCODE='22023';END IF;
 INSERT INTO local_identity.episode_recycle_bin(episode_id,owner_id,archived_before,size_bytes,inventory) VALUES(e.id,local_identity.owner_id(),e.archived_at,p_size,p_inventory) RETURNING revision INTO version;
 UPDATE public.episodes SET archived_at=coalesce(archived_at,clock_timestamp()),updated_at=clock_timestamp() WHERE id=e.id;
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) VALUES(e.account_id,e.id,'episode_recycled',jsonb_build_object('revision',version,'size_bytes',p_size),local_identity.owner_id());
 RETURN version;
END $function$

CREATE OR REPLACE FUNCTION local_identity.register_owned_studio_freeze(p_episode uuid, p_basis uuid, p_reference jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE package public.review_packages;
BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned Studio freeze required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.episodes e WHERE e.id=p_episode AND e.archived_at IS NULL AND e.stage IN ('storyboard_approved','production_ready','render_ready','qc_review') AND NOT local_identity.is_historical_episode(e.id)) THEN RAISE EXCEPTION 'Current editable Studio required' USING ERRCODE='55000';END IF;
 SELECT * INTO package FROM public.review_packages WHERE id=p_basis AND episode_id=p_episode AND invalidated_at IS NULL AND stage IN ('storyboard_review','production_ready','qc_review');
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.review_packages newer WHERE newer.episode_id=p_episode AND newer.stage=package.stage AND newer.invalidated_at IS NULL AND newer.revision_number>package.revision_number) THEN RAISE EXCEPTION 'Current Studio basis required' USING ERRCODE='55000';END IF;
 IF p_reference IS NULL OR jsonb_typeof(p_reference)<>'object' OR p_reference->>'relative_path' IS NULL OR p_reference->>'relative_path' !~ '/openchatcut-frozen/[0-9a-f-]{36}/project[.]json$'
  OR local_identity.episode_current_reference(p_episode,p_reference->>'relative_path') IS NULL
  OR coalesce(p_reference->>'sha256','') !~ '^[0-9a-f]{64}$' OR coalesce(p_reference->>'file_size','') !~ '^[1-9][0-9]{0,15}$'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_reference) key WHERE key NOT IN ('relative_path','sha256','file_size')) THEN RAISE EXCEPTION 'Invalid owned frozen Studio reference' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM public.artifacts a WHERE a.episode_id=p_episode AND a.relative_path=p_reference->>'relative_path' AND (a.sha256<>p_reference->>'sha256' OR a.file_size<>(p_reference->>'file_size')::bigint OR a.artifact_type<>'studio_frozen_project')) THEN RAISE EXCEPTION 'Frozen Studio identity changed' USING ERRCODE='55000';END IF;
 INSERT INTO public.artifacts(episode_id,artifact_type,relative_path,sha256,file_size)
 SELECT p_episode,'studio_frozen_project',p_reference->>'relative_path',p_reference->>'sha256',(p_reference->>'file_size')::bigint
 WHERE NOT EXISTS(SELECT 1 FROM public.artifacts a WHERE a.episode_id=p_episode AND a.relative_path=p_reference->>'relative_path');
END $function$

CREATE OR REPLACE FUNCTION local_identity.register_production_manual_narration(p_workspace uuid, p_shot text, p_material uuid, p_duration numeric, p_text text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces;e public.episodes;m public.production_material_revisions;t public.tasks;a public.artifacts;track_id uuid;
BEGIN
 w:=local_identity.lock_current_production_workspace(p_workspace);
 SELECT * INTO e FROM public.episodes WHERE id=w.episode_id;
 IF e.archived_at IS NOT NULL OR e.stage='production_completed' OR e.main_script_revision_id IS DISTINCT FROM w.script_revision_id OR NOT local_identity.preparation_source_current(w.preparation_revision_id) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.bindings) b WHERE b->>'shotId'=p_shot) THEN RAISE EXCEPTION 'Current workspace shot required' USING ERRCODE='22023';END IF;
 SELECT * INTO m FROM public.production_material_revisions WHERE id=p_material AND episode_id=e.id AND material_type='audio' AND material_purpose IN ('narration','general_reference');
 IF NOT FOUND OR p_duration IS NULL OR p_duration<=0 OR p_duration>7200 OR p_text IS NULL OR length(p_text)>100000 THEN RAISE EXCEPTION 'Verified narration material required' USING ERRCODE='22023';END IF;
 SELECT existing_audio.id INTO track_id FROM public.audio_tracks existing_audio JOIN public.tasks existing_task ON existing_task.id=existing_audio.source_task_id WHERE existing_audio.episode_id=e.id AND existing_audio.source_material_revision_id=m.id AND existing_audio.track_kind='narration' AND existing_audio.cue_id=p_shot AND (existing_task.input_snapshot#>>'{workspace_narration,version}'='workspace-narration/v2' AND existing_task.input_snapshot#>>'{workspace_narration,workspace_id}'=w.id::text AND existing_task.input_snapshot#>>'{workspace_narration,preparation_revision_id}'=w.preparation_revision_id::text OR existing_task.input_snapshot#>>'{workspace_manual_narration,workspace_id}'=w.id::text AND EXISTS(SELECT 1 FROM local_identity.production_preparation_revisions p WHERE p.id=w.preparation_revision_id AND p.source_format='storyboard/v1' AND p.source_reference_id::text=existing_task.input_snapshot->>'storyboard_review_package_id')) AND existing_task.input_snapshot#>>'{media,narration,text}'=p_text;
 IF FOUND THEN RETURN track_id;END IF;
 INSERT INTO public.tasks(episode_id,task_type,status,input_snapshot,budget_limit_cents,max_attempts,provider,model,prompt_version,actual_cost_cents,completed_at,last_result)
 VALUES(e.id,'generate_narration','completed',jsonb_build_object('capability','narration_manual_upload','workspace_narration',jsonb_build_object('version','workspace-narration/v2','workspace_id',w.id,'shot_id',p_shot,'preparation_revision_id',w.preparation_revision_id),'media',jsonb_build_object('narration',jsonb_build_object('text',p_text)),'manual_source',jsonb_build_object('material_revision_id',m.id),'audio_track',jsonb_build_object('kind','narration','cue_id',p_shot,'preparation_revision_id',w.preparation_revision_id,'source_material_revision_id',m.id,'start_seconds',0,'duration_seconds',p_duration)),0,1,'manual_upload','owner-provided-audio','workspace-manual-narration-v2',0,clock_timestamp(),jsonb_build_object('version','manual-result/v1','status','completed','actualCostCents',0,'validation',jsonb_build_object('passed',true),'artifacts',jsonb_build_array(jsonb_build_object('artifactType','narration_audio','relativePath',m.storage_path,'sha256',m.sha256,'fileSize',m.file_size)))) RETURNING * INTO t;
 SELECT * INTO a FROM public.artifacts WHERE episode_id=e.id AND relative_path=m.storage_path;
 IF FOUND THEN
  IF a.sha256<>m.sha256 OR a.file_size<>m.file_size THEN RAISE EXCEPTION 'Registered audio identity differs' USING ERRCODE='22023';END IF;
 ELSE
  INSERT INTO public.artifacts(episode_id,artifact_type,relative_path,sha256,file_size,producer_task_id) VALUES(e.id,'narration_audio',m.storage_path,m.sha256,m.file_size,t.id) RETURNING * INTO a;
 END IF;
 INSERT INTO public.audio_tracks(episode_id,source_task_id,source_artifact_id,preparation_revision_id,source_material_revision_id,track_kind,cue_id,relative_path,sha256,file_size,start_seconds,duration_seconds) VALUES(e.id,t.id,a.id,w.preparation_revision_id,m.id,'narration',p_shot,m.storage_path,m.sha256,m.file_size,0,p_duration) RETURNING id INTO track_id;
 INSERT INTO public.production_dependencies(episode_id,upstream_kind,upstream_id,downstream_kind,downstream_id) VALUES(e.id,'material_revision',m.id,'task',t.id) ON CONFLICT DO NOTHING;
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) VALUES(e.account_id,e.id,'workspace_manual_narration_registered',jsonb_build_object('workspace_id',w.id,'shot_id',p_shot,'material_revision_id',m.id,'task_id',t.id,'audio_track_id',track_id),local_identity.owner_id());
 RETURN track_id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.register_production_preparation(p_episode uuid, p_script uuid, p_id uuid, p_file jsonb, p_manifest jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes; source public.production_material_revisions; existing local_identity.production_preparation_revisions;
 directory text; shot jsonb; next_revision integer;
BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned input required' USING ERRCODE='42501';END IF;
 SELECT * INTO e FROM public.episodes WHERE id=p_episode;
 IF e.archived_at IS NOT NULL OR e.stage NOT IN ('script_approved','storyboard_review','storyboard_approved','production_ready','render_ready','qc_review')
  OR local_identity.is_historical_episode(e.id) OR e.main_script_revision_id IS DISTINCT FROM p_script THEN
  RAISE EXCEPTION 'Current confirmed script required' USING ERRCODE='40001';
 END IF;
 SELECT * INTO source FROM public.production_material_revisions WHERE id=p_script AND episode_id=e.id AND material_type='script';
 IF NOT FOUND OR NOT local_identity.script_material_is_approved(p_script) THEN RAISE EXCEPTION 'Owned confirmed script required' USING ERRCODE='42501';END IF;
 SELECT directory_relative_path INTO directory FROM local_identity.episode_storage_location(e.id);
 IF p_id IS NULL OR directory IS NULL OR jsonb_typeof(p_file) IS DISTINCT FROM 'object'
  OR p_file->>'relativePath' IS DISTINCT FROM directory||'/preparation/'||p_id::text||'.json'
  OR jsonb_typeof(p_file->'sha256') IS DISTINCT FROM 'string' OR p_file->>'sha256' !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(p_file->'fileSize') IS DISTINCT FROM 'number' THEN
  RAISE EXCEPTION 'Verified preparation file required' USING ERRCODE='22023';
 END IF;
 IF (p_file->>'fileSize')::numeric NOT BETWEEN 1 AND 9223372036854775807 OR (p_file->>'fileSize') !~ '^[1-9][0-9]*$' THEN
  RAISE EXCEPTION 'Valid preparation file size required' USING ERRCODE='22023';
 END IF;
 IF jsonb_typeof(p_manifest) IS DISTINCT FROM 'object' OR p_manifest->>'version' IS DISTINCT FROM 'production-preparation/v1'
  OR jsonb_typeof(p_manifest->'shots') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Versioned production preparation required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(p_manifest->'shots') NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Production shots required' USING ERRCODE='22023';END IF;
 FOR shot IN SELECT value FROM jsonb_array_elements(p_manifest->'shots') LOOP
  IF jsonb_typeof(shot) IS DISTINCT FROM 'object' OR jsonb_typeof(shot->'id') IS DISTINCT FROM 'string'
   OR length(btrim(shot->>'id')) NOT BETWEEN 1 AND 128 OR shot->>'id' IS DISTINCT FROM btrim(shot->>'id') OR shot ? 'shotType'
   OR jsonb_typeof(shot->'scriptSegment') IS DISTINCT FROM 'string'
   OR jsonb_typeof(shot->'durationSeconds') IS DISTINCT FROM 'number'
   OR coalesce(shot->>'targetSpec','') NOT IN ('9:16','16:9','1:1')
   OR coalesce(shot->>'visualSource','') NOT IN ('image','video','material','unassigned') THEN
   RAISE EXCEPTION 'Valid current production shot required' USING ERRCODE='22023';
  END IF;
  IF (shot->>'durationSeconds')::numeric NOT BETWEEN 0.1 AND 120 THEN RAISE EXCEPTION 'Valid shot duration required' USING ERRCODE='22023';END IF;
 END LOOP;
 IF (SELECT count(*)<>count(DISTINCT value->>'id') FROM jsonb_array_elements(p_manifest->'shots')) THEN RAISE EXCEPTION 'Unique shot identities required' USING ERRCODE='22023';END IF;
 SELECT * INTO existing FROM local_identity.production_preparation_revisions WHERE id=p_id;
 IF FOUND THEN
  IF existing.episode_id IS DISTINCT FROM p_episode OR existing.script_revision_id IS DISTINCT FROM p_script
   OR existing.script_sha256 IS DISTINCT FROM source.sha256 OR existing.file_reference IS DISTINCT FROM p_file
   OR existing.manifest IS DISTINCT FROM p_manifest OR existing.origin<>'script' OR existing.created_by IS DISTINCT FROM local_identity.owner_id() THEN
   RAISE EXCEPTION 'Preparation identity already belongs to different frozen content' USING ERRCODE='40001';
  END IF;
  RETURN p_id;
 END IF;
 SELECT coalesce(max(revision_number),0)+1 INTO next_revision FROM local_identity.production_preparation_revisions WHERE episode_id=e.id;
 INSERT INTO local_identity.production_preparation_revisions(id,episode_id,script_revision_id,script_sha256,revision_number,origin,source_format,file_reference,manifest,content_sha256,created_by)
 VALUES(p_id,e.id,source.id,source.sha256,next_revision,'script','production-preparation/v1',p_file,p_manifest,encode(extensions.digest(p_manifest::text,'sha256'),'hex'),local_identity.owner_id());
 INSERT INTO local_identity.production_shots(episode_id,shot_id) SELECT e.id,value->>'id' FROM jsonb_array_elements(p_manifest->'shots') ON CONFLICT DO NOTHING;
 INSERT INTO local_identity.production_shot_versions(preparation_revision_id,episode_id,shot_id,position,origin,baseline_text,snapshot)
 SELECT p_id,e.id,value->>'id',ordinality::integer,'script',value->>'scriptSegment',value FROM jsonb_array_elements(p_manifest->'shots') WITH ORDINALITY;
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id)
 VALUES(e.account_id,e.id,'production_preparation_confirmed',jsonb_build_object('preparation_revision_id',p_id,'script_revision_id',source.id,'sha256',p_file->>'sha256'),local_identity.owner_id());
 RETURN p_id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.register_wan_material(p_task_id uuid, p_attempt integer, p_lease_token uuid, p_path text, p_sha256 text, p_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tasks; r public.paid_generation_reservations; owner_id uuid; mid uuid; rev integer;
begin
 if local_identity.actor_role() is distinct from 'service_role' then raise exception 'Worker required' using errcode='42501'; end if;
 perform public.assert_worker_lease(p_task_id,p_attempt,p_lease_token);
 select * into t from public.tasks where id=p_task_id and status='running' and attempt=p_attempt+1 and provider IN ('bailian','volcengine','minimax','kling') for update;
 if not found then raise exception 'Current task attempt required'; end if;
 select * into r from public.paid_generation_reservations where task_id=t.id and provider_task_id is not null for update;
 if not found then raise exception 'Submitted video reservation required'; end if;
 if r.material_revision_id is not null then return r.material_revision_id; end if;
 if p_sha256 is null or p_size is null or p_path is distinct from t.input_snapshot#>>'{output,relative_path}' or p_sha256 !~ '^[0-9a-f]{64}$' or p_size<=0 then raise exception 'Invalid output manifest'; end if;
 owner_id:=(t.input_snapshot->>'requested_by')::uuid;
 if not exists(select 1 from public.account_memberships where account_id=r.account_id and user_id=owner_id and role='owner') then raise exception 'Original requesting Owner no longer has access'; end if;
 perform 1 from public.episodes where id=t.episode_id for update;
 select coalesce(max(revision_number),0)+1 into rev from public.production_material_revisions where episode_id=t.episode_id and material_type='video';
 insert into public.production_material_revisions(episode_id,revision_number,material_type,source_kind,source_path,storage_path,mime_type,sha256,file_size,is_main_script,created_by,material_purpose)
 values(t.episode_id,rev,'video','worker','wan-'||(t.input_snapshot#>>'{shot,id}')||'.mp4',p_path,'video/mp4',p_sha256,p_size,false,owner_id,case t.task_type when 'generate_shot_video' then 'visual_reference' when 'generate_a_roll' then 'a_roll' else 'b_roll' end) returning id into mid;
 update public.paid_generation_reservations set request_state='succeeded',material_revision_id=mid where task_id=t.id;
 return mid;
end $function$

CREATE OR REPLACE FUNCTION local_identity.register_workspace_images()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v local_identity.workspace_visual_candidates; a jsonb; mid uuid; rev integer;ownerid uuid;idx integer:=0;BEGIN
 IF NEW.task_type<>'generate_static_visual' OR NEW.status<>'completed' OR OLD.status='completed' THEN RETURN NEW;END IF;
 SELECT * INTO v FROM local_identity.workspace_visual_candidates WHERE task_id=NEW.id FOR UPDATE;
 IF v.id IS NULL OR v.material_revision_id IS NOT NULL THEN RETURN NEW;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v.episode_id::text,0));
 SELECT owner_id INTO ownerid FROM local_identity.input_episodes WHERE episode_id=v.episode_id;
 FOR a IN SELECT value FROM jsonb_array_elements(NEW.last_result->'artifacts') LOOP
 IF a->>'artifactType'<>'static_visual' OR a->>'relativePath' IS DISTINCT FROM (CASE WHEN idx=0 THEN NEW.input_snapshot#>>'{output,relative_path}' ELSE regexp_replace(NEW.input_snapshot#>>'{output,relative_path}','[.]png$',format('-%s.png',idx+1)) END) THEN RAISE EXCEPTION 'Invalid generated image artifact';END IF;
 SELECT coalesce(max(revision_number),0)+1 INTO rev FROM public.production_material_revisions WHERE episode_id=v.episode_id;
 INSERT INTO public.production_material_revisions(episode_id,revision_number,material_type,source_kind,source_path,storage_path,mime_type,sha256,file_size,is_main_script,created_by,material_purpose) VALUES(v.episode_id,rev,'image','file',v.shot_id||'-generated-'||(idx+1)::text||'.png',a->>'relativePath','image/png',a->>'sha256',(a->>'fileSize')::bigint,false,ownerid,'visual_reference') RETURNING id INTO mid;
 IF idx=0 THEN UPDATE local_identity.workspace_visual_candidates SET material_revision_id=mid WHERE id=v.id;
 ELSE INSERT INTO local_identity.workspace_visual_candidates(workspace_id,episode_id,clip_id,shot_id,target_item_id,input_fingerprint,target_snapshot,request_snapshot,material_revision_id) VALUES(v.workspace_id,v.episode_id,v.clip_id,v.shot_id,v.target_item_id,v.input_fingerprint||'-'||idx,v.target_snapshot,v.request_snapshot||jsonb_build_object('batchId',v.id),mid);END IF;
 idx:=idx+1;END LOOP;
 IF idx<>(v.request_snapshot#>>'{imageSettings,count}')::integer THEN RAISE EXCEPTION 'Incomplete image batch';END IF;
 UPDATE public.paid_generation_reservations SET request_state='succeeded',material_revision_id=(SELECT material_revision_id FROM local_identity.workspace_visual_candidates WHERE id=v.id) WHERE task_id=NEW.id;
 RETURN NEW;
END $function$

