CREATE OR REPLACE FUNCTION local_identity.retain_history_cleanup_file(p_key uuid, p_sha text, p_session_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE target jsonb;
BEGIN
 IF session_user<>'loop_app' OR NOT EXISTS(SELECT 1 FROM local_identity.sessions WHERE token_hash=p_session_hash AND owner_id=local_identity.owner_id() AND revoked_at IS NULL AND expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'Verified Owner session required' USING ERRCODE='42501';END IF;
 SELECT t INTO target FROM local_identity.command_receipts r CROSS JOIN LATERAL jsonb_array_elements(r.result->'historyCleanupTargets')t WHERE r.owner_id=local_identity.owner_id() AND r.idempotency_key=p_key AND t->>'sha'=p_sha;
 IF target IS NULL THEN RAISE EXCEPTION 'Cleanup target unavailable' USING ERRCODE='42501';END IF;
 INSERT INTO local_identity.history_retained_files(owner_id,logical_path,sha256,bytes,kind,metadata,retention_reason)
 VALUES(local_identity.owner_id(),'retained-after-deletion/'||p_key::text||'/'||p_sha,p_sha,(target->>'bytes')::bigint,'retained-dependency',jsonb_build_object('deletionKey',p_key),'business-dependency') ON CONFLICT DO NOTHING;
END $function$

CREATE OR REPLACE FUNCTION local_identity.retry_input_media(p_episode_id uuid, p_task_id uuid)
 RETURNS public.tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous public.tasks; created public.tasks; frozen jsonb; nonce text:=gen_random_uuid()::text; path text; BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode_id) THEN RAISE EXCEPTION 'Owner managed Episode required' USING ERRCODE='42501'; END IF;
 SELECT t.* INTO previous FROM public.tasks t JOIN local_identity.input_episodes i ON i.episode_id=t.episode_id AND i.media_enabled JOIN public.episodes e ON e.id=t.episode_id AND e.stage='storyboard_approved' WHERE t.id=p_task_id AND t.episode_id=p_episode_id AND t.task_type IN ('generate_shot_video','search_shot_video','preview_shot_video','generate_a_roll','generate_b_roll','generate_soundtrack','extract_embedded_audio') AND t.status IN ('failed','blocked') AND t.invalidated_at IS NULL FOR UPDATE OF t;
 IF NOT FOUND THEN RAISE EXCEPTION 'Current failed media task required' USING ERRCODE='22023'; END IF;
 IF previous.task_type='extract_embedded_audio' AND previous.input_snapshot#>>'{shot_preparation,draft_id}' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.shot_preparation_drafts d JOIN public.review_packages p ON p.id=d.review_package_id WHERE d.id::text=previous.input_snapshot#>>'{shot_preparation,draft_id}' AND d.episode_id=p_episode_id AND d.video_status='ready' AND p.invalidated_at IS NULL AND d.current_video_artifact_id::text=previous.input_snapshot#>>'{source_video_artifact,id}') THEN RAISE EXCEPTION 'Current source-video draft required' USING ERRCODE='22023'; END IF;
 IF previous.provider IN ('bailian','volcengine','minimax','kling') THEN RAISE EXCEPTION 'Resume the saved Wan task; automatic paid retry is forbidden'; END IF;
 IF previous.task_type <> 'extract_embedded_audio' AND NOT EXISTS(SELECT 1 FROM public.review_packages p JOIN public.approvals a ON a.review_package_id=p.id AND a.stage='storyboard_approved' AND a.decision='approved' WHERE p.id::text=previous.input_snapshot->>'storyboard_review_package_id' AND p.episode_id=p_episode_id AND p.stage='storyboard_review' AND p.invalidated_at IS NULL AND p.revision_number=(SELECT max(q.revision_number) FROM public.review_packages q WHERE q.episode_id=p_episode_id AND q.stage='storyboard_review' AND q.invalidated_at IS NULL)) THEN RAISE EXCEPTION 'Current approved media package required' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.tasks t WHERE t.episode_id=p_episode_id AND t.input_snapshot->>'native_media_retry_of'=p_task_id::text AND t.status IN ('ready','running','completed')) THEN SELECT * INTO created FROM public.tasks t WHERE t.episode_id=p_episode_id AND t.input_snapshot->>'native_media_retry_of'=p_task_id::text AND t.status IN ('ready','running','completed') ORDER BY created_at DESC LIMIT 1; RETURN created; END IF;
 frozen:=previous.input_snapshot-'runtime_constraints';path:=frozen#>>'{output,relative_path}';
 frozen:=frozen||jsonb_build_object('native_media_retry_of',p_task_id,'configuration_hash',coalesce(frozen->>'configuration_hash','')||'-retry-'||nonce);
 frozen:=jsonb_set(frozen,'{output,relative_path}',to_jsonb(regexp_replace(path,'(\.[^/.]+)$','-retry-'||nonce||'\1')));
 INSERT INTO public.tasks(episode_id,task_type,status,input_snapshot,budget_limit_cents,max_attempts,provider,model,prompt_version) VALUES(p_episode_id,previous.task_type,'ready',frozen,previous.budget_limit_cents,previous.max_attempts,previous.provider,previous.model,previous.prompt_version) RETURNING * INTO created;
 IF previous.task_type='extract_embedded_audio' AND previous.input_snapshot#>>'{shot_preparation,draft_id}' IS NOT NULL THEN UPDATE public.shot_preparation_drafts SET audio_status='running',pending_source_audio_task_id=created.id,source_audio_error=NULL,updated_at=now() WHERE id::text=previous.input_snapshot#>>'{shot_preparation,draft_id}' AND episode_id=p_episode_id; ELSIF previous.input_snapshot#>>'{shot_preparation,draft_id}' IS NOT NULL THEN UPDATE public.shot_preparation_drafts SET video_status='running',pending_video_task_id=created.id,video_error=NULL,updated_at=now() WHERE id::text=previous.input_snapshot#>>'{shot_preparation,draft_id}' AND episode_id=p_episode_id; END IF;
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) SELECT e.account_id,e.id,'native_media_retry_requested',jsonb_build_object('previous_task_id',previous.id,'task_id',created.id),local_identity.owner_id() FROM public.episodes e WHERE e.id=p_episode_id;
 RETURN created;
END $function$

CREATE OR REPLACE FUNCTION local_identity.retry_owned_final_render(p_episode_id uuid, p_reason text)
 RETURNS public.tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.episodes; t public.tasks; previous_status text;
BEGIN
 IF NOT local_identity.owned_delivery_episode(p_episode_id) OR btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Owned delivery Episode and reason required' USING ERRCODE='42501'; END IF;
 SELECT * INTO e FROM public.episodes WHERE id=p_episode_id;
 SELECT task.* INTO t FROM public.tasks task JOIN public.review_packages p ON p.id::text=task.input_snapshot#>>'{final_render,source_review_package_id}' AND p.episode_id=task.episode_id AND p.stage='qc_review' AND p.invalidated_at IS NULL JOIN public.approvals a ON a.review_package_id=p.id AND a.episode_id=p_episode_id AND a.stage='qc_passed' AND a.decision='approved' JOIN public.account_memberships m ON m.account_id=e.account_id AND m.user_id=a.actor_id AND m.role='owner' WHERE task.episode_id=p_episode_id AND task.task_type='generate_final_render' AND task.invalidated_at IS NULL ORDER BY task.created_at DESC LIMIT 1 FOR UPDATE OF task;
 IF NOT FOUND OR e.stage NOT IN ('qc_passed','render_ready') OR t.status NOT IN ('failed','blocked') OR EXISTS(SELECT 1 FROM public.tasks WHERE episode_id=p_episode_id AND task_type IN ('generate_review_render','generate_final_render') AND status IN ('ready','running') AND invalidated_at IS NULL) THEN RAISE EXCEPTION 'Current stopped final render required' USING ERRCODE='55000'; END IF;
 previous_status:=t.status;
 IF t.status='failed' AND e.stage='qc_passed' THEN RETURN public.retry_failed_final_render(p_episode_id,p_reason); END IF;
 UPDATE public.tasks SET status='ready',max_attempts=attempt+1,claimed_at=NULL,completed_at=NULL WHERE id=t.id RETURNING * INTO t;
 UPDATE public.episodes SET stage='qc_passed',updated_at=now() WHERE id=p_episode_id;
 IF e.stage<>'qc_passed' THEN INSERT INTO public.state_transitions(episode_id,from_stage,to_stage,reason,actor_id) VALUES(p_episode_id,e.stage,'qc_passed',btrim(p_reason),local_identity.owner_id()); END IF;
 INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id) VALUES(e.account_id,p_episode_id,'final_render_retry_requested',jsonb_build_object('task_id',t.id,'attempt',t.attempt,'reason',btrim(p_reason),'previous_status',previous_status),local_identity.owner_id());
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION local_identity.retry_workspace_visual(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v local_identity.workspace_visual_candidates; t public.tasks; BEGIN
 SELECT * INTO v FROM local_identity.workspace_visual_candidates WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(v.episode_id) THEN RAISE EXCEPTION 'Owned visual request required' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.tasks WHERE id=v.task_id FOR UPDATE;
 IF NOT FOUND OR t.status NOT IN ('failed','blocked') OR t.invalidated_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.paid_generation_reservations r JOIN local_identity.workspace_visual_submissions s ON s.task_id=r.task_id WHERE r.task_id=t.id AND r.provider_task_id IS NOT NULL AND s.outcome<>'rejected') THEN RAISE EXCEPTION 'Only a saved Provider ID may resume; unknown submission cannot be repeated' USING ERRCODE='55000'; END IF;
 UPDATE public.tasks SET status='ready',max_attempts=attempt+1,claimed_at=null,completed_at=null WHERE id=t.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.save_production_caption_input(p_workspace uuid, p_clip uuid, p_contract jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces; b jsonb; voice local_identity.workspace_narration_inputs;
BEGIN
 w:=local_identity.lock_current_production_workspace(p_workspace);
 SELECT value INTO b FROM jsonb_array_elements(w.bindings) WHERE value->>'id'=p_clip::text;
 IF b IS NULL OR NOT coalesce(public.is_valid_shot_caption_contract(p_contract),false) THEN RAISE EXCEPTION 'Workspace caption input invalid' USING ERRCODE='22023';END IF;
 -- Follow the current versioned voice input; historical draft evidence stays immutable.
 IF p_contract->>'content_mode'='follow_tts' THEN
  SELECT * INTO voice FROM local_identity.workspace_narration_inputs WHERE workspace_id=w.id AND preparation_revision_id=w.preparation_revision_id AND shot_id=b->>'shotId';
  IF voice.mode IS DISTINCT FROM 'tts' OR p_contract->>'text' IS DISTINCT FROM voice.narration_text THEN RAISE EXCEPTION 'Captions must follow current narration text' USING ERRCODE='40001';END IF;
 END IF;
 INSERT INTO local_identity.workspace_caption_inputs(workspace_id,episode_id,preparation_revision_id,shot_id,contract)
  VALUES(w.id,w.episode_id,w.preparation_revision_id,b->>'shotId',p_contract)
  ON CONFLICT(workspace_id,preparation_revision_id,shot_id) DO UPDATE SET contract=excluded.contract,updated_at=clock_timestamp()
   WHERE workspace_caption_inputs.contract IS DISTINCT FROM excluded.contract;
END $function$

CREATE OR REPLACE FUNCTION local_identity.save_recycle_limit(p_bytes bigint, p_revision bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current local_identity.recycle_bin_settings;
BEGIN
 IF local_identity.owner_id() IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF p_bytes IS NULL OR p_bytes NOT BETWEEN 100000000 AND 1000000000000 THEN RAISE EXCEPTION 'Invalid recycle limit' USING ERRCODE='22023';END IF;
 INSERT INTO local_identity.recycle_bin_settings(owner_id) VALUES(local_identity.owner_id()) ON CONFLICT DO NOTHING;
 SELECT * INTO current FROM local_identity.recycle_bin_settings WHERE owner_id=local_identity.owner_id() FOR UPDATE;
 IF current.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'Recycle settings changed' USING ERRCODE='55000';END IF;
 UPDATE local_identity.recycle_bin_settings SET limit_bytes=p_bytes,revision=revision+1 WHERE owner_id=local_identity.owner_id() RETURNING revision INTO p_revision;
 RETURN p_revision;
END $function$

CREATE OR REPLACE FUNCTION local_identity.save_selected_workspace_narration(p_episode uuid, p_review uuid, p_shot text, p_text text, p_voice text, p_rate numeric, p_language text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.shot_preparation_drafts;previous public.shot_preparation_drafts;caption_text text;BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned input required' USING ERRCODE='42501';END IF;
 SELECT * INTO previous FROM public.shot_preparation_drafts WHERE episode_id=p_episode AND review_package_id=p_review AND shot_id=p_shot;
 caption_text:=coalesce(previous.subtitle_text,(SELECT s->>'scriptSegment' FROM public.review_packages r CROSS JOIN LATERAL jsonb_array_elements(r.context_snapshot#>'{worker_result,storyboard,shots}') s WHERE r.id=p_review AND s->>'id'=p_shot),p_text);
 saved:=public.save_shot_preparation_draft(p_episode,p_review,p_shot,'tts',caption_text,coalesce(previous.subtitles_enabled,true),p_text,p_voice,p_rate);
 UPDATE public.shot_preparation_drafts SET subtitle_text=caption_text,tts_text=p_text,tts_voice=p_voice,tts_override_voice=p_voice,tts_speaking_rate=p_rate,tts_override_speaking_rate=p_rate,tts_language_code=p_language WHERE id=saved.id;

 UPDATE public.shot_preparation_drafts SET
  subtitle_text=caption_text,
  subtitles_enabled=coalesce(previous.subtitles_enabled,saved.subtitles_enabled),
  caption_contract=CASE WHEN previous.id IS NOT NULL THEN previous.caption_contract ELSE jsonb_set(jsonb_set(saved.caption_contract,'{content_mode}','"follow_tts"'::jsonb),'{text}',to_jsonb(caption_text)) END
 WHERE id=saved.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.save_workspace_caption_input(p_workspace uuid, p_clip uuid, p_contract jsonb)
 RETURNS public.shot_preparation_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces; b jsonb; d public.shot_preparation_drafts; BEGIN
 SELECT * INTO w FROM local_identity.production_workspaces WHERE id=p_workspace FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(w.episode_id) OR local_identity.is_historical_episode(w.episode_id) OR NOT EXISTS(SELECT 1 FROM public.episodes e JOIN public.review_packages p ON p.id=w.storyboard_package_id WHERE e.id=w.episode_id AND e.main_script_revision_id=w.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed' AND p.invalidated_at IS NULL) THEN RAISE EXCEPTION 'Current Owner workspace required' USING ERRCODE='42501'; END IF;
 SELECT value INTO b FROM jsonb_array_elements(w.bindings) WHERE value->>'id'=p_clip::text;
 IF b IS NULL OR NOT public.is_valid_shot_caption_contract(p_contract) THEN RAISE EXCEPTION 'Workspace caption input invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO d FROM public.shot_preparation_drafts WHERE episode_id=w.episode_id AND review_package_id=w.storyboard_package_id AND shot_id=b->>'shotId' FOR UPDATE;
 IF p_contract->>'content_mode'='follow_tts' AND (d.audio_mode IS DISTINCT FROM 'tts' OR p_contract->>'text' IS DISTINCT FROM d.tts_text) THEN RAISE EXCEPTION 'Captions must follow current narration text' USING ERRCODE='40001'; END IF;
 IF d.id IS NULL THEN
  INSERT INTO public.shot_preparation_drafts(episode_id,review_package_id,shot_id,audio_mode,subtitle_text,subtitles_enabled,caption_contract)
  VALUES(w.episode_id,w.storyboard_package_id,b->>'shotId','none',p_contract->>'text',(p_contract->>'enabled')::boolean,p_contract) RETURNING * INTO d;
 ELSE
  UPDATE public.shot_preparation_drafts SET frozen_at=NULL,frozen_by=NULL,subtitle_text=p_contract->>'text',subtitles_enabled=(p_contract->>'enabled')::boolean,caption_contract=p_contract,updated_at=clock_timestamp() WHERE id=d.id RETURNING * INTO d;
 END IF;
 RETURN d;
END $function$

CREATE OR REPLACE FUNCTION local_identity.save_workspace_narration_draft(p_episode uuid, p_review uuid, p_shot text, p_mode text, p_text text, p_voice text, p_rate numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE previous public.shot_preparation_drafts; saved public.shot_preparation_drafts; caption_text text; BEGIN
 SELECT * INTO previous FROM public.shot_preparation_drafts WHERE episode_id=p_episode AND review_package_id=p_review AND shot_id=p_shot;
 caption_text:=coalesce(previous.subtitle_text,(SELECT s->>'scriptSegment' FROM public.review_packages r CROSS JOIN LATERAL jsonb_array_elements(r.context_snapshot#>'{worker_result,storyboard,shots}') s WHERE r.id=p_review AND s->>'id'=p_shot),p_text);
 saved:=public.save_shot_preparation_draft(p_episode,p_review,p_shot,p_mode,caption_text,coalesce(previous.subtitles_enabled,true),p_text,p_voice,p_rate);
 IF p_mode='tts' THEN saved:=public.save_shot_tts_override(p_episode,p_review,p_shot,p_voice,p_rate); END IF;
 IF previous.id IS NOT NULL AND (previous.tts_text IS DISTINCT FROM saved.tts_text OR previous.tts_voice IS DISTINCT FROM saved.tts_voice OR previous.tts_speaking_rate IS DISTINCT FROM saved.tts_speaking_rate OR previous.tts_language_code IS DISTINCT FROM saved.tts_language_code) THEN
 UPDATE public.shot_preparation_drafts SET pending_tts_task_id=NULL,current_tts_task_id=NULL,current_audio_track_id=NULL,tts_actual_duration_seconds=NULL,audio_status=CASE WHEN p_mode='tts' THEN 'pending' ELSE 'ready' END WHERE id=saved.id;
 END IF;

 UPDATE public.shot_preparation_drafts SET
  subtitle_text=caption_text,
  subtitles_enabled=coalesce(previous.subtitles_enabled,saved.subtitles_enabled),
  caption_contract=CASE WHEN previous.id IS NOT NULL THEN previous.caption_contract ELSE jsonb_set(jsonb_set(saved.caption_contract,'{content_mode}','"follow_tts"'::jsonb),'{text}',to_jsonb(caption_text)) END
 WHERE id=saved.id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.scope_input_post_task(p_task_id uuid)
 RETURNS public.tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tasks; prefix text; BEGIN
 SELECT * INTO t FROM public.tasks WHERE id=p_task_id;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(t.episode_id) OR t.task_type NOT IN ('extract_embedded_audio','align_shot_captions','generate_shot_sync_preview') THEN RAISE EXCEPTION 'Managed Owner post-production task required' USING ERRCODE='42501'; END IF;
 IF t.status<>'ready' OR t.attempt<>0 OR t.created_at<>transaction_timestamp() THEN RETURN t; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.shot_preparation_drafts d JOIN public.review_packages p ON p.id=d.review_package_id JOIN public.approvals a ON a.review_package_id=p.id AND a.stage='storyboard_approved' AND a.decision='approved' WHERE d.id::text=t.input_snapshot#>>'{shot_preparation,draft_id}' AND d.episode_id=t.episode_id AND p.invalidated_at IS NULL) THEN RAISE EXCEPTION 'Approved shot task required' USING ERRCODE='22023'; END IF;
 prefix:=format('%s/post-production/%s',(SELECT directory_relative_path FROM local_identity.episode_storage_location(t.episode_id)),t.id);
 UPDATE public.tasks SET input_snapshot=jsonb_set(input_snapshot,'{output,relative_path}',to_jsonb(prefix||CASE t.task_type WHEN 'align_shot_captions' THEN '/alignment.json' WHEN 'extract_embedded_audio' THEN '/source.mp3' ELSE '/proxy.mp4' END)) WHERE id=t.id RETURNING * INTO t;
 IF t.task_type='generate_shot_sync_preview' THEN UPDATE public.tasks SET input_snapshot=jsonb_set(input_snapshot,'{review_render,project_relative_path}',to_jsonb(prefix||'/index.html')) WHERE id=t.id RETURNING * INTO t; END IF;
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION local_identity.scope_input_studio_task(p_task_id uuid, p_fingerprint text, p_frozen jsonb)
 RETURNS public.tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tasks; prefix text; recorded jsonb; reference jsonb;
BEGIN
 SELECT * INTO t FROM public.tasks WHERE id=p_task_id;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(t.episode_id) OR NOT local_identity.input_task_allowed(t.episode_id,t.task_type) OR t.task_type<>'generate_review_render' OR t.status<>'ready' OR t.attempt<>0 OR t.created_at<>transaction_timestamp() OR p_fingerprint !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Fresh Owner Studio task required' USING ERRCODE='42501'; END IF;
 recorded:=coalesce(t.input_snapshot#>'{review_render,adjustments,studio_project}',t.input_snapshot->'studio_project');
 reference:=jsonb_build_object('relative_path',recorded->'relative_path','sha256',recorded->'sha256','file_size',recorded->'file_size');
 IF p_frozen IS NULL OR reference IS DISTINCT FROM p_frozen OR (NOT local_identity.owned_studio_frozen_reference(t.episode_id,p_frozen) OR p_frozen->>'relative_path' !~ '/openchatcut-frozen/[0-9a-f-]{36}/project[.]json$') OR p_frozen->>'sha256' !~ '^[0-9a-f]{64}$' OR (p_frozen->>'file_size')::bigint<1 THEN RAISE EXCEPTION 'Frozen Studio task differs' USING ERRCODE='22023'; END IF;
 prefix:=format('%s/review-render/%s',(SELECT directory_relative_path FROM local_identity.episode_storage_location(t.episode_id)),t.id);
 UPDATE public.tasks SET input_snapshot=jsonb_set(jsonb_set(jsonb_set(input_snapshot,'{output,relative_path}',to_jsonb(prefix||'/review-render.mp4')),'{review_render,project_relative_path}',to_jsonb(prefix||'/index.html')),'{review_render,adjustments,studio_project}',coalesce(recorded,'{}'::jsonb)||p_frozen)||jsonb_build_object('native_studio_fingerprint',p_fingerprint,'input_artifacts',coalesce(input_snapshot->'input_artifacts','[]'::jsonb)||jsonb_build_array(jsonb_build_object('artifactType','studio_frozen_project','relativePath',p_frozen->>'relative_path','sha256',p_frozen->>'sha256','fileSize',(p_frozen->>'file_size')::bigint))) WHERE id=t.id RETURNING * INTO t;
 UPDATE public.review_render_composition_revisions SET composition_config=jsonb_set(composition_config,'{studio_project}',coalesce(recorded,'{}'::jsonb)||p_frozen) WHERE id::text=t.input_snapshot#>>'{review_render,composition_revision_id}' AND episode_id=t.episode_id;
 UPDATE public.artifacts SET producer_task_id=t.id WHERE episode_id=t.episode_id AND artifact_type='studio_frozen_project' AND relative_path=p_frozen->>'relative_path' AND sha256=p_frozen->>'sha256' AND file_size=(p_frozen->>'file_size')::bigint AND producer_task_id IS NULL;
 IF NOT FOUND THEN INSERT INTO public.artifacts(episode_id,producer_task_id,artifact_type,relative_path,sha256,file_size) SELECT t.episode_id,t.id,'studio_frozen_project',p_frozen->>'relative_path',p_frozen->>'sha256',(p_frozen->>'file_size')::bigint WHERE NOT EXISTS(SELECT 1 FROM public.artifacts a WHERE a.episode_id=t.episode_id AND a.producer_task_id=t.id AND a.artifact_type='studio_frozen_project' AND a.relative_path=p_frozen->>'relative_path' AND a.sha256=p_frozen->>'sha256' AND a.file_size=(p_frozen->>'file_size')::bigint);END IF;
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION local_identity.secret_reference_inventory(p_session_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF session_user<>'loop_app' OR NOT EXISTS(SELECT 1 FROM local_identity.sessions WHERE token_hash=p_session_hash AND owner_id=local_identity.owner_id() AND revoked_at IS NULL AND expires_at>clock_timestamp()) THEN
  RAISE EXCEPTION 'Verified application session required' USING ERRCODE='42501';
 END IF;
 SELECT jsonb_build_object(
  'connections',coalesce((SELECT jsonb_agg(jsonb_build_object('reference',b.secret_ref,'connectionId',c.id,'name',c.name,'provider',v.provider,'version',v.version,'current',c.current_version_id=v.id,'revoked',v.revoked_at IS NOT NULL)) FROM local_identity.connection_bindings b JOIN public.external_connection_versions v ON v.id=b.version_id JOIN public.external_connections c ON c.id=v.connection_id WHERE b.store_mode='keychain'),'[]') || coalesce((SELECT jsonb_agg(jsonb_build_object('reference',b.secret_ref,'connectionId',c.id,'name',c.name||' · 账务','provider',b.provider,'version',1,'current',b.status='current','revoked',b.status='retired')) FROM local_identity.connection_billing_credentials b JOIN public.external_connections c ON c.id=b.connection_id),'[]'),
  'intents',coalesce((SELECT jsonb_agg(jsonb_build_object('reference',secret_ref,'name',metadata->>'name','operation',metadata->>'command')) FROM local_identity.connection_intents WHERE store_mode='keychain' AND applied_at IS NULL),'[]'),
  'history',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(
   SELECT reference,count(*)::integer occurrences FROM(
    SELECT m[1] reference FROM local_identity.history_versions v CROSS JOIN LATERAL regexp_matches(v.payload::text,'(?:"\$keychainRef"\s*:\s*"|keychain:)([a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12})','g') m
    UNION ALL SELECT r->>'reference' FROM local_identity.history_file_protections p CROSS JOIN LATERAL jsonb_array_elements(p.replacements) r
    UNION ALL SELECT r->>'reference' FROM local_identity.history_file_catalog f CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(f.metadata->'replacements')='array' THEN f.metadata->'replacements' ELSE '[]'::jsonb END) r
   ) refs WHERE reference ~ '^[a-f0-9]{8}-([a-f0-9]{4}-){3}[a-f0-9]{12}$' GROUP BY reference
  ) x),'[]'),
  'files',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(
    SELECT DISTINCT ON(coalesce(p.protected_sha256,f.sha256)) coalesce(p.protected_sha256,f.sha256) sha256, coalesce(p.protected_bytes,f.bytes) bytes, f.logical_path FROM local_identity.history_file_catalog f LEFT JOIN local_identity.history_file_protections p ON p.original_sha256=f.sha256
    WHERE f.bytes>0 AND (f.logical_path ~* '\.(json|jsonl|md|txt|sql|ya?ml|toml|env|sh|py|[cm]?[jt]sx?|html|css|csv|log|ini|conf)$' OR f.kind IN ('text','source'))
    ORDER BY coalesce(p.protected_sha256,f.sha256),f.logical_path
  ) x),'[]')
 ) INTO result;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION local_identity.set_episode_business_quality(p_episode uuid, p_tier text, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid:=local_identity.owner_id(); old_value jsonb; n integer;
BEGIN
 IF o IS NULL OR NOT local_identity.production_metrics_enabled() THEN RAISE EXCEPTION 'Production metrics not enabled' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.episodes e JOIN public.account_memberships m ON m.account_id=e.account_id WHERE e.id=p_episode AND m.user_id=o AND m.role='owner' FOR UPDATE OF e;
 IF NOT FOUND THEN RAISE EXCEPTION 'Owned episode required' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.episodes e WHERE e.id=p_episode AND (e.archived_at IS NOT NULL OR e.stage='production_completed')) OR EXISTS(SELECT 1 FROM local_identity.episode_recycle_bin r WHERE r.episode_id=p_episode) THEN RAISE EXCEPTION 'Episode is read only' USING ERRCODE='55000';END IF;
 IF NOT EXISTS(SELECT 1 FROM local_identity.input_episodes WHERE episode_id=p_episode AND owner_id=o) THEN RAISE EXCEPTION 'Current input episode required' USING ERRCODE='42501';END IF;
 IF p_tier IS NULL OR p_tier NOT IN ('unspecified','low','medium','high') THEN RAISE EXCEPTION 'Invalid business quality';END IF;
 old_value:=local_identity.episode_business_quality(p_episode);
 IF p_expected_revision IS NOT NULL AND p_expected_revision<>(old_value->>'revision')::integer THEN RAISE EXCEPTION 'Business quality revision changed' USING ERRCODE='40001';END IF;
 IF old_value->>'tier'=p_tier THEN RETURN old_value;END IF;
 n:=(old_value->>'revision')::integer+1;
 INSERT INTO local_identity.production_metric_quality_versions(owner_id,episode_id,revision,tier) VALUES(o,p_episode,n,p_tier);
 PERFORM local_identity.append_production_metric(o,p_episode,'quality_changed','quality:'||n,jsonb_build_object('tier',p_tier,'revision',n),NULL,p_tier);
 RETURN jsonb_build_object('tier',p_tier,'revision',n);
END $function$

CREATE OR REPLACE FUNCTION local_identity.set_production_metrics_enabled(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o uuid:=local_identity.owner_id(); previous boolean; e record; q record; at_time timestamptz:=clock_timestamp();
BEGIN
 IF o IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='42501';END IF;
 IF p_enabled IS NULL THEN RAISE EXCEPTION 'Boolean activation required';END IF;
 INSERT INTO local_identity.production_metric_controls(owner_id) VALUES(o) ON CONFLICT DO NOTHING;
 SELECT enabled INTO previous FROM local_identity.production_metric_controls WHERE owner_id=o FOR UPDATE;
 UPDATE local_identity.production_metric_controls SET enabled=p_enabled,coverage_started_at=CASE WHEN p_enabled THEN coalesce(coverage_started_at,at_time) ELSE coverage_started_at END,updated_at=CASE WHEN previous IS DISTINCT FROM p_enabled THEN at_time ELSE updated_at END WHERE owner_id=o;
 IF previous AND NOT p_enabled THEN UPDATE local_identity.production_metric_coverage_periods SET ended_at=at_time WHERE owner_id=o AND ended_at IS NULL;END IF;
 IF p_enabled AND NOT previous THEN
  INSERT INTO local_identity.production_metric_coverage_periods(owner_id,started_at) VALUES(o,at_time);
  FOR e IN SELECT ep.id,ep.stage FROM public.episodes ep JOIN public.account_memberships m ON m.account_id=ep.account_id WHERE m.user_id=o AND m.role='owner' LOOP
   PERFORM local_identity.append_production_metric(o,e.id,'coverage_observation','coverage:'||extract(epoch from at_time)::text,jsonb_build_object('stage',e.stage,'observed_only',true),at_time);
   FOR q IN SELECT id,attempt,available_at FROM public.tasks WHERE episode_id=e.id AND status='ready' AND invalidated_at IS NULL LOOP
    INSERT INTO local_identity.production_metric_queue_cycles(owner_id,task_id,episode_id,attempt,enqueued_at,eligible_at,observed_only) VALUES(o,q.id,e.id,q.attempt,at_time,greatest(q.available_at,at_time),true) ON CONFLICT DO NOTHING;
   END LOOP;
  END LOOP;
 END IF;
 RETURN (SELECT jsonb_build_object('enabled',enabled,'coverageStartedAt',coverage_started_at) FROM local_identity.production_metric_controls WHERE owner_id=o);
END $function$

CREATE OR REPLACE FUNCTION local_identity.shot_video_snapshot(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE result jsonb:=p; media jsonb:=p->'media';types jsonb;
BEGIN
 result:=jsonb_set(result,'{capability}',to_jsonb(CASE coalesce(p#>>'{media,video,request,operation}',p#>>'{media,b_roll,request,operation}') WHEN 'search' THEN 'shot_video_search' WHEN 'preview' THEN 'shot_video_preview' ELSE 'shot_video_generation' END));
 IF media ? 'wan_video' THEN result:=jsonb_set(result,'{media}',(media-'wan_video')||jsonb_build_object('video',media->'wan_video'));
 ELSIF media ? 'b_roll' THEN result:=jsonb_set(result,'{media}',(media-'b_roll')||jsonb_build_object('video',media->'b_roll'));END IF;
 IF jsonb_typeof(result->'shot')='object' THEN result:=jsonb_set(result,'{shot}',(result->'shot')-'shotType');END IF;
 SELECT jsonb_agg(CASE WHEN value IN ('"a_roll_video"'::jsonb,'"b_roll_asset"'::jsonb) THEN '"shot_video"'::jsonb ELSE value END) INTO types FROM jsonb_array_elements(p#>'{output,required_artifact_types}');
 IF types IS NOT NULL THEN result:=jsonb_set(result,'{output,required_artifact_types}',types);END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION local_identity.stop_workspace_queued_tasks(p_workspace uuid, p_kind text, p_shot text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces; stopped integer;
BEGIN
 SELECT * INTO w FROM local_identity.production_workspaces WHERE id=p_workspace FOR UPDATE;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(w.episode_id) THEN RAISE EXCEPTION 'Owned current workspace required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.episodes e JOIN local_identity.production_preparation_revisions p ON p.id=w.preparation_revision_id AND p.episode_id=w.episode_id AND p.script_revision_id=w.script_revision_id
  WHERE e.id=w.episode_id AND e.archived_at IS NULL AND e.stage<>'production_completed' AND NOT local_identity.is_historical_episode(e.id)
  AND e.main_script_revision_id=w.script_revision_id AND local_identity.preparation_source_current(p.id)) THEN RAISE EXCEPTION 'Current writable workspace required' USING ERRCODE='55000';END IF;
 IF p_kind IS NULL OR p_kind NOT IN ('narration','bgm','sfx','shot') OR
  (p_kind IN ('narration','shot') AND (p_shot IS NULL OR length(p_shot)=0)) OR
  (p_kind IN ('bgm','sfx') AND p_shot IS NOT NULL) THEN RAISE EXCEPTION 'Invalid stopped content scope' USING ERRCODE='22023';END IF;
 IF p_kind='shot' AND EXISTS(SELECT 1 FROM jsonb_array_elements(w.bindings) b WHERE b->>'shotId'=p_shot) THEN RAISE EXCEPTION 'Shot is still in the current workspace' USING ERRCODE='22023';END IF;
 WITH scoped AS (
  SELECT r.task_id FROM local_identity.workspace_narration_requests r WHERE r.workspace_id=w.id AND r.shot_id=p_shot AND p_kind IN ('narration','shot')
  UNION SELECT r.task_id FROM local_identity.workspace_audio_requests r JOIN local_identity.workspace_audio_preparations p ON p.id=r.preparation_id
   WHERE r.workspace_id=w.id AND (p_kind IN ('bgm','sfx') AND p.kind=p_kind OR p_kind='shot' AND p.shot_id=p_shot)
  UNION SELECT v.task_id FROM local_identity.workspace_visual_candidates v WHERE v.workspace_id=w.id AND p_kind='shot' AND v.shot_id=p_shot
 )
 UPDATE public.tasks t SET status='superseded',invalidated_at=clock_timestamp(),invalidated_reason='当前用途已关闭或删除，不再自动执行。'
 WHERE t.id IN (SELECT task_id FROM scoped) AND t.episode_id=w.episode_id AND t.status='ready' AND t.invalidated_at IS NULL
  AND NOT EXISTS(SELECT 1 FROM local_identity.workspace_narration_submissions s WHERE s.task_id=t.id AND s.outcome IN ('started','received'))
  AND NOT EXISTS(SELECT 1 FROM local_identity.workspace_visual_submissions s WHERE s.task_id=t.id AND s.outcome IN ('started','received'))
  AND NOT EXISTS(SELECT 1 FROM public.paid_generation_reservations r WHERE r.task_id=t.id)
  AND NOT EXISTS(SELECT 1 FROM local_identity.workspace_publication_holds(w.episode_id) h WHERE h.task_id=t.id)
  AND NOT (coalesce(t.last_result#>'{preflight,checks}','[]'::jsonb) @> '[{"check":"provider_result_unknown"}]'::jsonb);
 GET DIAGNOSTICS stopped=ROW_COUNT;
 IF stopped>0 THEN INSERT INTO public.audit_events(account_id,episode_id,event_type,payload,actor_id)
  SELECT e.account_id,e.id,'workspace_queued_content_stopped',jsonb_build_object('workspace_id',w.id,'kind',p_kind,'shot_id',p_shot,'stopped_count',stopped),local_identity.owner_id() FROM public.episodes e WHERE e.id=w.episode_id;END IF;
 RETURN stopped;
END $function$

CREATE OR REPLACE FUNCTION local_identity.sync_production_workspace_shots(p_workspace uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces; p local_identity.production_preparation_revisions; shot record; position integer;
BEGIN
 SELECT * INTO w FROM local_identity.production_workspaces WHERE id=p_workspace;
 IF NOT FOUND OR NOT local_identity.lock_owned_input_episode(w.episode_id) THEN RAISE EXCEPTION 'Owned workspace required' USING ERRCODE='42501';END IF;
 SELECT * INTO w FROM local_identity.production_workspaces WHERE id=p_workspace FOR UPDATE;
 SELECT * INTO p FROM local_identity.production_preparation_revisions WHERE id=coalesce(w.preparation_revision_id,w.storyboard_package_id) AND episode_id=w.episode_id AND script_revision_id=w.script_revision_id;
 IF p.id IS NULL OR NOT local_identity.preparation_source_current(p.id) OR NOT EXISTS(SELECT 1 FROM public.episodes e WHERE e.id=w.episode_id AND e.main_script_revision_id=w.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed' AND NOT local_identity.is_historical_episode(e.id)) THEN
  RAISE EXCEPTION 'Imported current preparation required before editing' USING ERRCODE='40001';
 END IF;
 UPDATE local_identity.production_workspaces SET preparation_revision_id=p.id WHERE id=w.id AND preparation_revision_id IS DISTINCT FROM p.id;
 SELECT coalesce(max(v.position),0) INTO position FROM local_identity.production_shot_versions v WHERE v.preparation_revision_id=p.id;
 FOR shot IN SELECT b->>'shotId' id FROM jsonb_array_elements(w.bindings) WITH ORDINALITY a(b,ordinal) GROUP BY b->>'shotId' ORDER BY min(ordinal) LOOP
  IF shot.id IS NULL OR btrim(shot.id)='' THEN RAISE EXCEPTION 'Stable shot identity required' USING ERRCODE='22023';END IF;
  IF NOT EXISTS(SELECT 1 FROM local_identity.production_shot_versions v WHERE v.preparation_revision_id=p.id AND v.shot_id=shot.id) THEN
   position:=position+1;
   INSERT INTO local_identity.production_shots(episode_id,shot_id) VALUES(w.episode_id,shot.id) ON CONFLICT DO NOTHING;
   INSERT INTO local_identity.production_shot_versions(preparation_revision_id,episode_id,shot_id,position,origin,baseline_text,snapshot) VALUES(p.id,w.episode_id,shot.id,position,'local','',jsonb_build_object('id',shot.id));
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION local_identity.update_media_root_execution(p_id uuid, p_status text, p_progress jsonb, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m local_identity.media_root_migrations;BEGIN
 IF session_user<>'loop_app' OR local_identity.owner_id() IS DISTINCT FROM local_identity.media_root_owner() THEN RAISE EXCEPTION 'Storage Owner required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM local_identity.media_root_migrations WHERE id=p_id AND owner_id=local_identity.owner_id() FOR UPDATE;
 IF NOT FOUND OR m.manifest_sha256<>encode(sha256(convert_to(m.manifest::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'Migration plan proof missing';END IF;
 IF NOT ((p_status='copying' AND m.status IN ('planned','copying','failed') AND (m.manifest->>'canExecute')::boolean) OR (p_status='failed' AND m.status='copying') OR (p_status='rolled_back' AND m.status IN ('planned','copying','failed'))) THEN RAISE EXCEPTION 'Migration state does not permit this operation' USING ERRCODE='55000';END IF;
 UPDATE local_identity.media_root_migrations SET status=p_status,progress=p_progress,error=p_error,updated_at=clock_timestamp() WHERE id=p_id;
END $function$

CREATE OR REPLACE FUNCTION local_identity.use_production_source_track(p_workspace uuid, p_shot text, p_track uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w local_identity.production_workspaces; track public.audio_tracks;
BEGIN
 w:=local_identity.lock_current_production_workspace(p_workspace);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.bindings) b WHERE b->>'shotId'=p_shot) THEN RAISE EXCEPTION 'Current workspace shot required' USING ERRCODE='22023';END IF;
 WITH RECURSIVE basis AS(
  SELECT p.id,p.parent_preparation_revision_id,p.source_format,p.source_reference_id FROM local_identity.production_preparation_revisions p WHERE p.id=w.preparation_revision_id AND p.episode_id=w.episode_id
  UNION SELECT p.id,p.parent_preparation_revision_id,p.source_format,p.source_reference_id FROM local_identity.production_preparation_revisions p JOIN basis b ON p.id=b.parent_preparation_revision_id WHERE p.episode_id=w.episode_id
 ) SELECT a.* INTO track FROM public.audio_tracks a WHERE a.id=p_track AND a.episode_id=w.episode_id AND a.track_kind='source' AND EXISTS(
  SELECT 1 FROM basis p WHERE a.preparation_revision_id=p.id OR a.preparation_revision_id IS NULL AND p.source_format='storyboard/v1' AND a.source_review_package_id=p.source_reference_id);
 IF NOT FOUND THEN RAISE EXCEPTION 'Registered preparation-bound source track required' USING ERRCODE='22023';END IF;
 INSERT INTO local_identity.workspace_narration_inputs(workspace_id,episode_id,preparation_revision_id,shot_id,mode,audio_track_id)
  VALUES(w.id,w.episode_id,w.preparation_revision_id,p_shot,'manual',track.id)
  ON CONFLICT(workspace_id,preparation_revision_id,shot_id) DO UPDATE SET mode=CASE WHEN workspace_narration_inputs.mode='none' THEN 'manual' ELSE workspace_narration_inputs.mode END,audio_track_id=excluded.audio_track_id,updated_at=clock_timestamp();
END $function$

CREATE OR REPLACE FUNCTION local_identity.use_workspace_narration_track(p_episode uuid, p_review uuid, p_shot text, p_track uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE track public.audio_tracks; BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned input required' USING ERRCODE='42501'; END IF;
 SELECT * INTO track FROM public.audio_tracks WHERE id=p_track AND episode_id=p_episode AND track_kind='narration';
 IF NOT FOUND THEN RAISE EXCEPTION 'Registered narration track required' USING ERRCODE='22023'; END IF;
 UPDATE public.shot_preparation_drafts SET current_audio_track_id=track.id,audio_status='ready',source_audio_duration_seconds=track.duration_seconds WHERE episode_id=p_episode AND review_package_id=p_review AND shot_id=p_shot AND audio_mode='source';
END $function$

CREATE OR REPLACE FUNCTION local_identity.use_workspace_source_track(p_episode uuid, p_review uuid, p_shot text, p_track uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE track public.audio_tracks; draft public.shot_preparation_drafts; BEGIN
 IF NOT local_identity.lock_owned_input_episode(p_episode) THEN RAISE EXCEPTION 'Owned input required' USING ERRCODE='42501'; END IF;
 SELECT * INTO track FROM public.audio_tracks WHERE id=p_track AND episode_id=p_episode AND track_kind='source' AND source_review_package_id=p_review;
 IF NOT FOUND THEN RAISE EXCEPTION 'Real registered source track required' USING ERRCODE='22023'; END IF;
 SELECT * INTO draft FROM public.shot_preparation_drafts WHERE episode_id=p_episode AND review_package_id=p_review AND shot_id=p_shot;
 IF draft.id IS NULL THEN PERFORM public.save_shot_preparation_draft(p_episode,p_review,p_shot,'source',coalesce(local_identity.workspace_shot_context(p_episode,p_review,p_shot)->>'scriptSegment',''),false,NULL,NULL,NULL); END IF;
 UPDATE public.shot_preparation_drafts SET audio_mode=CASE WHEN audio_mode='none' THEN 'source' ELSE audio_mode END,current_audio_track_id=track.id,audio_status='ready',source_audio_duration_seconds=track.duration_seconds WHERE episode_id=p_episode AND review_package_id=p_review AND shot_id=p_shot;
END $function$

CREATE OR REPLACE FUNCTION local_identity.validate_production_metric_payload(p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE k text; v jsonb;
BEGIN
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>8192 THEN RAISE EXCEPTION 'Invalid metric payload';END IF;
 FOR k,v IN SELECT entry.key,entry.value FROM jsonb_each(p_payload) AS entry LOOP
  IF NOT k=ANY(ARRAY['task_id','attempt','request_id','request_kind','request_role','response_status','phase','http_status','operation','request_key','reason_code','workspace_id','candidate_id','source_task_id','related_task_id','target_id','change_reason','project_revision','project_sha256','source_kind','confirmation_id','estimate_version','estimated_cents','currency','source_currency','conversion_rate','rate_version','estimate_known','retry_of_task_id','paid_cents','billing_evidence_id']) THEN RAISE EXCEPTION 'Unexpected metric payload field';END IF;
  IF jsonb_typeof(v) NOT IN ('null','string','number','boolean') THEN RAISE EXCEPTION 'Metric payload scalars required';END IF;
  IF jsonb_typeof(v)='string' AND (length(v#>>'{}')>200 OR (v#>>'{}') !~ '^[A-Za-z0-9:_./-]*$') THEN RAISE EXCEPTION 'Metric payload machine identifiers required';END IF;
  IF k IN ('attempt','project_revision','estimated_cents','paid_cents') AND v<>'null'::jsonb AND (jsonb_typeof(v)<>'number' OR (v#>>'{}') !~ '^[0-9]{1,14}$') THEN RAISE EXCEPTION 'Metric nonnegative integer required';END IF;
  IF k='http_status' AND v<>'null'::jsonb AND ((v#>>'{}') !~ '^[1-5][0-9]{2}$' OR jsonb_typeof(v)<>'number') THEN RAISE EXCEPTION 'Invalid HTTP status';END IF;
  IF k='operation' AND v<>'null'::jsonb AND v#>>'{}' NOT IN ('create','poll','download') THEN RAISE EXCEPTION 'Invalid request operation';END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION local_identity.validate_production_metric_scope(p_episode uuid, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE k text; ref uuid;
BEGIN
 FOREACH k IN ARRAY ARRAY['task_id','source_task_id','related_task_id','retry_of_task_id'] LOOP
  IF p_payload->>k IS NOT NULL THEN
   ref:=(p_payload->>k)::uuid;
   IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=ref AND episode_id=p_episode) THEN RAISE EXCEPTION 'Metric task scope mismatch' USING ERRCODE='42501';END IF;
  END IF;
 END LOOP;
 IF p_payload->>'workspace_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM local_identity.production_workspaces WHERE id=(p_payload->>'workspace_id')::uuid AND episode_id=p_episode) THEN RAISE EXCEPTION 'Metric workspace scope mismatch' USING ERRCODE='42501';END IF;
 IF p_payload->>'confirmation_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM local_identity.workspace_call_confirmations WHERE id=(p_payload->>'confirmation_id')::uuid AND episode_id=p_episode AND consumed_at IS NOT NULL) THEN RAISE EXCEPTION 'Metric confirmation scope mismatch' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION local_identity.workspace_audio_task_current(p_task uuid, p_attempt integer, p_lease uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request local_identity.workspace_audio_requests; BEGIN
 PERFORM public.refresh_worker_task_lease(p_task,p_attempt,p_lease);
 SELECT * INTO request FROM local_identity.workspace_audio_requests WHERE task_id=p_task;
 IF NOT FOUND THEN RETURN true; END IF;
 IF NOT local_identity.workspace_task_preparation_current(p_task,request.workspace_id) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM local_identity.workspace_audio_preparations p JOIN local_identity.production_workspaces w ON w.id=p.workspace_id JOIN public.episodes e ON e.id=w.episode_id WHERE p.id=request.preparation_id AND p.task_id=p_task AND p.input_fingerprint=request.input_fingerprint AND e.main_script_revision_id=w.script_revision_id AND e.archived_at IS NULL AND e.stage<>'production_completed') THEN RETURN false; END IF;
 RETURN request.authorization_hash IS NULL OR EXISTS(SELECT 1 FROM local_identity.workspace_production_authorizations p JOIN public.episodes e ON e.id=p.episode_id WHERE p.episode_id=request.episode_id AND p.enabled AND p.authorized_at IS NOT NULL AND p.authorization_hash=request.authorization_hash AND p.script_revision_id=e.main_script_revision_id);
END $function$

CREATE OR REPLACE FUNCTION loop_internal.bump_episode_read_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb; eid uuid; seen text[]:='{}'; sources jsonb[]; item text; identity text;
begin
 if TG_OP='INSERT' then sources:=array[to_jsonb(NEW)];
 elsif TG_OP='DELETE' then sources:=array[to_jsonb(OLD)];
 else sources:=array[to_jsonb(OLD),to_jsonb(NEW)]; end if;
 foreach source in array sources loop
  eid:=null;
  case TG_ARGV[1]
   when 'direct' then eid:=(source->>'episode_id')::uuid;
   when 'review' then select episode_id into eid from public.review_packages where id=(source->>'review_package_id')::uuid;
   when 'audio' then select episode_id into eid from public.audio_tracks where id=(source->>'audio_track_id')::uuid;
   when 'task' then select episode_id into eid from public.tasks where id=(source->>'task_id')::uuid;
  end case;
  item:=coalesce(source->>'id',(source->>'review_package_id')||'/'||(source->>'member_key'));
  identity:=eid::text||'/'||item;
  if eid is null or identity=any(seen) or not exists(select 1 from public.episodes where id=eid) then continue;end if;
  seen:=array_append(seen,identity);
  -- Each business row has its own counter; tombstones survive deletion.
  -- No shared episode/section write lock that could invert Worker lock order.
  insert into public.episode_read_revisions(episode_id,section,item_id) values(eid,TG_ARGV[0],item)
   on conflict(episode_id,section,item_id) do update set revision=public.episode_read_revisions.revision+1;
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.activate_blueprint_version(p_account_id uuid, p_blueprint_version_id uuid)
 RETURNS public.account_blueprint_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  membership_role public.member_role;
  activated_blueprint public.account_blueprint_versions;
begin
  select role into membership_role
  from public.account_memberships
  where account_id = p_account_id and user_id = local_identity.owner_id();
  if membership_role is distinct from 'owner' then
    raise exception 'Owner membership is required to activate a blueprint version' using errcode = '42501';
  end if;
  select * into activated_blueprint
  from public.account_blueprint_versions
  where account_id = p_account_id and id = p_blueprint_version_id
  for update;
  if not found then
    raise exception 'Blueprint version does not belong to this account' using errcode = '22023';
  end if;
  if activated_blueprint.archived_at is not null then
    raise exception 'Archived blueprint versions must be restored before activation' using errcode = '22023';
  end if;
  update public.account_blueprint_versions
  set is_active = false
  where account_id = p_account_id and is_active;
  update public.account_blueprint_versions
  set is_active = true
  where account_id = p_account_id and id = p_blueprint_version_id
  returning * into activated_blueprint;
  update public.accounts set current_blueprint_version_id = p_blueprint_version_id where id = p_account_id;
  insert into public.audit_events (account_id, event_type, payload, actor_id)
  values (p_account_id, 'blueprint_version_activated', jsonb_build_object('blueprint_version_id', p_blueprint_version_id, 'version', activated_blueprint.version), local_identity.owner_id());
  return activated_blueprint;
end;
$function$

CREATE OR REPLACE FUNCTION public.advance_qc_only_review_render()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pre_render_package public.review_packages; updated_episode public.episodes;
begin
  if new.task_type <> 'generate_review_render' or new.status <> 'ready' then return new; end if;
  select * into pre_render_package from public.review_packages package
  where package.id = (new.input_snapshot #>> '{review_render,pre_render_review_package_id}')::uuid
    and package.stage = 'production_ready' and package.invalidated_at is null
    and package.context_snapshot ->> 'approval_mode' = 'qc_only';
  if not found then return new; end if;
  update public.episodes set stage = 'render_ready', updated_at = now()
  where id = new.episode_id and stage = 'production_ready' returning * into updated_episode;
  if not found then return new; end if;
  insert into public.state_transitions (episode_id,from_stage,to_stage,reason,actor_id)
  values (updated_episode.id,'production_ready','render_ready','冻结媒体已自动进入 OpenChatCut 审核渲染。',null);
  insert into public.audit_events (account_id,episode_id,event_type,payload,actor_id)
  values (updated_episode.account_id,updated_episode.id,'review_render_auto_queued',jsonb_build_object('task_id',new.id,'pre_render_review_package_id',pre_render_package.id),null);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_current_qc_review_issue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare selected_package public.review_packages; selected_episode public.episodes; selected_task public.tasks;
begin
  select * into selected_package from public.review_packages package
  where package.id = new.review_package_id and package.stage = 'qc_review' and package.invalidated_at is null;
  if not found then raise exception 'Current QC review package is required' using errcode = '22023'; end if;
  select * into selected_episode from public.episodes episode where episode.id = selected_package.episode_id and episode.stage = 'qc_review' for update;
  if not found or exists (select 1 from public.review_packages package where package.episode_id = selected_package.episode_id and package.stage = 'qc_review' and package.invalidated_at is null and package.revision_number > selected_package.revision_number) then raise exception 'QC review package is no longer current' using errcode = '22023'; end if;
  if new.status = 'revision_requested' then
    select task.* into selected_task from public.pre_render_review_members member join public.tasks task on task.id = member.source_task_id
    where member.review_package_id = (selected_package.context_snapshot ->> 'pre_render_review_package_id')::uuid and member.member_key = new.member_key;
    if not found or selected_task.provider = 'manual_upload' or selected_task.input_snapshot ? 'manual_source' then raise exception 'This QC member must be replaced through its original uploaded material' using errcode = '22023'; end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_prompt_context_to_worker_task_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  selected_episode public.episodes;
  blueprint_policy jsonb;
  selected_series_version public.series_versions;
  context jsonb;
begin
  if new.task_package is null or jsonb_typeof(new.task_package) <> 'object' then return new; end if;
  if coalesce(new.task_package #>> '{episode,id}', new.task_package ->> 'episode_id', '') = '' then return new; end if;
  select episode.* into selected_episode from public.episodes episode where episode.id = coalesce(new.task_package #>> '{episode,id}', new.task_package ->> 'episode_id')::uuid;
  if not found then return new; end if;
  select policy into blueprint_policy from public.account_blueprint_versions where id = selected_episode.blueprint_version_id;
  select series_version.* into selected_series_version from public.series_versions series_version where series_version.id = selected_episode.series_version_id and series_version.account_id = selected_episode.account_id;

  context := jsonb_strip_nulls(jsonb_build_object(
    'version', 'prompt-context/v1',
    'blueprint_version_id', selected_episode.blueprint_version_id,
    'series_version_id', selected_series_version.id,
    'account_hard_constraints', jsonb_strip_nulls(jsonb_build_object(
      'approval_gates', blueprint_policy -> 'approval_gates',
      'allowed_tools', blueprint_policy -> 'allowed_tools',
      'asset_root', blueprint_policy -> 'asset_root',
      'restrictions', blueprint_policy -> 'restrictions',
      'publishing', blueprint_policy -> 'publishing'
    )),
    'account_defaults', jsonb_strip_nulls(jsonb_build_object(
      'positioning', blueprint_policy -> 'positioning',
      'audience', blueprint_policy -> 'audience',
      'tone', blueprint_policy -> 'tone',
      'brand_voice', blueprint_policy -> 'brand_voice',
      'visual_style', blueprint_policy -> 'visual_style',
      'subtitle_style', blueprint_policy -> 'subtitle_style',
      'language', blueprint_policy -> 'language',
      'creative_rules', blueprint_policy -> 'creative_rules'
    )),
    'series_baseline', case when selected_series_version.id is null then null else jsonb_build_object('version_id', selected_series_version.id, 'version', selected_series_version.version, 'rules', selected_series_version.rules) end,
    'episode_input', jsonb_strip_nulls(jsonb_build_object(
      'commission', new.task_package -> 'commission',
      'script_revision', new.task_package -> 'script_revision',
      'input_artifacts', new.task_package -> 'input_artifacts',
      'shot', new.task_package -> 'shot',
      'media', new.task_package -> 'media'
    )),
    'review_feedback', new.task_package -> 'review_feedback'
  ));
  new.task_package := jsonb_set(new.task_package, '{prompt_context}', context || jsonb_build_object('hash', md5(context::text)), true);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.block_exhausted_a_roll_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  blocker_detail text;
begin
  if new.task_type <> 'generate_a_roll'
    or new.status <> 'failed'
    or new.attempt < new.max_attempts then
    return new;
  end if;

  blocker_detail := coalesce(nullif(btrim(new.last_result #>> '{retry,reason}'), ''), 'A-roll Worker 在所有冻结尝试中均失败。');
  update public.tasks
  set status = 'blocked',
      last_result = coalesce(new.last_result, '{}'::jsonb) || jsonb_build_object(
        'status', 'blocked',
        'blockers', jsonb_build_array(jsonb_build_object('code', 'a_roll_retries_exhausted', 'detail', blocker_detail)),
        'retry', jsonb_build_object('shouldRetry', false, 'reason', blocker_detail),
        'nextStep', '由 Owner 检查冻结执行器或配置后创建新的任务。'
      )
  where id = new.id;
  insert into public.audit_events (account_id, episode_id, event_type, payload, actor_id)
  select episode.account_id, episode.id, 'a_roll_task_blocked', jsonb_build_object('task_id', new.id, 'shot_id', new.input_snapshot #>> '{shot,id}', 'code', 'a_roll_retries_exhausted', 'detail', blocker_detail), null
  from public.episodes episode where episode.id = new.episode_id;
  return new;
end;
$function$

