  where id = draft_id and pending_source_audio_task_id = new.id and new.status in ('ready', 'running', 'failed','blocked');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_shot_tts_task_after_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  draft_id uuid;
  failure_reason text;
begin
  if new.task_type <> 'generate_narration' then return new; end if;
  draft_id := nullif(new.input_snapshot #>> '{shot_preparation,draft_id}', '')::uuid;
  if draft_id is null then return new; end if;
  failure_reason := coalesce(new.last_result #>> '{blockers,0,detail}', new.last_result #>> '{retry,reason}', 'TTS 任务失败，请重试。');
  update public.shot_preparation_drafts
  set audio_status = case when new.status = 'failed' then 'failed' else 'running' end,
      tts_error = case when new.status = 'failed' then failure_reason else null end,
      updated_at = now()
  where id = draft_id and pending_tts_task_id = new.id and new.status in ('ready', 'running', 'failed');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_episode(p_episode_id uuid, p_to_stage public.episode_stage, p_reason text)
 RETURNS public.episodes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_episode public.episodes;
  previous_stage public.episode_stage;
  membership_role public.member_role;
  owner_approval_stages public.episode_stage[] := array['script_approved','visual_approved','storyboard_approved','render_ready','qc_passed','publish_ready','published']::public.episode_stage[];
  review_stages public.episode_stage[] := array['script_review','visual_review','storyboard_review','production_ready','qc_review','publishing_review']::public.episode_stage[];
begin
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'Transition reason is required' using errcode = '22023'; end if;
  select * into current_episode from public.episodes where id = p_episode_id for update;
  if not found then raise exception 'Episode % does not exist', p_episode_id using errcode = 'P0002'; end if;
  if not public.is_allowed_episode_transition(current_episode.stage, p_to_stage) then raise exception 'Invalid transition from % to %', current_episode.stage, p_to_stage using errcode = '22023'; end if;
  select role into membership_role from public.account_memberships where account_id = current_episode.account_id and user_id = local_identity.owner_id();
  if membership_role is null then raise exception 'No membership for this account' using errcode = '42501'; end if;
  if (p_to_stage = any(owner_approval_stages) or current_episode.stage = any(review_stages)) and membership_role <> 'owner' then raise exception 'Owner approval is required for this review decision' using errcode = '42501'; end if;
  if p_to_stage = 'qc_passed' and exists (select 1 from public.qc_review_issues issue where issue.review_package_id = (select package.id from public.review_packages package where package.episode_id = p_episode_id and package.stage = 'qc_review' and package.invalidated_at is null order by package.revision_number desc limit 1) and issue.severity = 'blocking' and issue.status = 'open') then raise exception 'Open blocking QC issues must be resolved before approval' using errcode = '22023'; end if; if not public.has_required_artifacts(p_episode_id, p_to_stage) then raise exception 'Required artifacts are missing for %', p_to_stage using errcode = '22023'; end if;
  -- ADR-0065: generated-script events cannot succeed without their retired projections.
  IF current_episode.stage IN ('brief_draft','script_draft','script_review')
    OR p_to_stage IN ('brief_draft','script_draft','script_review','script_approved') THEN
    RAISE EXCEPTION 'Generated script transitions are retired; confirm an uploaded script in the current workspace' USING ERRCODE='0A000';
  END IF;
  previous_stage := current_episode.stage;
  update public.episodes set stage = p_to_stage, updated_at = now() where id = p_episode_id returning * into current_episode;
  insert into public.state_transitions (episode_id, from_stage, to_stage, reason, actor_id) values (p_episode_id, previous_stage, p_to_stage, btrim(p_reason), local_identity.owner_id());
  if p_to_stage = any(owner_approval_stages) then
    insert into public.approvals (episode_id, stage, decision, reason, actor_id) values (p_episode_id, p_to_stage, 'approved', btrim(p_reason), local_identity.owner_id());
  elsif previous_stage = any(review_stages) then
    insert into public.approvals (episode_id, stage, decision, reason, actor_id) values (p_episode_id, previous_stage, 'changes_requested', btrim(p_reason), local_identity.owner_id());
  end if;
  insert into public.audit_events (account_id, episode_id, event_type, payload, actor_id) values (current_episode.account_id, p_episode_id, 'stage_transition', jsonb_build_object('to_stage', p_to_stage, 'reason', btrim(p_reason)), local_identity.owner_id());
  return current_episode;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_current_blueprint(p_account_id uuid, p_policy jsonb)
 RETURNS public.account_blueprint_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.accounts;b public.account_blueprint_versions;next_version integer;
BEGIN
 IF jsonb_typeof(p_policy) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Blueprint policy must be a JSON object' USING ERRCODE='22023';END IF;
 SELECT account.* INTO a FROM public.accounts account JOIN public.account_memberships m ON m.account_id=account.id AND m.user_id=local_identity.owner_id() AND m.role='owner' WHERE account.id=p_account_id FOR UPDATE OF account;
 IF NOT FOUND THEN RAISE EXCEPTION 'Owner membership is required to update a blueprint' USING ERRCODE='42501';END IF;
 SELECT * INTO b FROM public.account_blueprint_versions WHERE id=a.current_blueprint_version_id AND account_id=a.id AND is_active AND archived_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'The current blueprint is unavailable' USING ERRCODE='22023';END IF;
 p_policy:=public.creative_account_rules(p_policy);
 IF b.policy IS DISTINCT FROM p_policy AND (EXISTS(SELECT 1 FROM public.episodes WHERE blueprint_version_id=b.id) OR EXISTS(SELECT 1 FROM local_identity.episode_creation_intents WHERE blueprint_version_id=b.id AND result IS NULL)) THEN
  SELECT coalesce(max(version),0)+1 INTO next_version FROM public.account_blueprint_versions WHERE account_id=a.id;
  UPDATE public.account_blueprint_versions SET is_active=false,archived_at=now(),is_snapshot=true WHERE id=b.id;
  INSERT INTO public.account_blueprint_versions(account_id,version,policy,is_active) VALUES(a.id,next_version,p_policy,true) RETURNING * INTO b;
  UPDATE public.accounts SET current_blueprint_version_id=b.id WHERE id=a.id;
 ELSIF b.policy IS DISTINCT FROM p_policy THEN
  UPDATE public.account_blueprint_versions SET policy=p_policy WHERE id=b.id RETURNING * INTO b;
 END IF;
 INSERT INTO public.audit_events(account_id,event_type,payload,actor_id) VALUES(a.id,'blueprint_policy_updated',jsonb_build_object('blueprint_version_id',b.id,'version',b.version),local_identity.owner_id());RETURN b;
END $function$

CREATE OR REPLACE FUNCTION public.update_episode_title(p_episode_id uuid, p_title text)
 RETURNS public.episodes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_episode public.episodes;
  updated_episode public.episodes;
  next_title text := btrim(coalesce(p_title, ''));
begin
  select episode.* into current_episode
  from public.episodes episode
  join public.account_memberships membership
    on membership.account_id = episode.account_id
   and membership.user_id = local_identity.owner_id()
   and membership.role = 'owner'
  where episode.id = p_episode_id
  for update of episode;
  if not found then
    raise exception 'Owner membership is required to update an episode title' using errcode = '42501';
  end if;

  update public.episodes
  set title = next_title, updated_at = now()
  where id = p_episode_id
  returning * into updated_episode;

  if current_episode.title is distinct from updated_episode.title then
    insert into public.audit_events (account_id, episode_id, event_type, payload, actor_id)
    values (
      current_episode.account_id,
      current_episode.id,
      'episode_title_updated',
      jsonb_build_object('previous_title', current_episode.title, 'title', updated_episode.title),
      local_identity.owner_id()
    );
  end if;
  return updated_episode;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_external_connection(p_connection_id uuid, p_name text, p_description text)
 RETURNS public.external_connections
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare updated_connection public.external_connections;
begin
  if local_identity.owner_id() is null then raise exception 'Owner login is required' using errcode = '42501'; end if;
  if char_length(trim(p_name)) not between 1 and 100 or char_length(coalesce(p_description, '')) > 500 then raise exception 'Connection name or description is invalid' using errcode = '22023'; end if;
  update public.external_connections set name = trim(p_name), description = trim(coalesce(p_description, '')) where id = p_connection_id and created_by = local_identity.owner_id() returning * into updated_connection;
  if not found then raise exception 'External connection does not exist' using errcode = 'P0002'; end if;
  return updated_connection;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_blueprint_external_connections()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k text; ref text; expected_provider text; expected_adapter text;
begin
 IF TG_OP='INSERT' AND NEW.is_snapshot AND EXISTS(SELECT 1 FROM public.account_blueprint_versions b WHERE b.account_id=NEW.account_id AND b.policy=NEW.policy) THEN RETURN NEW; END IF;
 -- Exact retirement-only edit: no other policy fields or references can change.
 if TG_OP='UPDATE' and new.policy<>old.policy and new.policy=local_identity.without_retired_provider_capabilities(old.policy) then return new; end if;
 -- Archive an exact copy of this Owner current policy; this grants no execution.
 if new.is_snapshot and not new.is_active and new.archived_at is not null and exists(
  select 1 from public.accounts a join public.account_blueprint_versions b on b.id=a.current_blueprint_version_id
  join public.account_memberships m on m.account_id=a.id and m.user_id=local_identity.owner_id() and m.role='owner'
  where a.id=new.account_id and b.policy=new.policy
 ) then return new; end if;
 foreach k in array array['a_roll','b_roll','soundtrack','narration','static_visual'] loop
  ref:=nullif(btrim(new.policy #>> array[k,'credential_ref']),'');
  if ref is null then continue; end if;
  expected_provider:=new.policy #>> array[k,'executor','provider']; expected_adapter:=new.policy #>> array[k,'executor','adapter'];
  if not coalesce(case k
   when 'a_roll' then (expected_provider,expected_adapter) in (('bailian','wan_video'),('volcengine','seedance_video'),('minimax','minimax_video'),('kling','kling_video'))
   when 'b_roll' then (expected_provider,expected_adapter) in (('bailian','wan_video'),('pexels','pexels_video'),('volcengine','seedance_video'),('minimax','minimax_video'),('kling','kling_video'))
   when 'soundtrack' then (expected_provider,expected_adapter)=('freesound','freesound_preview')
   when 'narration' then (expected_provider,expected_adapter) in (('volcengine_tts','volcengine_tts'))
   when 'static_visual' then (expected_provider,expected_adapter) in (('openai','openai_images')) end,false)
  then raise exception '% uses an incompatible connection Adapter',k using errcode='22023'; end if;
  if ref !~ '^[0-9a-f-]{36}$' or not exists (
   select 1 from public.external_connection_versions v join public.external_connections c on c.id=v.connection_id
   join public.account_memberships m on m.account_id=new.account_id and m.user_id=c.created_by and m.role='owner'
   where v.id=ref::uuid and c.created_by=local_identity.owner_id() and c.current_version_id=v.id and v.revoked_at is null
   and v.provider=expected_provider and v.adapter=expected_adapter and public.connection_version_is_verified(v.id)
  ) then raise exception '% requires this Owner current verified connection',k using errcode='22023'; end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.worker_resource_limits(p_input jsonb, p_capacity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare runtime jsonb:=public.worker_runtime_constraints(p_input,p_capacity);
 provider text:=coalesce(nullif(p_input#>>'{executor,provider}',''),p_input->>'provider','unknown');
 adapter text:=coalesce(nullif(p_input#>>'{executor,adapter}',''),p_input#>>'{media,adapter}','default');
 credential text:=nullif(p_input->>'credential_ref',''); limits jsonb;
begin
 limits:=jsonb_build_array(
  jsonb_build_object('key','provider:'||provider,'limit',least(coalesce((runtime#>>'{source,provider_or_connection_limit}')::integer,(runtime#>>'{source,adapter_safety_limit}')::integer),p_capacity)),
  jsonb_build_object('key','adapter:'||provider||':'||adapter,'limit',(runtime->>'effective_concurrency')::integer),
  jsonb_build_object('key','connection:'||coalesce(credential,provider||':'||adapter||':shared'),'limit',(runtime->>'effective_concurrency')::integer)
 );
 if provider in ('ffmpeg','openchatcut','whisperx') then
  limits:=limits||jsonb_build_array(jsonb_build_object('key','host:cpu','limit',1));
 end if;
 if provider in ('ffmpeg','openchatcut') then
  limits:=limits||jsonb_build_array(jsonb_build_object('key','host:render','limit',1));
 end if;
 if provider in ('pexels','freesound') then
  limits:=limits||jsonb_build_array(jsonb_build_object('key','host:download','limit',least(3,p_capacity)));
 end if;
 select jsonb_agg(jsonb_build_object('key',r.value->>'key','limit',
   least((r.value->>'limit')::integer,coalesce(c.capacity,(r.value->>'limit')::integer))) order by r.value->>'key')
 into limits from jsonb_array_elements(limits) r
 left join public.worker_resource_ceilings c on c.resource_key=r.value->>'key';
 return limits;
end $function$

CREATE OR REPLACE FUNCTION public.worker_runtime_constraints(p_input_snapshot jsonb, p_worker_capacity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  provider text := coalesce(nullif(btrim(p_input_snapshot #>> '{executor,provider}'), ''), nullif(btrim(p_input_snapshot ->> 'provider'), ''), 'unknown');
  adapter text := coalesce(nullif(btrim(p_input_snapshot #>> '{executor,adapter}'), ''), nullif(btrim(p_input_snapshot #>> '{media,adapter}'), ''), 'default');
  provider_limit integer;
  adapter_limit integer;
  worker_limit integer := case when p_worker_capacity > 0 then p_worker_capacity else 1 end;
  credential_key text := coalesce(nullif(btrim(p_input_snapshot ->> 'credential_ref'), ''), 'shared');
  group_key text;
begin
  adapter_limit := case adapter
    when 'pexels_video' then 3
    when 'volcengine_tts' then 2
    when 'freesound_preview' then 1
    when 'openai_images' then 1
    when 'openchatcut_card_video' then 1
    else 1
  end;
  provider_limit := case
    when provider = 'pexels' and adapter = 'pexels_video' then 3
    when provider = 'volcengine_tts' and adapter = 'volcengine_tts' then 2
    else null
  end;
  group_key := format('%s:%s:%s', provider, adapter, credential_key);
  return jsonb_build_object(
    'version', 'worker-runtime/v1',
    'concurrency_group', group_key,
    'effective_concurrency', least(coalesce(provider_limit, adapter_limit), adapter_limit, worker_limit),
    'source', jsonb_build_object(
      'provider_or_connection_limit', provider_limit,
      'adapter_safety_limit', adapter_limit,
      'worker_capacity', worker_limit
    )
  );
end;
$function$
